// ---- fakePipeline: the EXTERNAL agentic-job seam (agenticJobAccess) ---

// fakePipeline stands in for the claude-code-action DESIGN job at the WIRE seam. It
// records every submitted spec (so tests assert the ProjectID / artifact_kind /
// branch in DispatchInputs and the DISTINCT idempotency key per dispatch) and serves
// a scripted terminal phase per observe. By default a submitted job is observed
// PipelineSucceeded immediately (the job "ran, committed the JSON, CI went green").
type fakePipeline struct {
	mu sync.Mutex

	// phases is the scripted terminal phase per dispatch in order; once exhausted the
	// last entry repeats. Empty == always PipelineSucceeded.
	phases []pipelinePhase
	// diagnostic is attached to a failed/cancelled observation.
	diagnostic string
	// runURL is attached to EVERY observation (the RA's resolved run URL — the real RA
	// surfaces it on live runs for the generating deep-link and on terminal failures
	// for the failed card's "why" pointer).
	runURL string
	// submitErr, when non-nil, makes SubmitAgenticJob FAIL (a terminal
	// dispatch-rejection fault, e.g. GitHub 422 → ContractMisuse) — the F15 gap-2a path.
	submitErr error

	submits []submitRecord
	// handleByName tracks the phase to return for each issued handle.
	handlePhase map[string]pipelinePhase
	nextID      int
	// onObserve, when set, is invoked on each observe (used to mutate the read-back
	// state mid-flight, e.g. clearing a critique note so the PM-revise loop terminates).
	onObserve func()
	// episodes is the SP1 capture-seam script: one entry per observe call, consumed in
	// order; once exhausted the LAST entry repeats. nil entries mirror an observation
	// with no mined summary (the GitHub-Actions arm, or a cancelled run whose subprocess
	// has not unwound yet). An empty script means "never any episode".
	episodes []*agenticjob.EpisodeSummary
	observes int

	// rec, when set, is the lifecycle-shape oracle's observation side (stage 4b1 Task 1).
	rec *shapeRecorder
}

// Stage 4a: ONE copy now serves the systemDesign+projectDesign rails (byte-identical
// twins, collapsed by the package merge — arch.CheckFileLayout allows one impl file and one test file).
type submitRecord struct {
	projectID      ProjectID
	idempotencyKey fwra.IdempotencyKey
	dispatchInputs map[string]string
	// targetRepo / workflowFile capture the per-project-design-dispatch override so the
	// proof can assert the dispatch hit the per-project repo + aiarch-design.yml (not the
	// central construction repo + aiarch-construct.yml). Empty == dormant-rail fallback.
	targetRepo   string
	workflowFile string
}

// SubmitAgenticJob implements the GENERATED agenticjob contract seam
// (the submit invoker reaches it via the registered genActivities). The idempotency key is
// now stamped INSIDE the generated activity (genActivityIdempotencyKey) and arrives on the
// fwra call Context; the RepoRef→RepoTarget decode happens workflow-side (dispatchDesignJob),
// so spec.TargetRepo is the DECODED {Owner,Name} — recorded here as "owner/name".
func (p *fakePipeline) SubmitAgenticJob(rc fwra.Context, spec agenticjob.PipelineSpec) (agenticjob.PipelineHandle, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	targetRepo := ""
	if !agenticjob.RepoTargetIsZero(spec.TargetRepo) {
		targetRepo = spec.TargetRepo.Owner + "/" + spec.TargetRepo.Name
	}
	if p.submitErr != nil {
		// Record the attempt so a test can still assert the dispatch was tried, then fail
		// the submit — the terminal dispatch-rejection path (the whole round-trip errors).
		p.submits = append(p.submits, submitRecord{projectID: ProjectID(spec.ProjectID), idempotencyKey: rc.IdempotencyKey, dispatchInputs: spec.DispatchInputs})
		return agenticjob.PipelineHandle(""), p.submitErr
	}
	idx := len(p.submits)
	p.submits = append(p.submits, submitRecord{
		projectID:      ProjectID(spec.ProjectID),
		idempotencyKey: rc.IdempotencyKey,
		dispatchInputs: spec.DispatchInputs,
		targetRepo:     targetRepo,
		workflowFile:   spec.WorkflowFile,
	})
	phase := pipelineSucceeded
	if len(p.phases) > 0 {
		if idx < len(p.phases) {
			phase = p.phases[idx]
		} else {
			phase = p.phases[len(p.phases)-1]
		}
	}
	p.nextID++
	name := "design-run/" + uuid.NewString()
	p.handlePhase[name] = phase
	// The shape oracle's dispatch record (stage 4b1 Task 1). A design dispatch carries no
	// `phase` input — its bag is artifact_kind + job_mode + command — so the COMMAND is
	// what is recorded here; a design task's start is recorded from its review round
	// instead, which is the only per-task landmark this rail actually has.
	if p.rec != nil {
		p.rec.jobDispatched(spec.DispatchInputs[dispatchInputCommand])
	}
	return agenticjob.PipelineHandle(name), nil
}

// submitCount returns how many dispatches have been submitted so far (thread-safe), so a
// ledger fake can record the dispatch count at seed time and a test can assert ordering.
func (p *fakePipeline) submitCount() int {
	p.mu.Lock()
	defer p.mu.Unlock()
	return len(p.submits)
}

func (p *fakePipeline) ObserveAgenticJob(_ fwra.Context, handle agenticjob.PipelineHandle) (agenticjob.PipelineObservation, error) {
	p.mu.Lock()
	phase := p.handlePhase[agenticjob.PipelineHandleString(handle)]
	hook := p.onObserve
	diag := p.diagnostic
	runURL := p.runURL
	p.mu.Unlock()
	if hook != nil {
		hook()
	}
	obs := agenticjob.PipelineObservation{Phase: neutralToRAPhase(phase)}
	// Mirror the real RA: the resolved run URL rides on EVERY observation (live runs
	// power the generating deep-link; terminal failures power the failed card).
	obs.RunURL = runURL
	if phase == pipelineFailed || phase == pipelineCancelled {
		obs.Diagnostic = diag
	}
	obs.Episode = p.nextEpisode()
	return obs, nil
}

// nextEpisode serves the capture-seam script: entry N for observe N, the last entry
// repeating once the script is exhausted (mirroring the real RA, whose mined summary is
// stable once it lands).
func (p *fakePipeline) nextEpisode() *agenticjob.EpisodeSummary {
	p.mu.Lock()
	defer p.mu.Unlock()
	if len(p.episodes) == 0 {
		return nil
	}
	i := p.observes
	p.observes++
	if i >= len(p.episodes) {
		i = len(p.episodes) - 1
	}
	return p.episodes[i]
}

// CancelAgenticJob satisfies the contract; the design draft path never cancels.
func (p *fakePipeline) CancelAgenticJob(_ fwra.Context, _ agenticjob.PipelineHandle) error {
	return nil
}

// neutralToRAPhase maps this Manager's neutral scripted phase onto the RA phase the
// generated observe activity returns (the inverse of designPipelinePhase).
func neutralToRAPhase(p pipelinePhase) agenticjob.PipelinePhase {
	switch p {
	case pipelinePending:
		return agenticjob.PhasePending
	case pipelineRunning:
		return agenticjob.PhaseRunning
	case pipelineSucceeded:
		return agenticjob.PhaseSucceeded
	case pipelineFailed:
		return agenticjob.PhaseFailed
	case pipelineCancelled:
		return agenticjob.PhaseCancelled
	default:
		return agenticjob.PhasePending
	}
}

var _ agenticjob.AgenticJobAccess = (*fakePipeline)(nil)

// ---- helpers ----------------------------------------------------------------

// Stage 4a: ONE copy now serves the systemDesign+projectDesign+construction rails (byte-identical
// twins, collapsed by the package merge — arch.CheckFileLayout allows one impl file and one test file).
// registerGenActivities registers the GENERATED RA activities (projectState read-version /
// advance-phase, pipeline submit/observe/cancel, the six rail verbs, syncManagedScaffold,
// and — since B10 — the eight designSessionAccess verbs the migrated call sites now reach,
// including the envelope-parameter Stage op) under their contract names — mirrors what
// RegisterWorker threads via genActivities (worker.gen.go). Pipeline / rail may be nil for
// tests that never dispatch; the registered method values are only invoked when the
// workflow reaches them.
//
// The designSessionAccess ops are backed by projectstate.NewDesignSessionAccess(ps) — the
// REAL production wrapper (projectstate/designsession.go), not a hand-rolled test double —
// so every workflow test exercises the actual forward-to-base + provenance capability
// check the RA runs, not a re-implementation of it. ps must be non-nil; the generated
// ProjectStateAccess contract requires every branch/ledger/reconcile verb unconditionally
// (C2 fold, code-health-phase-a), so a test's fake (e.g. gitrail_test.go's
// branchAwareFakeProjectState, gitrail_proof_test.go's seqProjectState) simply OVERRIDES
// the verbs it wants branch/ledger-aware behavior for — no separate registration or
// capability opt-in needed.
// fakeEpisodes is the episodeAccess test double: it RECORDS every appended record and
// counts every attempt, so a test can assert both what was written and how many times the
// append was retried. failAlways fails every attempt (the ledger-is-down case); failN
// fails only the first N (the transient-stumble case the bounded retry exists for).
//
// It HONOURS the call context. The production LocalFS/NoOp realisations happen to ignore
// it, but a double that ignores it too would silently bless an append handed an
// already-cancelled context — exactly the bug the answer-watch's fresh append budget
// exists to prevent, and one no test could otherwise see.
type fakeEpisodes struct {
	mu         sync.Mutex
	appended   []episode.EpisodeRecord
	attempts   int
	failN      int
	failAlways bool

	// listRecords/listErr back ListEpisodes (Task 9 facet reads); lastQuery
	// captures the query the manager actually issued, for TargetRef-semantics
	// assertions.
	listRecords []episode.EpisodeRecord
	listErr     error
	lastQuery   episode.EpisodeQuery

	// traceEvents/traceErr back ReadTraceEvents; lastTrace* captures the args
	// the manager actually issued.
	traceEvents        []json.RawMessage
	traceErr           error
	lastTraceProjectID episode.ProjectID
	lastTraceEpisodeID string
}

// Stage 4a: ONE copy now serves the systemDesign+projectDesign+construction rails (byte-identical
// twins, collapsed by the package merge — arch.CheckFileLayout allows one impl file and one test file).
func (f *fakeEpisodes) AppendEpisode(rc fwra.Context, _ episode.ProjectID, record episode.EpisodeRecord) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.attempts++
	if rc.Context != nil && rc.Err() != nil {
		return fwra.New(fwra.Infrastructure, "append called with a dead context: "+rc.Err().Error())
	}
	if f.failAlways || f.attempts <= f.failN {
		return fwra.New(fwra.Infrastructure, "episode ledger unavailable")
	}
	f.appended = append(f.appended, record)
	return nil
}

// Stage 4a: ONE copy now serves the systemDesign+projectDesign+construction rails (byte-identical
// twins, collapsed by the package merge — arch.CheckFileLayout allows one impl file and one test file).
func (f *fakeEpisodes) ListEpisodes(_ fwra.Context, query episode.EpisodeQuery) ([]episode.EpisodeRecord, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.lastQuery = query
	if f.listErr != nil {
		return nil, f.listErr
	}
	return f.listRecords, nil
}

// Stage 4a: ONE copy now serves the systemDesign+projectDesign+construction rails (byte-identical
// twins, collapsed by the package merge — arch.CheckFileLayout allows one impl file and one test file).
func (f *fakeEpisodes) ReadTraceEvents(_ fwra.Context, projectID episode.ProjectID, episodeID string) ([]json.RawMessage, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.lastTraceProjectID = projectID
	f.lastTraceEpisodeID = episodeID
	if f.traceErr != nil {
		return nil, f.traceErr
	}
	return f.traceEvents, nil
}

// Stage 4a: ONE copy now serves the systemDesign+projectDesign+construction rails (byte-identical
// twins, collapsed by the package merge — arch.CheckFileLayout allows one impl file and one test file).
func (f *fakeEpisodes) records() []episode.EpisodeRecord {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]episode.EpisodeRecord(nil), f.appended...)
}

// Stage 4a: ONE copy now serves the systemDesign+projectDesign+construction rails (byte-identical
// twins, collapsed by the package merge — arch.CheckFileLayout allows one impl file and one test file).
func (f *fakeEpisodes) attemptCount() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.attempts
}

var _ episode.EpisodeAccess = (*fakeEpisodes)(nil)

// Stage 4a: ONE copy now serves the systemDesign+projectDesign+construction rails (byte-identical
// twins, collapsed by the package merge — arch.CheckFileLayout allows one impl file and one test file).
// testLedgerClock is the fixed clock the execution-ledger double stamps, so a row a test
// reads back is comparable between runs.
var testLedgerClock = time.Date(2026, 9, 23, 12, 0, 0, 0, time.UTC)

// fakeActivityExecution is the in-memory activityExecutionAccess the design workflow tests
// dual-write their review rounds through. Hand-rolled rather than the generated
// FakeActivityExecutionAccess for the reason the construction twin gives: these tests
// assert on the ROWS a session produced — "a send-back is a round, sentBack, carrying the
// same comments the slot thread got" — and a double whose every op is a func field records
// calls, not state.
//
// It holds the rules those assertions depend on and no more: one id names one round, a
// decided round takes no further verdict, and the round's thread mints its ids the way
// applyRoundReviewBatch does. The rest of the contract is the real facet's and is pinned by
// its own access_test.go.
type fakeActivityExecution struct {
	*fakeProjectState
}

var _ projectstate.ActivityExecutionAccess = fakeActivityExecution{}

// upsertExecution mirrors the store's single write-back point. Callers hold the lock.
func (f *fakeProjectState) upsertExecution(activityID string, mutate func(*projectstate.ActivityExecution)) projectstate.Version {
	if f.project.ActivityExecution == nil {
		f.project.ActivityExecution = map[string]projectstate.ActivityExecution{}
	}
	row := f.project.ActivityExecution[activityID]
	row.ActivityID = activityID
	mutate(&row)
	row.Version++
	f.project.ActivityExecution[activityID] = row
	return f.bump()
}

// execution reads back the execution row a session wrote.
func (f *fakeProjectState) execution(activityID string) projectstate.ActivityExecution {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.project.ActivityExecution[activityID]
}

// applyExecution is the shared shape of every mutating verb on the double: the
// per-activity CAS first, then the one write-back point.
func (f fakeActivityExecution) applyExecution(expectedActivityVersion int64, activityID string, mutate func(*projectstate.ActivityExecution)) (projectstate.Version, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	// The per-activity CAS the real facet applies (withActivityVersion). A stale
	// expectation is refused as a Conflict and writes NOTHING — counter included — so a
	// session whose copy of the row version has drifted fails here instead of passing
	// against a double that does not hold the rule production does.
	if held := f.project.ActivityExecution[activityID].Version; expectedActivityVersion != projectstate.NoActivityVersionExpectation && expectedActivityVersion != held {
		return 0, fwra.New(fwra.Conflict, fmt.Sprintf(
			"fake projectstate: activity %s is at version %d, not the expected %d; re-read the activity and re-apply",
			activityID, held, expectedActivityVersion))
	}
	return f.upsertExecution(activityID, mutate), nil
}

func (f fakeActivityExecution) OpenActivity(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, expectedActivityVersion int64, activityID string, typ projectstate.ActivityType, variant projectstate.TestingVariant, pin projectstate.LifecyclePin, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	return f.applyExecution(expectedActivityVersion, activityID, func(row *projectstate.ActivityExecution) {
		row.Type, row.Variant = typ, variant
		if row.Pin == nil {
			held := pin
			row.Pin = &held
		}
		if row.StartedAt == nil {
			t := testLedgerClock
			row.StartedAt = &t
		}
	})
}

func (f fakeActivityExecution) OpenReviewRound(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, expectedActivityVersion int64, activityID string, round projectstate.ReviewRoundInput, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	return f.applyExecution(expectedActivityVersion, activityID, func(row *projectstate.ActivityExecution) {
		for i := range row.Reviews {
			if row.Reviews[i].RoundID == round.RoundID {
				return // already open: a no-op success, not a second round
			}
		}
		// The shape oracle (stage 4b1 Task 1): a review task's START is the round opening,
		// recorded AFTER the idempotent-reopen check so a re-entry at the same id is not
		// counted twice.
		if f.rec != nil {
			f.rec.taskStarted(string(round.TaskID))
			f.rec.roundOpened(round.RoundID)
		}
		row.Reviews = append(row.Reviews, projectstate.ReviewRound{
			RoundID: round.RoundID,
			TaskID:  round.TaskID,
			Reviews: round.Reviews,
			// The KIND rides the round (stage 4b1 Task 10). The double used to drop it, which made
			// every kinded-round assertion vacuous: a design round's whole identity is the artifact
			// it judges, and roundGateKey reads it to tell two kinds' gates apart.
			ArtifactKind: round.ArtifactKind,
			Round:        round.Round,
			SubjectRef:   round.SubjectRef,
			Reviewers:    append([]projectstate.RoundReviewer(nil), round.Reviewers...),
			Outcome:      projectstate.RoundPending,
			OpenedAt:     testLedgerClock.Format(time.RFC3339),
			Provenance:   projectstate.AttemptProvenance{Origin: projectstate.OriginObserved, GeneratedAt: &testLedgerClock},
		})
	})
}

func (f fakeActivityExecution) AppendReviewVerdict(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, expectedActivityVersion int64, activityID string, roundID string, verdict projectstate.ReviewVerdict, comments []projectstate.ReviewComment, replies []projectstate.ReviewReply, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	var refused error
	v, err := f.applyExecution(expectedActivityVersion, activityID, func(row *projectstate.ActivityExecution) {
		for i := range row.Reviews {
			r := &row.Reviews[i]
			if r.RoundID != roundID || r.Outcome != projectstate.RoundPending {
				continue
			}
			// Build the new thread in a LOCAL and commit it only if every reply found its
			// parent. The real store applies the batch inside one mutation that either lands
			// whole or raises, and a double that half-applied would hide exactly the bug
			// roundRepliesFor exists to prevent: the comments landing while the utterance is
			// refused.
			thread := append([]projectstate.ReviewComment(nil), r.Thread...)
			for _, c := range comments {
				held := c
				// The same id the real applyRoundReviewBatch mints: from the THREAD it lands
				// on, not from the batch — which is what the workflow's slot→round pairing
				// predicts.
				held.ID = projectstate.ReviewCommentID(r.Round, len(thread))
				held.Round, held.Status = r.Round, projectstate.ReviewCommentOpen
				thread = append(thread, held)
			}
			// A reply lands INSIDE the thread it answers, and one naming a comment this
			// round's thread does not hold FAILS the whole append — the real store's rule
			// (appendReviewReply returns NotFound and AppendReviewVerdict propagates it).
			for _, rep := range replies {
				found := false
				for j := range thread {
					if thread[j].ID != rep.CommentID {
						continue
					}
					thread[j].Replies = append(append([]projectstate.ReviewCommentReply(nil), thread[j].Replies...),
						projectstate.ReviewCommentReply{
							ID:         fmt.Sprintf("%su%d", rep.CommentID, len(thread[j].Replies)+1),
							AuthorRole: rep.AuthorRole, Text: rep.Text, At: rep.At,
						})
					found = true
					break
				}
				if !found {
					refused = fwra.New(fwra.NotFound, "fakeActivityExecution.AppendReviewVerdict: reply names comment "+rep.CommentID+", which round "+roundID+" does not hold")
					return
				}
			}
			stamped := verdict
			stamped.At = testLedgerClock.Format(time.RFC3339)
			r.Verdicts = append(r.Verdicts, stamped)
			r.Thread = thread
			return
		}
	})
	if refused != nil {
		return 0, refused
	}
	return v, err
}

func (f fakeActivityExecution) DecideReviewRound(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, expectedActivityVersion int64, activityID string, roundID string, outcome projectstate.ReviewRoundOutcome, decidedBy string, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	return f.applyExecution(expectedActivityVersion, activityID, func(row *projectstate.ActivityExecution) {
		for i := range row.Reviews {
			r := &row.Reviews[i]
			if r.RoundID != roundID || r.Outcome != projectstate.RoundPending {
				continue
			}
			r.Outcome, r.DecidedBy, r.DecidedAt = outcome, decidedBy, testLedgerClock.Format(time.RFC3339)
			// The shape oracle (stage 4b1 Task 1): the decision, and — on a PASS — the
			// review task's completion. A sent-back round does NOT complete its task: the
			// pair re-opens, which is the whole claim of the send-back shape.
			if f.rec != nil {
				f.rec.roundDecided(roundID, string(outcome))
				if outcome == projectstate.RoundPassed {
					f.rec.taskCompleted(string(r.TaskID))
				}
			}
			return
		}
	})
}

func (f fakeActivityExecution) SetReviewCommentStatus(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, expectedActivityVersion int64, activityID string, roundID string, commentID string, status string, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	return f.applyExecution(expectedActivityVersion, activityID, func(row *projectstate.ActivityExecution) {
		for i := range row.Reviews {
			r := &row.Reviews[i]
			if r.RoundID != roundID {
				continue
			}
			for j := range r.Thread {
				if r.Thread[j].ID == commentID {
					r.Thread[j].Status = status
					return
				}
			}
		}
	})
}

