func asProjectDesignError(t *testing.T, err error) *fwmanager.Error {
	t.Helper()
	var pde *fwmanager.Error
	if !errors.As(err, &pde) {
		t.Fatalf("expected *projectDesignError, got %T: %v", err, err)
	}
	return pde
}

