// ---- pdFakePipeline: the EXTERNAL agentic-job seam (agenticJobAccess) ---

// pdFakePipeline stands in for the claude-code-action DESIGN job at the WIRE seam. It
// records every submitted spec (so tests assert the ProjectID / artifact_kind / branch
// in DispatchInputs and the DISTINCT idempotency key per dispatch) and serves a
// scripted terminal phase per observe. By default a submitted job is observed
// pdPipelineSucceeded immediately (the job "ran, committed the JSON, CI went green").
type pdFakePipeline struct {
	mu sync.Mutex

	// phases is the scripted terminal phase per dispatch in order; once exhausted the
	// last entry repeats. Empty == always pdPipelineSucceeded.
	phases []pdPipelinePhase
	// diagnostic is attached to a failed/cancelled observation.
	diagnostic string

	submits []submitRecord
	// handlePhase tracks the phase to return for each issued handle.
	handlePhase map[string]pdPipelinePhase
	nextID      int
	// onObserve, when set, is invoked on each observe (used to snapshot/mutate state
	// mid-flight — the ONLY moment a dispatch is genuinely in flight; systemdesign twin).
	onObserve func()
	// runURL, when set, rides EVERY observation and marks the REMOTE (GitHub-Actions)
	// venue — the only venue signal the capture seam can see.
	runURL string
	// episodes is the SP1 capture-seam script: one entry per observe call, consumed in
	// order; once exhausted the LAST entry repeats. nil entries mirror an observation
	// with no mined summary. An empty script means "never any episode".
	episodes []*agenticjob.EpisodeSummary
	observes int
}

// SubmitAgenticJob implements the GENERATED agenticjob contract seam
// (the submit invoker reaches it via the registered genActivities). The idempotency key is
// now stamped INSIDE the generated activity (genActivityIdempotencyKey) and arrives on the
// fwra call Context; the RepoRef→RepoTarget decode happens workflow-side (dispatchDesignJob),
// so spec.TargetRepo is the DECODED {Owner,Name} — recorded here as "owner/name".
func (p *pdFakePipeline) SubmitAgenticJob(rc fwra.Context, spec agenticjob.PipelineSpec) (agenticjob.PipelineHandle, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	idx := len(p.submits)
	targetRepo := ""
	if !agenticjob.RepoTargetIsZero(spec.TargetRepo) {
		targetRepo = spec.TargetRepo.Owner + "/" + spec.TargetRepo.Name
	}
	p.submits = append(p.submits, submitRecord{
		projectID:      ProjectID(spec.ProjectID),
		idempotencyKey: rc.IdempotencyKey,
		dispatchInputs: spec.DispatchInputs,
		targetRepo:     targetRepo,
		workflowFile:   spec.WorkflowFile,
	})
	phase := pdPipelineSucceeded
	if len(p.phases) > 0 {
		if idx < len(p.phases) {
			phase = p.phases[idx]
		} else {
			phase = p.phases[len(p.phases)-1]
		}
	}
	p.nextID++
	name := "design-run/" + uuid.NewString()
	p.handlePhase[name] = phase
	return agenticjob.PipelineHandle(name), nil
}

// submitCount returns how many dispatches have been submitted so far (thread-safe), so a
// ledger fake can record the dispatch count at seed time and a test can assert ordering.
func (p *pdFakePipeline) submitCount() int {
	p.mu.Lock()
	defer p.mu.Unlock()
	return len(p.submits)
}

func (p *pdFakePipeline) ObserveAgenticJob(_ fwra.Context, handle agenticjob.PipelineHandle) (agenticjob.PipelineObservation, error) {
	p.mu.Lock()
	phase := p.handlePhase[agenticjob.PipelineHandleString(handle)]
	diag := p.diagnostic
	hook := p.onObserve
	p.mu.Unlock()
	if hook != nil {
		hook()
	}
	obs := agenticjob.PipelineObservation{Phase: pdNeutralToRAPhase(phase)}
	if phase == pdPipelineFailed || phase == pdPipelineCancelled {
		obs.Diagnostic = diag
	}
	obs.RunURL = p.runURL
	obs.Episode = p.nextEpisode()
	return obs, nil
}

// nextEpisode serves the SP1 capture-seam script: entry N for observe N, the last entry
// repeating once the script is exhausted (mirroring the real RA, whose mined summary is
// stable once it lands).
func (p *pdFakePipeline) nextEpisode() *agenticjob.EpisodeSummary {
	p.mu.Lock()
	defer p.mu.Unlock()
	if len(p.episodes) == 0 {
		return nil
	}
	i := p.observes
	p.observes++
	if i >= len(p.episodes) {
		i = len(p.episodes) - 1
	}
	return p.episodes[i]
}

// CancelAgenticJob satisfies the contract; the Phase-2 draft path never cancels.
func (p *pdFakePipeline) CancelAgenticJob(_ fwra.Context, _ agenticjob.PipelineHandle) error {
	return nil
}

// pdNeutralToRAPhase maps this Manager's neutral scripted phase onto the RA phase the
// generated observe activity returns (the inverse of pdDesignPipelinePhase).
func pdNeutralToRAPhase(p pdPipelinePhase) agenticjob.PipelinePhase {
	switch p {
	case pdPipelinePending:
		return agenticjob.PhasePending
	case pdPipelineRunning:
		return agenticjob.PhaseRunning
	case pdPipelineSucceeded:
		return agenticjob.PhaseSucceeded
	case pdPipelineFailed:
		return agenticjob.PhaseFailed
	case pdPipelineCancelled:
		return agenticjob.PhaseCancelled
	default:
		return agenticjob.PhasePending
	}
}

var _ agenticjob.AgenticJobAccess = (*pdFakePipeline)(nil)

