// pdFakeActivityExecution is the in-memory activityExecutionAccess the design workflow tests
// dual-write their review rounds through. Hand-rolled rather than the generated
// FakeActivityExecutionAccess for the reason the construction twin gives: these tests
// assert on the ROWS a session produced — "a send-back is a round, sentBack, carrying the
// same comments the slot thread got" — and a double whose every op is a func field records
// calls, not state.
//
// It holds the rules those assertions depend on and no more: one id names one round, a
// decided round takes no further verdict, and the round's thread mints its ids the way
// applyRoundReviewBatch does. The rest of the contract is the real facet's and is pinned by
// its own access_test.go.
type pdFakeActivityExecution struct {
	*pdFakeProjectState
}

var _ projectstate.ActivityExecutionAccess = pdFakeActivityExecution{}

// upsertExecution mirrors the store's single write-back point. Callers hold the lock.
func (f *pdFakeProjectState) upsertExecution(activityID string, mutate func(*projectstate.ActivityExecution)) projectstate.Version {
	if f.project.ActivityExecution == nil {
		f.project.ActivityExecution = map[string]projectstate.ActivityExecution{}
	}
	row := f.project.ActivityExecution[activityID]
	row.ActivityID = activityID
	mutate(&row)
	row.Version++
	f.project.ActivityExecution[activityID] = row
	return f.bump()
}

// execution reads back the execution row a session wrote.
func (f *pdFakeProjectState) execution(activityID string) projectstate.ActivityExecution {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.project.ActivityExecution[activityID]
}

// applyExecution is the shared shape of every mutating verb on the double: the
// per-activity CAS first, then the one write-back point.
func (f pdFakeActivityExecution) applyExecution(expectedActivityVersion int64, activityID string, mutate func(*projectstate.ActivityExecution)) (projectstate.Version, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	// The per-activity CAS the real facet applies (withActivityVersion). A stale
	// expectation is refused as a Conflict and writes NOTHING — counter included — so a
	// session whose copy of the row version has drifted fails here instead of passing
	// against a double that does not hold the rule production does.
	if held := f.project.ActivityExecution[activityID].Version; expectedActivityVersion != projectstate.NoActivityVersionExpectation && expectedActivityVersion != held {
		return 0, fwra.New(fwra.Conflict, fmt.Sprintf(
			"fake projectstate: activity %s is at version %d, not the expected %d; re-read the activity and re-apply",
			activityID, held, expectedActivityVersion))
	}
	return f.upsertExecution(activityID, mutate), nil
}

func (f pdFakeActivityExecution) OpenActivity(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, expectedActivityVersion int64, activityID string, typ projectstate.ActivityType, variant projectstate.TestingVariant, pin projectstate.LifecyclePin, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	return f.applyExecution(expectedActivityVersion, activityID, func(row *projectstate.ActivityExecution) {
		row.Type, row.Variant = typ, variant
		if row.Pin == nil {
			held := pin
			row.Pin = &held
		}
		if row.StartedAt == nil {
			t := testLedgerClock
			row.StartedAt = &t
		}
	})
}

func (f pdFakeActivityExecution) OpenReviewRound(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, expectedActivityVersion int64, activityID string, round projectstate.ReviewRoundInput, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	return f.applyExecution(expectedActivityVersion, activityID, func(row *projectstate.ActivityExecution) {
		for i := range row.Reviews {
			if row.Reviews[i].RoundID == round.RoundID {
				return // already open: a no-op success, not a second round
			}
		}
		row.Reviews = append(row.Reviews, projectstate.ReviewRound{
			RoundID: round.RoundID,
			TaskID:  round.TaskID,
			Reviews: round.Reviews,
			// The KIND rides the round (stage 4b1 Task 10). The double used to drop it, which made
			// every kinded-round assertion vacuous: a design round's whole identity is the artifact
			// it judges, and roundGateKey reads it to tell two kinds' gates apart.
			ArtifactKind: round.ArtifactKind,
			Round:        round.Round,
			SubjectRef:   round.SubjectRef,
			Reviewers:    append([]projectstate.RoundReviewer(nil), round.Reviewers...),
			Outcome:      projectstate.RoundPending,
			OpenedAt:     testLedgerClock.Format(time.RFC3339),
			Provenance:   projectstate.AttemptProvenance{Origin: projectstate.OriginObserved, GeneratedAt: &testLedgerClock},
		})
	})
}

func (f pdFakeActivityExecution) AppendReviewVerdict(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, expectedActivityVersion int64, activityID string, roundID string, verdict projectstate.ReviewVerdict, comments []projectstate.ReviewComment, replies []projectstate.ReviewReply, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	var refused error
	v, err := f.applyExecution(expectedActivityVersion, activityID, func(row *projectstate.ActivityExecution) {
		for i := range row.Reviews {
			r := &row.Reviews[i]
			if r.RoundID != roundID || r.Outcome != projectstate.RoundPending {
				continue
			}
			// Build the new thread in a LOCAL and commit it only if every reply found its
			// parent. The real store applies the batch inside one mutation that either lands
			// whole or raises, and a double that half-applied would hide exactly the bug
			// roundRepliesFor exists to prevent: the comments landing while the utterance is
			// refused.
			thread := append([]projectstate.ReviewComment(nil), r.Thread...)
			for _, c := range comments {
				held := c
				// The same id the real applyRoundReviewBatch mints: from the THREAD it lands
				// on, not from the batch — which is what the workflow's slot→round pairing
				// predicts.
				held.ID = projectstate.ReviewCommentID(r.Round, len(thread))
				held.Round, held.Status = r.Round, projectstate.ReviewCommentOpen
				thread = append(thread, held)
			}
			// A reply lands INSIDE the thread it answers, and one naming a comment this
			// round's thread does not hold FAILS the whole append — the real store's rule
			// (appendReviewReply returns NotFound and AppendReviewVerdict propagates it).
			for _, rep := range replies {
				found := false
				for j := range thread {
					if thread[j].ID != rep.CommentID {
						continue
					}
					thread[j].Replies = append(append([]projectstate.ReviewCommentReply(nil), thread[j].Replies...),
						projectstate.ReviewCommentReply{
							ID:         fmt.Sprintf("%su%d", rep.CommentID, len(thread[j].Replies)+1),
							AuthorRole: rep.AuthorRole, Text: rep.Text, At: rep.At,
						})
					found = true
					break
				}
				if !found {
					refused = fwra.New(fwra.NotFound, "fakeActivityExecution.AppendReviewVerdict: reply names comment "+rep.CommentID+", which round "+roundID+" does not hold")
					return
				}
			}
			stamped := verdict
			stamped.At = testLedgerClock.Format(time.RFC3339)
			r.Verdicts = append(r.Verdicts, stamped)
			r.Thread = thread
			return
		}
	})
	if refused != nil {
		return 0, refused
	}
	return v, err
}

func (f pdFakeActivityExecution) DecideReviewRound(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, expectedActivityVersion int64, activityID string, roundID string, outcome projectstate.ReviewRoundOutcome, decidedBy string, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	return f.applyExecution(expectedActivityVersion, activityID, func(row *projectstate.ActivityExecution) {
		for i := range row.Reviews {
			r := &row.Reviews[i]
			if r.RoundID != roundID || r.Outcome != projectstate.RoundPending {
				continue
			}
			r.Outcome, r.DecidedBy, r.DecidedAt = outcome, decidedBy, testLedgerClock.Format(time.RFC3339)
			return
		}
	})
}

func (f pdFakeActivityExecution) SetReviewCommentStatus(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, expectedActivityVersion int64, activityID string, roundID string, commentID string, status string, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	return f.applyExecution(expectedActivityVersion, activityID, func(row *projectstate.ActivityExecution) {
		for i := range row.Reviews {
			r := &row.Reviews[i]
			if r.RoundID != roundID {
				continue
			}
			for j := range r.Thread {
				if r.Thread[j].ID == commentID {
					r.Thread[j].Status = status
					return
				}
			}
		}
	})
}

