// planWithDesignPrefix is the derived plan's fixed design prefix exactly as DerivePlan
// emits it (Task 9): requirements → architecture → projectDesign, each authored
// system-architect/coding=false and componentless, with no construction row against any
// of them. It is the fixture for BOTH sides of this rule — the pump that must walk past
// them and the read that must serve them — because they are the same three rows.
func planWithDesignPrefix() projectstate.Project {
	return projWithActivities(
		[]projectstate.ActivityItem{
			{Name: "requirements", Title: "Requirements", WorkerClass: "system-architect"},
			{Name: "architecture", Title: "Architecture & Call Chains", WorkerClass: "system-architect"},
			{Name: "projectDesign", Title: "Project Design (SDP Review · M0)", WorkerClass: "system-architect"},
		},
		[]projectstate.NetworkDependency{
			{Activity: "architecture", DependsOn: []string{"requirements"}},
			{Activity: "projectDesign", DependsOn: []string{"architecture"}},
		},
	)
}

// THE RULE BOTH WAYS (stage 4b1 Task 10). A pump on the two pre-4b1 eligibility rules still
// walks past a design activity — it has no child for it, and a recorded history that skipped
// it must keep skipping it — while eligibleWithDesign SELECTS it. Neither rule ever BLOCKS
// one: blocking records a sticky RecordActivityFailed with no reopen path, which would poison
// the very activity this wave is built to run.
func Test_NextEligible_DesignActivitiesAreAdmittedOnlyOnTheFencedRule(t *testing.T) {
	proj := planWithDesignPrefix() // requirements/architecture/projectDesign not started
	for _, rule := range []eligibilityRule{eligibleNotStarted, eligibleDispatchable} {
		sel := nextEligibleActivity(proj, rule)
		if sel.Verdict != verdictQuiescent {
			t.Errorf("rule %d: with only design work eligible a pre-4b1 pump is quiescent, got %+v", rule, sel)
		}
	}
	sel := nextEligibleActivity(proj, eligibleWithDesign)
	if sel.Verdict != verdictDispatch || sel.Activity.ActivityID != "requirements" {
		t.Fatalf("want requirements dispatched under eligibleWithDesign, got %+v", sel)
	}
	if sel.Activity.Type != projectstate.ActivityTypeRequirements {
		t.Errorf("the dispatched activity carries type %s, want requirements", sel.Activity.Type)
	}
	if !isDesignLifecycle(sel.Activity.Type) {
		t.Error("a dispatched design activity must be recognised as one, or its phase floor is the construction seal")
	}
}

// THE PHASE GATE IS PER ACTIVITY (Task 10; Task 9's carry 1). projectDesign's own phase is
// PhaseProjectDesign — M0's approve is what moves the project INTO construction — so a
// blanket PhaseConstruction gate made the deterministic Project Design permanently
// unselectable and left Task 9's compute inert. Driven at the phase a real project is in
// when M0 is owed, with the two upstream design activities Done.
func Test_NextEligible_SelectsProjectDesignBeforeTheProjectReachesConstruction(t *testing.T) {
	proj := planWithDesignPrefix()
	proj.Phase = projectstate.PhaseProjectDesign
	// Both upstream design activities read DONE, which for a design activity means every
	// phase's gate attempt passed — four for `requirements`, one for `architecture`.
	proj.ActivityExecution = map[string]projectstate.ActivityExecution{
		"requirements": {ActivityID: "requirements", Attempts: passedLedger("requirements",
			"mission", "glossary", "volatilities", "coreUseCases")},
		"architecture": {ActivityID: "architecture", Attempts: passedLedger("architecture", "architecture")},
	}
	sel := nextEligibleActivity(proj, eligibleWithDesign)
	if sel.Verdict != verdictDispatch || sel.Activity.ActivityID != "projectDesign" {
		t.Fatalf("want projectDesign dispatched at PhaseProjectDesign, got %+v", sel)
	}
	// And the pre-4b1 rules are unmoved: the blanket gate still refuses every phase below
	// construction, which is what keeps a recorded history replaying what it recorded.
	if sel := nextEligibleActivity(proj, eligibleDispatchable); sel.Verdict != verdictQuiescent {
		t.Fatalf("a pre-4b1 pump must stay quiescent below PhaseConstruction, got %+v", sel)
	}
}

// A design activity reaching the dispatch resolver now RESOLVES, where it used to take its
// own quiescent arm off the retired sentinel.
func Test_DispatchSelectionFor_DesignActivityDispatches(t *testing.T) {
	sel := dispatchSelectionFor(planWithDesignPrefix(), "architecture",
		projectstate.ActivityItem{Name: "architecture", WorkerClass: "system-architect"})
	if sel.Verdict != verdictDispatch {
		t.Fatalf("got %+v, want dispatch", sel)
	}
	if sel.Activity.Type != projectstate.ActivityTypeArchitecture {
		t.Errorf("type = %s, want architecture", sel.Activity.Type)
	}
}

// THE ROSTER SPLIT IS GONE AND WHAT REMAINS IS A VERSION FENCE (stage 4b1 Task 11).
// runsOnTheDeliveryChild answered "which child runs this TYPE?" for one commit-range;
// startActivityChild now answers "did this EXECUTION record the marker?", which is a question
// about a history and not about a roster. The distinction is the thing this case pins, because
// the two look identical in a diff: a source that branched on the activity again would pass a
// behavioural test on a fresh execution just as well.
//
// The DefaultVersion arm's own proof is the replay suite — two pump fixtures (pre-b1 and pre-d)
// carry a recorded ChildWorkflow command for the retired child and went red before the fence
// existed — and the v1 arm's proof is every pump test above, which now runs the generic child
// end to end.
func Test_Pump_StartsOneChildAndNamesNoActivityType(t *testing.T) {
	src, err := os.ReadFile("pumpnextactivity.go")
	if err != nil {
		t.Fatalf("reading the pump: %v", err)
	}
	body := string(src)
	// THE FENCE IS GONE, deliberately (stage 4b1 Task 13). changeGenericActivityChild existed
	// so a pump parked in child.Get across the deploy replayed the ChildWorkflow command its own
	// history recorded; its DefaultVersion arm named ConstructActivityWorkflow, which the build no
	// longer has. A GetVersion marker whose other arm cannot compile is worse than no marker, and
	// the drain this wave requires before deploy is what discharges it
	// (docs/bugs/2026-09-24-stage3-rail-earmarks.md). A NEW fence here would be a claim that the
	// old child still exists.
	for _, gone := range []string{"workflow.GetVersion(ctx, changeGenericActivityChild", "pumpStartsTheGenericChild(", "executionKindConstructActivity"} {
		if strings.Contains(body, gone) {
			t.Errorf("the pump still uses %q; the retired child and the fence that chose it die together", gone)
		}
	}
	if strings.Contains(body, "isDesignLifecycle(") && strings.Contains(body, "ExecuteChildWorkflow") {
		t.Error("the pump must not choose a child by ACTIVITY TYPE; there is exactly one child")
	}
	if !strings.Contains(body, "deliveryActivityWorkflowID(projectID, id)") {
		t.Error("the pump must address the generic child by deliveryActivityWorkflowID; a hand-built id is how the pump and the façade disagree about which execution to signal")
	}
	if strings.Count(body, "workflow.ExecuteChildWorkflow(") != 1 {
		t.Errorf("the pump makes %d ChildWorkflow calls; one child means one call site",
			strings.Count(body, "workflow.ExecuteChildWorkflow("))
	}
}

// M0 ON THE SHAPE THE DERIVED PLAN ACTUALLY HAS (Task 9 + 10). A milestone never carries
// a Done record of its own, so M0 is satisfied only DERIVEDLY — every activity it depends
// on is Done — and since Task 9 that is projectDesign, whose ENTIRE lifecycle is one gate
// task (the sdp phase has no dispatch task at all, so the backfill writes a single passed
// sdpReview attempt and nothing else).
//
// That makes a long, silent chain load-bearing for the whole project: one attempt →
// phaseCompleteFromAttempts → projectDesign reads Done → M0 satisfied → every construction
// activity behind M0 is eligible. Break any link and the pump does not fail; it goes
// QUIESCENT, and a project with 29 activities to build looks finished. So the chain is
// pinned end to end here, and pinned NEGATIVELY too, so the assertion cannot pass for some
// reason other than the attempt.
func Test_NextEligible_M0IsSatisfiedByTheBackfilledProjectDesignRow(t *testing.T) {
	plan := func() projectstate.Project {
		proj := planWithDesignPrefix()
		list, _ := proj.ActivityList.Model.(*projectstate.ActivityList)
		list.Activities = append(list.Activities, projectstate.ActivityItem{
			Name: "C-TLM", Title: "TodoListManager", WorkerClass: "junior-developer",
			Coding: true, ComponentID: "todo-list-manager",
		})
		proj.Network = makeCommittedNetworkWithMilestones(
			[]projectstate.NetworkDependency{
				{Activity: "architecture", DependsOn: []string{"requirements"}},
				{Activity: "projectDesign", DependsOn: []string{"architecture"}},
				{Activity: "C-TLM", DependsOn: []string{"M0"}},
			},
			[]projectstate.NetworkMilestone{
				{ID: "M0", Name: "SDP Review Approved", Public: true, DependsOn: []string{"projectDesign"}},
			},
		)
		return proj
	}

	// The backfilled row, exactly as cmd/backfill-attempts writes it: the gate attempt
	// alone, no stored Phase and no stored Phases.
	done := plan()
	done.ActivityExecution = map[string]projectstate.ActivityExecution{
		"projectDesign": {ActivityID: "projectDesign", Attempts: []projectstate.TaskAttempt{
			ledgerAttempt("projectDesign", projectstate.GateTaskFor("sdp"), 1, projectstate.OutcomePassed),
		}},
	}
	sel := nextEligibleActivity(done, eligibleDispatchable)
	if sel.Verdict != verdictDispatch || sel.Activity.ActivityID != "C-TLM" {
		t.Fatalf("want C-TLM dispatched behind a satisfied M0, got %+v", sel)
	}
	// On eligibleWithDesign the SAME state picks `requirements` instead — it is declaration
	// index 0 and it has no row — which is precisely the selection change
	// changeDesignActivitiesDispatchable fences: a recorded history that dispatched C-TLM
	// must not replay into a different child.
	if fenced := nextEligibleActivity(done, eligibleWithDesign); fenced.Activity.ActivityID != "requirements" {
		t.Errorf("under eligibleWithDesign the same state selects %q, want requirements — "+
			"if this stops being true the version fence's reason has moved", fenced.Activity.ActivityID)
	}

	// Without that one attempt M0 is unsatisfied and the pump has nothing to do — which is
	// what proves the dispatch above came from the ledger and not from somewhere else.
	if sel := nextEligibleActivity(plan(), eligibleDispatchable); sel.Verdict != verdictQuiescent {
		t.Fatalf("with projectDesign unfinished the pump must be quiescent, got %+v", sel)
	}
}

// The regression the whole change exists for: a fresh project with NO service
// contracts must still dispatch its first coding activity.
func TestNextEligibleActivity_DispatchesWithNoServiceContracts(t *testing.T) {
	proj := projWithActivities(
		[]projectstate.ActivityItem{{
			Name: "C-TLM", Title: "TodoListManager — settlement manager",
			Coding: true, EffortDays: 13, ComponentID: "todo-list-manager",
		}},
		[]projectstate.NetworkDependency{{Activity: "C-TLM", DependsOn: []string{}}},
	)
	// Deliberately nil: ServiceContracts must play no part in selection.
	proj.ServiceContracts = nil

	sel := nextEligibleActivity(proj, eligibleDispatchable)
	if sel.Verdict != verdictDispatch {
		t.Fatalf("want verdictDispatch, got %v (blocked=%q)", sel.Verdict, sel.BlockedReason)
	}
	if sel.Activity.ComponentID != "todo-list-manager" {
		t.Fatalf("want componentID todo-list-manager, got %q", sel.Activity.ComponentID)
	}
	if sel.Activity.Layer != "manager" {
		t.Fatalf("want layer hydrated to manager, got %q", sel.Activity.Layer)
	}
	if sel.Activity.Kind != activityKindConstruction {
		t.Fatalf("want activityKindConstruction, got %v", sel.Activity.Kind)
	}
}

