// csFakeQueryClient scripts QueryWorkflow with an error, for the F20 pre-phase read test.
// It embeds client.Client so any unimplemented method panics.
type csFakeQueryClient struct {
	client.Client
	queryErr error
}

func (f *csFakeQueryClient) QueryWorkflow(_ context.Context, _ string, _ string, _ string, _ ...any) (converter.EncodedValue, error) {
	return nil, f.queryErr
}

// ---- F20: clean not-found altitude on the pre-phase construction read ------

// Before construction starts the pump workflow does not exist; Temporal's raw
// "workflow not found for ID: gtdapp:construction" must NOT reach the client. Map it to
// a clean, user-altitude NotFound.
func Test_GetSessionState_BeforeConstruction_CleanNotFound(t *testing.T) {
	fc := &csFakeQueryClient{queryErr: serviceerror.NewNotFound("workflow not found for ID: gtdapp:construction")}
	m := newTestConstructionManager(fc)

	_, err := m.GetSessionState(testCtx(), ProjectID("gtdapp"), nil)
	e := asConstructionError(t, err)
	if e.Kind != fwmanager.NotFound {
		t.Fatalf("want NotFound, got %d", e.Kind)
	}
	if strings.Contains(e.Detail, "workflow not found") || strings.Contains(e.Detail, "gtdapp:construction") {
		t.Fatalf("Temporal internals leaked to the client: %q", e.Detail)
	}
	if !strings.Contains(e.Detail, "construction has not started") {
		t.Fatalf("want a user-altitude message, got %q", e.Detail)
	}
}

// A PER-ACTIVITY miss means only that the pump has not dispatched that activity —
// construction may be under way elsewhere in the project — so the copy names the
// activity and never claims the whole project has not started.
func Test_GetSessionState_ActivityNotDispatched_NamesTheActivity(t *testing.T) {
	fc := &csFakeQueryClient{queryErr: serviceerror.NewNotFound("workflow not found for ID: gtdapp:C-billing-manager")}
	m := newTestConstructionManager(fc)
	act := ActivityID("C-billing-manager")

	_, err := m.GetSessionState(testCtx(), ProjectID("gtdapp"), &act)
	e := asConstructionError(t, err)
	if e.Kind != fwmanager.NotFound {
		t.Fatalf("want NotFound, got %d", e.Kind)
	}
	if strings.Contains(e.Detail, "for this project") {
		t.Fatalf("a per-activity miss claims the whole project has not started: %q", e.Detail)
	}
	if !strings.Contains(e.Detail, "C-billing-manager") || !strings.Contains(e.Detail, "not dispatched") {
		t.Fatalf("want the activity named as not dispatched, got %q", e.Detail)
	}
	if strings.Contains(e.Detail, "workflow not found") {
		t.Fatalf("Temporal internals leaked to the client: %q", e.Detail)
	}
}

// QA 2026-07-19 (poll-404 wizard reset twin): a namespace-not-found from a wrong/foreign
// Temporal backend must NOT map to the authoritative "construction has not started"
// NotFound — the polled console trusts that 404 and drops its session view. It stays an
// Infrastructure fault the client tolerates.
func Test_CS_GetSessionState_NamespaceNotFound_IsInfrastructureNot404(t *testing.T) {
	fc := &csFakeQueryClient{queryErr: serviceerror.NewNamespaceNotFound("default")}
	m := newTestConstructionManager(fc)

	_, err := m.GetSessionState(testCtx(), ProjectID("gtdapp"), nil)
	e := asConstructionError(t, err)
	if e.Kind == fwmanager.NotFound {
		t.Fatalf("namespace-not-found (wrong Temporal backend) must not claim construction absence, got NotFound %q", e.Detail)
	}
	if e.Kind != fwmanager.Infrastructure {
		t.Fatalf("want Infrastructure, got %d (detail %q)", e.Kind, e.Detail)
	}
}

// =============================================================================
// constructionManager workflow unit tests over the Temporal in-memory test
// environment (testsuite.WorkflowTestSuite). The three Engines (handOffEngine,
// interventionEngine, reviewEngine) and the four ResourceAccess ports
// (projectStateAccess, agenticJobAccess, artifactAccess, workerAccess)
// are constructed as interface test doubles (fakes) — the not-yet-built deps are
// driven against their FROZEN CONTRACTS as the Manager-declared consumer interfaces
// (deps.go). These run with no Docker and no dev server (the real-infrastructure
// exercise is a later integration activity).
//
// They assert the UC3 spine (cast → dispatch → submit/observe → stage → review →
// recordChangeReviewed → recordActivityExited), the no-eligible-activity quiet
// tick, the pause branch (NCUC2), the operator-override branch, and the key
// error/variance/conflict paths — per [[the-method-testing]] (black-box where the
// observable is the workflow result/recorded side effects).
// =============================================================================

// ---- Fakes (interface test doubles for the downstream deps) -----------------

// csFakeProjectState records the additive Phase-3 transition calls + serves a
// scripted head-state. It satisfies the Manager's ProjectStateAccess consumer
// interface (deps.go) — the read + the three additive transition verbs.
type csFakeProjectState struct {
	mu sync.Mutex

	project  projectstate.Project
	notFound bool

	// conflictFirst, when >0, returns fwra.Conflict on the first N transition
	// calls (across all transition verbs) before succeeding — drives the §6.5
	// re-read→re-apply loop.
	conflictFirst int

	reviewed  []string
	exited    []exitCall
	failed    []failCall
	paused    []string
	phaseDone []phaseCompletedCall

	version projectstate.Version

	// order, when set, receives "record" on every RecordOperatorPaused — a call-order
	// log shared with the other fakes (callLog).
	order *callLog

	// notes / delivered record the operator-note verbs (B1.4), in call order.
	notes     []noteCall
	delivered []deliveredCall

	// resumed counts RecordOperatorResumed calls (B1.7).
	resumed int

	// reconciles counts designSessionAccess.reconcileBranchFromMain calls and records the
	// branch + preserved kind each one carried — the F80c verb the child's restored merge
	// guard reaches (final fix wave, G3). onReconcile, when set, runs on each call, which is
	// how a test models "the reconcile made the PR mergeable again".
	reconciles  []reconcileCall
	onReconcile func()

	// rec, when set, is the lifecycle-shape oracle's observation side (stage 4b1 Task 1).
	// nil for every other test, and every call site is guarded, so a shape case and a
	// replay fixture exercise the SAME store semantics rather than two that drift.
	rec *shapeRecorder

	// stampConflicts, when >0, returns fwra.Conflict on the next N
	// RecordOperatorNoteDelivered calls only (a stamp that cannot land, M4).
	stampConflicts int
	// afterConflict, when set, runs each time maybeConflict serves a Conflict — the
	// concurrent write that caused it (I2: a new pause landing between two tries).
	afterConflict func(*csFakeProjectState)

	// seedCommentOnRound files ONE open comment on a round the instant it is opened, keyed by the
	// review task (stage 4b1 Task 12, fix round 2). It stands in for a race that is REAL in
	// production and unreachable in a test environment: a round is opened, its agent critic runs
	// for minutes, and a human files a comment in that window — after which the autogate must hold
	// rather than synthesize an approve. The test env has no such window (with no job reporting
	// RUNNING the whole walk executes at workflow time zero), so the double puts the comment where
	// the race would have.
	seedCommentOnRound map[string]projectstate.ReviewComment

	// commitFailKinds makes the SLOT COMMIT refuse for the named kinds (stage 4b1 Task 12, fix
	// round 1). It is the only way to reach the POST-EXIT COMMIT WINDOW: the walk records the
	// activity's binary exit and then commits its slots, so a commit that fails is what leaves a
	// Completed activity with an AwaitingReview slot. The refusal is deliberately NOT a Conflict
	// — applyRecovering would retry that away and the window would never open.
	commitFailKinds map[projectstate.ArtifactKind]bool

	// rowReads counts ReadActivityExecution calls (stage 4b1 Task 7). It is what the
	// unbound-caller table asserts on: the pump, the supervision pause record and the
	// round sweep hold NO row, so their Conflict arm must make ZERO of these — and case
	// (b)/(c) assert exactly ONE, which is the whole claim that twenty attempts became one.
	rowReads int

	// The deterministic Project-Design compute's writes (stage 4b1 Task 9). Three lists and
	// a counter, and each answers a question the others cannot:
	//
	//	stagedSlots / stagedModels  WHICH slots the compute staged, in order, and the models
	//	                            it staged — the dial equality is asserted on the models,
	//	                            not on a count, because "eight writes happened" would
	//	                            pass with eight wrong documents.
	//	committedSlots              which slots M0's approve committed. Order matters: a
	//	                            phase advanced before the plan was committed would put
	//	                            the pump into construction against an uncommitted plan.
	//	advanced                    AdvancePhase calls. The phase itself moves on f.project,
	//	                            so the seal's idempotence guard re-reads a real number.
	stagedSlots    []projectstate.ArtifactKind
	stagedModels   []projectstate.ArtifactModel
	committedSlots []projectstate.ArtifactKind
	advanced       int

	// commentStatuses is every comment id SetReviewCommentStatus was called with, in order
	// (stage 4b1 Task 10). It is the drain-past-capacity case's whole assertion.
	commentStatuses []string
}

// noteCall is one RecordOperatorNote; deliveredCall one RecordOperatorNoteDelivered.
type noteCall struct {
	activityID string
	note       projectstate.OperatorNoteInput
}

type deliveredCall struct {
	activityID, noteID, attemptID string
}

// phaseCompletedCall records one RecordPhaseCompleted transition (the gate's durable
// per-phase completion record). The gate tests assert on it via phaseCompleted.
type phaseCompletedCall struct {
	activityID string
	phase      string
}

type exitCall struct {
	activityID string
	outcome    projectstate.ActivityOutcome
}

type failCall struct {
	activityID string
	reason     projectstate.FailureReason
	detail     string
}

func (f *csFakeProjectState) ReadProject(_ fwra.Context, _ projectstate.ProjectID) (projectstate.Project, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.notFound {
		return projectstate.Project{}, fwra.New(fwra.NotFound, "no row yet")
	}
	return f.project, nil
}

func (f *csFakeProjectState) ReadProjectVersion(_ fwra.Context, _ projectstate.ProjectID) (projectstate.Version, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.notFound {
		return 0, fwra.New(fwra.NotFound, "no row yet")
	}
	return f.project.Version, nil
}

func (f *csFakeProjectState) bump() projectstate.Version {
	f.version++
	f.project.Version = f.version
	return f.version
}

func (f *csFakeProjectState) maybeConflict() error {
	if f.conflictFirst > 0 {
		f.conflictFirst--
		// Advance the served head version so the re-read sees a newer value.
		f.version++
		f.project.Version = f.version
		if f.afterConflict != nil {
			f.afterConflict(f)
		}
		return fwra.New(fwra.Conflict, "stale version")
	}
	return nil
}

func (f *csFakeProjectState) RecordChangeReviewed(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, activityID string, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if err := f.maybeConflict(); err != nil {
		return 0, err
	}
	f.reviewed = append(f.reviewed, activityID)
	f.stampRow(activityID)
	return f.bump(), nil
}

func (f *csFakeProjectState) RecordActivityExited(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, activityID string, outcome projectstate.ActivityOutcome, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if err := f.maybeConflict(); err != nil {
		return 0, err
	}
	f.exited = append(f.exited, exitCall{activityID: activityID, outcome: outcome})
	f.stampRow(activityID)
	return f.bump(), nil
}

func (f *csFakeProjectState) RecordActivityFailed(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, activityID string, reason projectstate.FailureReason, detail string, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if err := f.maybeConflict(); err != nil {
		return 0, err
	}
	f.failed = append(f.failed, failCall{activityID: activityID, reason: reason, detail: detail})
	f.stampRow(activityID)
	return f.bump(), nil
}

func (f *csFakeProjectState) RecordOperatorPaused(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, reason string, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if err := f.maybeConflict(); err != nil {
		return 0, err
	}
	f.paused = append(f.paused, reason)
	// Like the real store (GitStore.RecordOperatorPaused): the pause lands in head-state,
	// so a later read — the pump's readProject — sees it.
	f.project.OperatorPaused = true
	f.project.PauseReason = reason
	f.order.add("record")
	return f.bump(), nil
}

// RecordOperatorResumed records a resume (B1.7): the recorded pause is cleared.
func (f *csFakeProjectState) RecordOperatorResumed(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if err := f.maybeConflict(); err != nil {
		return 0, err
	}
	f.resumed++
	f.project.OperatorPaused = false
	f.project.PauseReason = ""
	if f.order != nil {
		f.order.add("resume")
	}
	return f.bump(), nil
}

func (f *csFakeProjectState) RecordReviewPolicy(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, _ projectstate.ReviewPolicy, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if err := f.maybeConflict(); err != nil {
		return 0, err
	}
	return f.bump(), nil
}

func (f *csFakeProjectState) RecordOperatorNote(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, activityID string, note projectstate.OperatorNoteInput, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if err := f.maybeConflict(); err != nil {
		return 0, err
	}
	f.notes = append(f.notes, noteCall{activityID: activityID, note: note})
	if f.order != nil {
		f.order.add("note")
	}
	f.stampRow(activityID)
	return f.bump(), nil
}

func (f *csFakeProjectState) RecordOperatorNoteDelivered(_ fwra.Context, _ projectstate.ProjectID, _ projectstate.Version, activityID, noteID, attemptID string, _ projectstate.RepoCredential, _ fwra.IdempotencyKey) (projectstate.Version, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.stampConflicts > 0 {
		f.stampConflicts--
		f.version++
		f.project.Version = f.version
		return 0, fwra.New(fwra.Conflict, "stale version (stamp)")
	}
	if err := f.maybeConflict(); err != nil {
		return 0, err
	}
	f.delivered = append(f.delivered, deliveredCall{activityID: activityID, noteID: noteID, attemptID: attemptID})
	if f.order != nil {
		f.order.add("delivered")
	}
	f.stampRow(activityID)
	return f.bump(), nil
}

