// railLifecycleEnabled derives wfDeps.RailEnabled (WorkerManifest), and the derivation
// is PER PROJECT because what the ONE repo resolver ANSWERS is what decides it. Every
// row below is a combination a real boot produces:
//
//   - cloud (or a creds-ful local boot): the catalog resolver answers the project's own
//     repo ⇒ the PR-rail lifecycle owns the branch → PR → merge.
//   - local with no GitHub App catalog: the rail dep is bound (GitLocal) AND the
//     resolver answers the deterministic GitLocal ref for every project ⇒ DORMANT. The
//     old table fed repo=nil for this case, an input the collapsed hook can no longer
//     produce, and a true here is what would mint a rail credential in the construction
//     history and make runLocalMergeStep skip, so nothing would merge local branches.
//   - a PR-rail boot whose catalog MISSES this project: enabled. gitEnabled still needs
//     a ref, so the lifecycle is dormant for that project anyway — but the local merge
//     job must not substitute for the rail on a rail boot (the pre-collapse verdict).
//   - a repo-less cloud boot (the hook returns nil) and a resolver with no rail dep:
//     dormant, exactly as before.
func Test_RailLifecycleEnabled_ReadsWhatTheResolverAnswers(t *testing.T) {
	const projectID = ProjectID("proj-1")
	catalog := func(ProjectID) (sourcecontrol.RepoRef, bool) { return sourcecontrol.RepoRef("acct|acct/p"), true }
	gitLocal := func(pid ProjectID) (sourcecontrol.RepoRef, bool) {
		return sourcecontrol.GitLocalRepoRefForProject(sourcecontrol.ProjectID(pid)), true
	}
	miss := func(ProjectID) (sourcecontrol.RepoRef, bool) { return sourcecontrol.RepoRef(""), false }
	cases := []struct {
		name string
		rail sourcecontrol.SourceControlAccess
		repo func(ProjectID) (sourcecontrol.RepoRef, bool)
		want bool
	}{
		{"cloud / creds-ful local: the catalog resolves the project's repo", &stubRail{}, catalog, true},
		{"local profile: GitLocal rail + GitLocal resolver", &stubRail{}, gitLocal, false},
		{"rail boot whose catalog misses this project", &stubRail{}, miss, true},
		{"repo-less cloud boot (nil resolver)", &stubRail{}, nil, false},
		{"resolver without a rail dep", nil, catalog, false},
		{"neither", nil, nil, false},
	}
	for _, tc := range cases {
		if got := railLifecycleEnabled(tc.rail, tc.repo)(projectID); got != tc.want {
			t.Fatalf("%s: railLifecycleEnabled = %v, want %v", tc.name, got, tc.want)
		}
	}
}

// ---- Tests: episode capture seam (SP1 Task 7) -------------------------------
//
// The invariant under test: every terminal observation of an agentic construction
// dispatch produces EXACTLY ONE ledger record — the mined summary when there is one, an
// explicit GAP record when there is not — and the append can never take the business
// workflow down with it.

// csCaptureSeamSummary is the mined summary the local executor reports on a terminal
// observation. Every field is checked for VERBATIM carry-through below.
func csCaptureSeamSummary() *agenticjob.EpisodeSummary {
	model := "claude-sonnet-4"
	cost := 0.42
	turns := int64(7)
	trace := ".aiarch/traces/ep-1.jsonl"
	streamed := agenticjob.EpisodeUsage{In: 90, Out: 40, CacheRead: 5, CacheCreate: 2}
	return &agenticjob.EpisodeSummary{
		EpisodeID:      "ep-1",
		Model:          &model,
		Usage:          agenticjob.EpisodeUsage{In: 100, Out: 50, CacheRead: 10, CacheCreate: 3},
		StreamedUsage:  &streamed,
		CostUSD:        &cost,
		NumTurns:       &turns,
		ToolCallCounts: map[string]int64{"Read": 4, "Edit": 2},
		SubagentSpans:  []agenticjob.SubagentSpan{{ToolUseID: "tu-1"}},
		StartedAt:      time.Date(2026, 8, 2, 10, 0, 0, 0, time.UTC),
		EndedAt:        time.Date(2026, 8, 2, 10, 5, 0, 0, time.UTC),
		Outcome:        agenticjob.EpisodeSucceeded,
		TracePath:      &trace,
	}
}

// testEpisodeRecordForInput carries episodeRecordFor's real (non-ctx) parameters
// through a Temporal test workflow. obs is left at its zero value (Episode nil): the
// GAP branch and the summary branch compute TargetRef identically before branching, so
// the gap branch alone is enough to exercise the attempt-key assembly this test targets.
type testEpisodeRecordForInput struct {
	IDSeed     string
	ActivityID string
	Task       projectstate.MethodTask
	Attempt    int
}

func testEpisodeRecordForWorkflow(ctx workflow.Context, in testEpisodeRecordForInput) (episode.EpisodeRecord, error) {
	return episodeRecordFor(ctx, csPipelineObservation{}, in.IDSeed, in.ActivityID, in.Task, in.Attempt), nil
}

func TestEpisodeRecordFor_TargetRefCarriesTheAttemptKey(t *testing.T) {
	var ts testsuite.WorkflowTestSuite
	env := ts.NewTestWorkflowEnvironment()
	env.ExecuteWorkflow(testEpisodeRecordForWorkflow, testEpisodeRecordForInput{
		IDSeed: "seed", ActivityID: "C-billing-manager", Task: projectstate.TaskDetailedDesign, Attempt: 2,
	})
	if err := env.GetWorkflowError(); err != nil {
		t.Fatalf("workflow error: %v", err)
	}
	var rec episode.EpisodeRecord
	if err := env.GetWorkflowResult(&rec); err != nil {
		t.Fatalf("decode result: %v", err)
	}

	want := "C-billing-manager:detailedDesign:2"
	if rec.TargetRef != want {
		t.Errorf("TargetRef = %q, want %q — a bare activityId makes the episode permanently unjoinable", rec.TargetRef, want)
	}
}

