// TestGetPumpStatus_AHungDescribeIsBounded: the describe is bounded by pumpRPCTimeout,
// so a hung call returns Infrastructure promptly instead of hanging the read.
func TestGetPumpStatus_AHungDescribeIsBounded(t *testing.T) {
	old := pumpRPCTimeout
	pumpRPCTimeout = 50 * time.Millisecond
	t.Cleanup(func() { pumpRPCTimeout = old })
	pid := ProjectID(uuid.NewString())
	mc := &temporalmocks.Client{}
	mc.On("DescribeWorkflowExecution", mock.Anything, pumpWorkflowID(pid), "").
		Run(func(args mock.Arguments) { <-args.Get(0).(context.Context).Done() }).
		Return((*workflowservice.DescribeWorkflowExecutionResponse)(nil), context.DeadlineExceeded)
	begin := time.Now()
	_, err := newTestConstructionManager(mc).GetPumpStatus(testCtx(), pid)
	if got := asConstructionError(t, err).Kind; got != fwmanager.Infrastructure {
		t.Fatalf("want Infrastructure for a hung describe, got %s", got)
	}
	if waited := time.Since(begin); waited > 2*time.Second {
		t.Fatalf("the describe was not bounded: waited %s", waited)
	}
}

// TestGetPumpStatus_EmptyProjectIsContractMisuse: nothing is described for an empty id.
func TestGetPumpStatus_EmptyProjectIsContractMisuse(t *testing.T) {
	mc := &temporalmocks.Client{}
	_, err := newTestConstructionManager(mc).GetPumpStatus(testCtx(), "")
	if got := asConstructionError(t, err).Kind; got != fwmanager.ContractMisuse {
		t.Fatalf("want ContractMisuse, got %s", got)
	}
	mc.AssertNotCalled(t, "DescribeWorkflowExecution", mock.Anything, mock.Anything, mock.Anything)
}

// ===========================================================================
// B1.7 — RESUME (plan-B1-B2 amendment §B): the recorded pause binds every pump,
// Begin on a paused project is refused, and ResumeProject is the one way back.
// ===========================================================================

// pausedProject is a project in construction whose pause is recorded.
func pausedProject() projectstate.Project {
	return projectstate.Project{ID: "p-res", Phase: projectstate.PhaseConstruction, OperatorPaused: true, PauseReason: "operator halt", Version: 7}
}

// resumeManager wires a façade over mc and a fake store serving proj.
func resumeManager(mc client.Client, proj projectstate.Project) (*constructionManager, *csFakeProjectState) {
	ps := &csFakeProjectState{project: proj, version: proj.Version}
	return newConstructionManager(mc, fakeFullProjectState{ps}, nil, nil, nil, nil, nil, fakeConstructionTransition{ps}, nil, nil, nil, nil, nil, 0, "", nil, sdpEngines{}), ps
}

func constructionErrorKind(err error) fwmanager.Kind {
	var fe *fwmanager.Error
	if errors.As(err, &fe) {
		return fe.Kind
	}
	return fwmanager.Unknown
}

// TestResumeProject_RefusalsInTheirPinnedOrder: ContractMisuse → NotFound → not in
// construction → not paused → a pause still being applied. Nothing is written, nothing
// is started, nothing is signalled on any refusal.
func TestResumeProject_RefusalsInTheirPinnedOrder(t *testing.T) {
	notConstruction := pausedProject()
	notConstruction.Phase = projectstate.PhaseProjectDesign
	notPaused := pausedProject()
	notPaused.OperatorPaused, notPaused.PauseReason = false, ""
	// Every later refusal is armed in every case (a missing project, a pause in flight),
	// so a refusal that is dropped falls through to the NEXT one — which says something
	// else. The message pins which refusal answered, not just its kind.
	notConstructionNotPaused := notConstruction
	notConstructionNotPaused.OperatorPaused = false
	cases := []struct {
		name     string
		id       ProjectID
		proj     projectstate.Project
		notFound bool
		inFlight bool
		want     fwmanager.Kind
		wantMsg  string
	}{
		{"empty id beats a missing project", "", pausedProject(), true, true, fwmanager.ContractMisuse, "empty projectId"},
		{"no project", "p-res", pausedProject(), true, true, fwmanager.NotFound, ""},
		{"not in construction beats not paused", "p-res", notConstructionNotPaused, false, true, fwmanager.FailedPrecondition, "not in construction"},
		{"not paused beats a pause in flight", "p-res", notPaused, false, true, fwmanager.FailedPrecondition, "not paused"},
		{"a pause still being applied", "p-res", pausedProject(), false, true, fwmanager.FailedPrecondition, "still being applied"},
	}
	for _, c := range cases {
		mc := &temporalmocks.Client{}
		if c.inFlight {
			mc.On("DescribeWorkflowExecution", mock.Anything, "p-res:construction", "").Return(describeStatus(enumspb.WORKFLOW_EXECUTION_STATUS_RUNNING), nil).Maybe()
		}
		m, ps := resumeManager(mc, c.proj)
		ps.notFound = c.notFound
		err := m.ResumeProject(testCtx(), c.id)
		if got := constructionErrorKind(err); got != c.want {
			t.Errorf("%s: want %s, got %v", c.name, c.want, err)
		}
		if c.wantMsg != "" && (err == nil || !strings.Contains(err.Error(), c.wantMsg)) {
			t.Errorf("%s: want the refusal that says %q, got %v", c.name, c.wantMsg, err)
		}
		if ps.resumed != 0 {
			t.Errorf("%s: a refusal must write nothing", c.name)
		}
		mc.AssertNotCalled(t, "ExecuteWorkflow", mock.Anything, mock.Anything, mock.Anything, mock.Anything)
		mc.AssertNotCalled(t, "SignalWorkflow", mock.Anything, mock.Anything, mock.Anything, mock.Anything, mock.Anything)
	}
}

// resumeStartMatcher matches exactly the one start ResumeProject may make: the
// project's one pump id, the one-pump policy pair, and an input with NO OperatorDriven.
func resumeStartMatcher(pid ProjectID) (any, any) {
	return mock.MatchedBy(func(o client.StartWorkflowOptions) bool {
			return o.ID == pumpWorkflowID(pid) &&
				o.WorkflowIDConflictPolicy == enumspb.WORKFLOW_ID_CONFLICT_POLICY_USE_EXISTING &&
				o.WorkflowIDReusePolicy == enumspb.WORKFLOW_ID_REUSE_POLICY_ALLOW_DUPLICATE
		}),
		pumpInput{ProjectID: pid}
}

// TestResumeProject_RecordsOnceThenStartsOrJoinsThePump: exactly one RA write, then one
// start-or-join of the pump (USE_EXISTING + ALLOW_DUPLICATE, not operator-driven), and no
// wait on its decision; the pause is cleared.
func TestResumeProject_RecordsOnceThenStartsOrJoinsThePump(t *testing.T) {
	mc := &temporalmocks.Client{}
	mc.On("DescribeWorkflowExecution", mock.Anything, "p-res:construction", "").
		Return((*workflowservice.DescribeWorkflowExecutionResponse)(nil), serviceerror.NewNotFound("no supervision run"))
	opts, input := resumeStartMatcher("p-res")
	mc.On("ExecuteWorkflow", mock.Anything, opts, executionKindPump, input).Return(fakePumpRun{id: "p-res:nextActivity", runID: "run-1"}, nil).Once()
	m, ps := resumeManager(mc, pausedProject())
	if err := m.ResumeProject(testCtx(), "p-res"); err != nil {
		t.Fatalf("ResumeProject: %v", err)
	}
	if ps.resumed != 1 || ps.project.OperatorPaused || ps.project.PauseReason != "" {
		t.Fatalf("want one resume write that clears the pause, got resumed=%d paused=%v reason=%q", ps.resumed, ps.project.OperatorPaused, ps.project.PauseReason)
	}
	mc.AssertExpectations(t)
	mc.AssertNotCalled(t, "QueryWorkflow", mock.Anything, mock.Anything, mock.Anything, mock.Anything)
	mc.AssertNotCalled(t, "SignalWorkflow", mock.Anything, mock.Anything, mock.Anything, mock.Anything, mock.Anything)
}

// TestResumeProject_AFailedStartStillResumes: once the record is written the resume has
// landed — the 30s sweep pumps the project — so a failed start is logged, never
// returned.
func TestResumeProject_AFailedStartStillResumes(t *testing.T) {
	mc := &temporalmocks.Client{}
	mc.On("DescribeWorkflowExecution", mock.Anything, "p-res:construction", "").Return(describeStatus(enumspb.WORKFLOW_EXECUTION_STATUS_COMPLETED), nil)
	opts, input := resumeStartMatcher("p-res")
	mc.On("ExecuteWorkflow", mock.Anything, opts, executionKindPump, input).Return(nil, serviceerror.NewUnavailable("frontend down"))
	m, ps := resumeManager(mc, pausedProject())
	if err := m.ResumeProject(testCtx(), "p-res"); err != nil {
		t.Fatalf("a failed pump start after the record must not fail the resume, got %v", err)
	}
	if ps.resumed != 1 {
		t.Fatalf("the resume must be recorded, got %d writes", ps.resumed)
	}
}

// TestResumeProject_ConflictRetryThenGiveUp: a version Conflict is re-read and retried;
// past resumeConflictAttempts it answers FailedPrecondition "changed concurrently".
func TestResumeProject_ConflictRetryThenGiveUp(t *testing.T) {
	for _, c := range []struct {
		conflicts int
		want      fwmanager.Kind
		writes    int
	}{{resumeConflictAttempts - 1, fwmanager.Unknown, 1}, {resumeConflictAttempts, fwmanager.FailedPrecondition, 0}} {
		mc := &temporalmocks.Client{}
		mc.On("DescribeWorkflowExecution", mock.Anything, "p-res:construction", "").Return(describeStatus(enumspb.WORKFLOW_EXECUTION_STATUS_COMPLETED), nil)
		opts, input := resumeStartMatcher("p-res")
		mc.On("ExecuteWorkflow", mock.Anything, opts, executionKindPump, input).Return(fakePumpRun{id: "p-res:nextActivity", runID: "run-1"}, nil).Maybe()
		m, ps := resumeManager(mc, pausedProject())
		ps.conflictFirst = c.conflicts
		err := m.ResumeProject(testCtx(), "p-res")
		if got := constructionErrorKind(err); got != c.want {
			t.Errorf("%d conflicts: want kind %s, got %v", c.conflicts, c.want, err)
		}
		if ps.resumed != c.writes {
			t.Errorf("%d conflicts: want %d landed writes, got %d", c.conflicts, c.writes, ps.resumed)
		}
	}
}

// TestResumeProject_ARetryReChecksThePause (I2): the first write conflicts because the
// project moved; the retry re-reads and re-checks everything the first try was allowed
// on. A new pause that landed in between is never cleared: nothing is written after the
// conflict, no pump starts, and the new pause stands.
func TestResumeProject_ARetryReChecksThePause(t *testing.T) {
	cases := []struct {
		name     string
		moved    func(*csFakeProjectState)
		inFlight bool
		wantMsg  string
	}{
		{"a new pause landed and is still being applied", func(f *csFakeProjectState) { f.project.PauseReason = "second halt" }, true, "still being applied"},
		{"a new pause landed and was relayed", func(f *csFakeProjectState) { f.project.PauseReason = "second halt" }, false, "a new pause (second halt) landed"},
		{"the same pause, now being re-applied", func(*csFakeProjectState) {}, true, "still being applied"},
		{"someone else resumed", func(f *csFakeProjectState) { f.project.OperatorPaused, f.project.PauseReason = false, "" }, false, "not paused"},
		{"the project left construction", func(f *csFakeProjectState) { f.project.Phase = projectstate.PhaseProjectDesign }, false, "left construction"},
	}
	for _, c := range cases {
		mc := &temporalmocks.Client{}
		mc.On("DescribeWorkflowExecution", mock.Anything, "p-res:construction", "").Return(describeStatus(enumspb.WORKFLOW_EXECUTION_STATUS_COMPLETED), nil).Once()
		second := enumspb.WORKFLOW_EXECUTION_STATUS_COMPLETED
		if c.inFlight {
			second = enumspb.WORKFLOW_EXECUTION_STATUS_RUNNING
		}
		mc.On("DescribeWorkflowExecution", mock.Anything, "p-res:construction", "").Return(describeStatus(second), nil).Maybe()
		m, ps := resumeManager(mc, pausedProject())
		ps.conflictFirst = 1
		ps.afterConflict = c.moved
		err := m.ResumeProject(testCtx(), "p-res")
		if got := constructionErrorKind(err); got != fwmanager.FailedPrecondition || !strings.Contains(err.Error(), c.wantMsg) {
			t.Errorf("%s: want FailedPrecondition saying %q, got %v", c.name, c.wantMsg, err)
		}
		if ps.resumed != 0 {
			t.Errorf("%s: nothing may be written after the conflict, got %d resume write(s)", c.name, ps.resumed)
		}
		mc.AssertNotCalled(t, "ExecuteWorkflow", mock.Anything, mock.Anything, mock.Anything, mock.Anything)
		if c.name != "someone else resumed" && c.name != "the project left construction" && (!ps.project.OperatorPaused || ps.project.PauseReason == "") {
			t.Errorf("%s: the pause must stand, got paused=%v reason=%q", c.name, ps.project.OperatorPaused, ps.project.PauseReason)
		}
	}
}

// TestResumeProject_ARetryOnAnUnrelatedWriteStillResumes: a conflict from a write that
// left the same pause standing and nothing in flight retries and resumes.
func TestResumeProject_ARetryOnAnUnrelatedWriteStillResumes(t *testing.T) {
	mc := &temporalmocks.Client{}
	mc.On("DescribeWorkflowExecution", mock.Anything, "p-res:construction", "").Return(describeStatus(enumspb.WORKFLOW_EXECUTION_STATUS_COMPLETED), nil)
	opts, input := resumeStartMatcher("p-res")
	mc.On("ExecuteWorkflow", mock.Anything, opts, executionKindPump, input).Return(fakePumpRun{id: "p-res:nextActivity", runID: "run-1"}, nil).Once()
	m, ps := resumeManager(mc, pausedProject())
	ps.conflictFirst = 1
	if err := m.ResumeProject(testCtx(), "p-res"); err != nil {
		t.Fatalf("an unrelated concurrent write must not stop the resume: %v", err)
	}
	if ps.resumed != 1 || ps.project.OperatorPaused {
		t.Fatalf("want one landed resume, got %d (paused=%v)", ps.resumed, ps.project.OperatorPaused)
	}
	mc.AssertNumberOfCalls(t, "DescribeWorkflowExecution", 2)
}

// TestExecuteNextActivity_PausedProjectIsRefusedBeforeAnyStart: Begin on a paused
// project answers FailedPrecondition naming the reason, and starts nothing (founder
// ruling 2026-09-13).
func TestExecuteNextActivity_PausedProjectIsRefusedBeforeAnyStart(t *testing.T) {
	mc := &temporalmocks.Client{}
	m, _ := resumeManager(mc, pausedProject())
	_, err := m.ExecuteNextActivity(testCtx(), "p-res", "t1")
	if got := constructionErrorKind(err); got != fwmanager.FailedPrecondition {
		t.Fatalf("want FailedPrecondition for Begin on a paused project, got %v", err)
	}
	if !strings.Contains(err.Error(), "paused (operator halt)") || !strings.Contains(err.Error(), "resume it to continue") {
		t.Fatalf("the refusal must name the pause and the way back, got %q", err.Error())
	}
	mc.AssertNotCalled(t, "ExecuteWorkflow", mock.Anything, mock.Anything, mock.Anything, mock.Anything)
}

// TestExecuteNextActivity_NoProjectStillStartsThePump: a project that does not exist
// cannot be paused, so Begin proceeds (the pump's own read is the quiet tick).
func TestExecuteNextActivity_NoProjectStillStartsThePump(t *testing.T) {
	mc := &temporalmocks.Client{}
	opts, input := resumeStartMatcher("p-res")
	mc.On("ExecuteWorkflow", mock.Anything, opts, executionKindPump, input).Return(nil, serviceerror.NewUnavailable("frontend down")).Once()
	m, ps := resumeManager(mc, pausedProject())
	ps.notFound = true
	if _, err := m.ExecuteNextActivity(testCtx(), "p-res", "t1"); constructionErrorKind(err) == fwmanager.FailedPrecondition {
		t.Fatalf("a missing project must not read as paused, got %v", err)
	}
	mc.AssertExpectations(t)
}

// ===========================================================================
// QueryActivityView — revision derivation (spec 2026-09-20 §2). Pure functions.
// ===========================================================================

// avServiceLifecycle is Figure A-1 as the lifecycle data states it: SRS → SRS Review →
// fork { Detailed Design → Design Review → Construction → Code Review → Integration }
// ∥ { STP → STP Review } → join Testing. A literal, so these tests pin the DERIVATION
// and not the data file.
func avServiceLifecycle() methodassets.Lifecycle {
	d := func(id, phase string, deps ...string) methodassets.LifecycleTask {
		return methodassets.LifecycleTask{ID: id, Kind: methodassets.LifecycleTaskDispatch, Title: id, Phase: phase, DependsOn: deps}
	}
	r := func(id, phase, reviews string, deps ...string) methodassets.LifecycleTask {
		return methodassets.LifecycleTask{ID: id, Kind: methodassets.LifecycleTaskReview, Title: id, Phase: phase, DependsOn: deps, Reviews: reviews}
	}
	return methodassets.Lifecycle{
		Type: "service",
		Phases: []methodassets.LifecyclePhase{
			{ID: "requirements", Label: "Requirements", Weight: 15, Gate: "srsReview"},
			{ID: "detailed_design", Label: "Detailed Design", Weight: 20, Gate: "designReview"},
			{ID: "test_plan", Label: "Test Plan", Weight: 10, Gate: "stpReview"},
			{ID: "construction", Label: "Construction", Weight: 40, Gate: "codeReview"},
			{ID: "integration", Label: "Integration", Weight: 15, Gate: "testing"},
		},
		Tasks: []methodassets.LifecycleTask{
			d("srs", "requirements"), r("srsReview", "requirements", "srs", "srs"),
			d("detailedDesign", "detailed_design", "srsReview"), r("designReview", "detailed_design", "detailedDesign", "detailedDesign"),
			d("stp", "test_plan", "srsReview"), r("stpReview", "test_plan", "stp", "stp"),
			d("construction", "construction", "designReview"), r("codeReview", "construction", "construction", "construction"),
			d("integration", "integration", "codeReview"), r("testing", "integration", "integration", "integration", "stpReview"),
		},
	}
}

func avAttempt(task projectstate.MethodTask, n int, outcome projectstate.TaskOutcome, origin projectstate.RecordOrigin) projectstate.TaskAttempt {
	a := ledgerAttempt("C-X", task, n, outcome)
	a.Provenance = projectstate.AttemptProvenance{Origin: origin, Basis: "test"}
	return a
}

func avObserved(task projectstate.MethodTask, n int, outcome projectstate.TaskOutcome) projectstate.TaskAttempt {
	return avAttempt(task, n, outcome, projectstate.OriginObserved)
}

// avResolved is what QueryActivityView hands normalizeAttempts for a service row: the
// ONE reconciled phase set, never the raw row.Phases. The C-X fixtures are all service
// activities, so the profile is fixed and the variant unused.
func avResolved(row projectstate.ActivityExecution) []projectstate.PhaseCompletion {
	profile := projectstate.ProfileFor(projectstate.ActivityTypeService, projectstate.TestVariantPlan)
	return projectstate.ResolvePhaseCompletions(profile, row.Attempts)
}

func avSendBack(gate, text string, comments ...projectstate.NoteComment) projectstate.OperatorNote {
	return projectstate.OperatorNote{NoteID: "n-" + text, Kind: projectstate.NoteSendBack, Gate: gate, Text: text, Comments: comments}
}

func avTask(t *testing.T, views []taskView, id string) taskView {
	t.Helper()
	for _, v := range views {
		if v.ID == id {
			return v
		}
	}
	t.Fatalf("no task %q in %+v", id, views)
	return taskView{}
}

func avOutcomes(v taskView) []string {
	out := make([]string, 0, len(v.Revisions))
	for _, r := range v.Revisions {
		out = append(out, r.Outcome)
	}
	return out
}

// avDump prints one normalized attempt per line — task/attempt/outcome — so a derivation
// failure reads as the ledger it produced rather than as a struct dump.
func avDump(attempts []projectstate.TaskAttempt) string {
	var b strings.Builder
	for _, a := range attempts {
		fmt.Fprintf(&b, "\t%s/%d/%s\n", a.Task, a.Attempt, a.Outcome)
	}
	return b.String()
}

var avSRSPassed = []projectstate.TaskAttempt{
	avObserved(projectstate.TaskSRS, 1, projectstate.OutcomePassed),
	avObserved(projectstate.TaskSRSReview, 1, projectstate.OutcomePassed),
}

func TestDeriveTaskViews_StatesAndRevisions(t *testing.T) {
	passed, rejected, failed, pending := projectstate.OutcomePassed, projectstate.OutcomeRejected, projectstate.OutcomeFailed, projectstate.OutcomePending
	with := func(extra ...projectstate.TaskAttempt) []projectstate.TaskAttempt {
		return append(slices.Clone(avSRSPassed), extra...)
	}
	cases := []struct {
		name     string
		attempts []projectstate.TaskAttempt
		notes    []projectstate.OperatorNote
		liveGate string
		want     map[string]string   // task id → state
		revs     map[string][]string // task id → revision outcomes
	}{
		{
			name: "nothing recorded: the root is pending, everything else locked",
			want: map[string]string{"srs": taskPending, "srsReview": taskLocked, "detailedDesign": taskLocked, "testing": taskLocked},
		},
		{
			name:     "the fork: a passed SRS Review unlocks BOTH branches; the join stays locked",
			attempts: with(),
			want:     map[string]string{"srsReview": taskPassed, "detailedDesign": taskPending, "stp": taskPending, "designReview": taskLocked, "testing": taskLocked},
		},
		{
			name: "a send-back opens revision 2; the dispatch and its review share the numbers",
			attempts: with(
				avObserved(projectstate.TaskDetailedDesign, 1, passed), avObserved(projectstate.TaskDesignReview, 1, rejected),
				avObserved(projectstate.TaskDetailedDesign, 2, passed), avObserved(projectstate.TaskDesignReview, 2, passed)),
			notes: []projectstate.OperatorNote{avSendBack("detailed_design", "split the op")},
			want:  map[string]string{"detailedDesign": taskPassed, "designReview": taskPassed, "construction": taskPending},
			revs:  map[string][]string{"detailedDesign": {revPassed, revPassed}, "designReview": {revSentBack, revPassed}},
		},
		{
			name: "failed and retried work before the gate is ONE revision",
			attempts: with(
				avObserved(projectstate.TaskDetailedDesign, 1, passed), avObserved(projectstate.TaskDesignReview, 1, passed),
				avObserved(projectstate.TaskConstruction, 1, failed), avObserved(projectstate.TaskConstruction, 2, failed),
				avObserved(projectstate.TaskConstruction, 3, passed), avObserved(projectstate.TaskCodeReview, 1, passed)),
			want: map[string]string{"construction": taskPassed, "codeReview": taskPassed},
			revs: map[string][]string{"construction": {revPassed}, "codeReview": {revPassed}},
		},
		{
			name:     "sent back and not yet redrafted: both tasks read sentBack",
			attempts: with(avObserved(projectstate.TaskDetailedDesign, 1, passed), avObserved(projectstate.TaskDesignReview, 1, rejected)),
			notes:    []projectstate.OperatorNote{avSendBack("detailed_design", "redo")},
			want:     map[string]string{"detailedDesign": taskSentBack, "designReview": taskSentBack, "construction": taskLocked},
		},
		{
			name: "the redraft is running: the dispatch runs, its review waits, the other branch is untouched",
			attempts: with(
				avObserved(projectstate.TaskDetailedDesign, 1, passed), avObserved(projectstate.TaskDesignReview, 1, rejected),
				avObserved(projectstate.TaskDetailedDesign, 2, pending), avObserved(projectstate.TaskSTP, 1, pending)),
			notes: []projectstate.OperatorNote{avSendBack("detailed_design", "redo")},
			want:  map[string]string{"detailedDesign": taskRunning, "designReview": taskPending, "stp": taskRunning, "stpReview": taskLocked},
			revs:  map[string][]string{"detailedDesign": {revPassed, revRunning}, "designReview": {revSentBack}},
		},
		{
			name:     "a live gate: the review task awaits the human",
			attempts: with(avObserved(projectstate.TaskDetailedDesign, 1, passed), avObserved(projectstate.TaskDesignReview, 1, pending)),
			liveGate: "detailed_design",
			want:     map[string]string{"detailedDesign": taskPassed, "designReview": taskAwaitingHuman},
			revs:     map[string][]string{"designReview": {revAwaitingHuman}},
		},
		{
			name:     "work that failed and was not retried",
			attempts: with(avObserved(projectstate.TaskDetailedDesign, 1, failed)),
			want:     map[string]string{"detailedDesign": taskFailed, "designReview": taskLocked},
			revs:     map[string][]string{"detailedDesign": {revFailed}},
		},
		{
			name:     "a partial backfill: a passed gate with no work attempt passes its work, and is not locked by silent ancestors",
			attempts: []projectstate.TaskAttempt{avAttempt(projectstate.TaskDesignReview, 1, passed, projectstate.OriginBackfilled)},
			want:     map[string]string{"srs": taskPending, "designReview": taskPassed, "detailedDesign": taskPassed, "construction": taskPending},
		},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			views := deriveTaskViews(avServiceLifecycle(), c.attempts, c.notes, nil, c.liveGate)
			if len(views) != 10 {
				t.Fatalf("want one view per lifecycle task (10), got %d", len(views))
			}
			for id, want := range c.want {
				if got := avTask(t, views, id).State; got != want {
					t.Errorf("%s state = %s, want %s", id, got, want)
				}
			}
			for id, want := range c.revs {
				if got := avOutcomes(avTask(t, views, id)); !slices.Equal(got, want) {
					t.Errorf("%s revisions = %v, want %v", id, got, want)
				}
			}
		})
	}
}

func TestDeriveTaskViews_RevisionMembersNoteAndProvenance(t *testing.T) {
	passed, rejected, failed := projectstate.OutcomePassed, projectstate.OutcomeRejected, projectstate.OutcomeFailed
	t0 := time.Date(2026, 9, 1, 9, 0, 0, 0, time.UTC)
	at := func(a projectstate.TaskAttempt, startMin, endMin int, episodeID string) projectstate.TaskAttempt {
		s, e := t0.Add(time.Duration(startMin)*time.Minute), t0.Add(time.Duration(endMin)*time.Minute)
		a.StartedAt, a.EndedAt = &s, &e
		if episodeID != "" {
			a.Evidence = projectstate.EvidenceRef{Kind: projectstate.EvidenceEpisode, Ref: episodeID}
		}
		return a
	}
	attempts := append(slices.Clone(avSRSPassed),
		at(avObserved(projectstate.TaskConstruction, 1, failed), 0, 10, "ep-c1"),
		at(avAttempt(projectstate.TaskConstruction, 2, passed, projectstate.OriginSynthesized), 11, 20, "ep-c2"),
		at(avObserved(projectstate.TaskTestClient, 1, passed), 12, 18, ""),
		at(avObserved(projectstate.TaskCodeReview, 1, rejected), 21, 30, ""),
		at(avObserved(projectstate.TaskConstruction, 3, passed), 31, 40, "ep-c3"),
		at(avObserved(projectstate.TaskCodeReview, 2, passed), 41, 45, ""),
	)
	older := avSendBack("construction", "predates the gate attempts — must stay unmatched")
	matched := avSendBack("construction", "handle the nil map",
		projectstate.NoteComment{JSONPath: "$.ops[0]", Text: "nil map"}, projectstate.NoteComment{JSONPath: "$.ops[1]", Text: "no test"})
	elsewhere := avSendBack("detailed_design", "another gate's note")
	views := deriveTaskViews(avServiceLifecycle(), attempts, []projectstate.OperatorNote{older, elsewhere, matched}, nil, "")

	avCheckWorkRevisions(t, t0, avTask(t, views, "construction").Revisions)
	avCheckGateRevisions(t, avTask(t, views, "codeReview").Revisions)
}

// avCheckWorkRevisions asserts the dispatch side of the run above: two revisions, the
// failed retry and the tandem test client folded into the first, the episode of the
// attempt that reached the gate, worst-origin contagion, and the revision's span.
func avCheckWorkRevisions(t *testing.T, t0 time.Time, work []taskRevision) {
	t.Helper()
	if len(work) != 2 {
		t.Fatalf("construction revisions = %d, want 2", len(work))
	}
	if got, want := work[0].AttemptIDs, []string{"C-X:construction:1", "C-X:construction:2", "C-X:testClient:1"}; !slices.Equal(got, want) {
		t.Errorf("revision 1 members = %v, want %v (the failed retry and the tandem test client are sub-attempts)", got, want)
	}
	if work[0].EpisodeID != "ep-c2" || work[1].EpisodeID != "ep-c3" {
		t.Errorf("episodes = %q, %q; want the attempt that reached the gate: ep-c2, ep-c3", work[0].EpisodeID, work[1].EpisodeID)
	}
	if work[0].Provenance != projectstate.OriginSynthesized || work[1].Provenance != projectstate.OriginObserved {
		t.Errorf("provenance = %q, %q; want synthesized (contagion from construction#2) then observed", work[0].Provenance, work[1].Provenance)
	}
	if work[0].StartedAt == nil || !work[0].StartedAt.Equal(t0) || work[0].EndedAt == nil || !work[0].EndedAt.Equal(t0.Add(20*time.Minute)) {
		t.Errorf("revision 1 spans %v–%v, want %v–%v", work[0].StartedAt, work[0].EndedAt, t0, t0.Add(20*time.Minute))
	}
}

// avCheckGateRevisions asserts the review side: shared numbering, and the send-back note
// matched by order with the tails aligned — the LAST construction note, not the oldest.
func avCheckGateRevisions(t *testing.T, gate []taskRevision) {
	t.Helper()
	if len(gate) != 2 || gate[0].N != 1 || gate[1].N != 2 {
		t.Fatalf("codeReview revisions = %+v, want n=1,2", gate)
	}
	if gate[0].Outcome != revSentBack || gate[0].Note != "handle the nil map" || len(gate[0].Comments) != 2 {
		t.Errorf("revision 1 = %+v, want sentBack carrying the LAST construction send-back note and its 2 comments", gate[0])
	}
	if gate[1].Note != "" || gate[0].EpisodeID != "" {
		t.Errorf("a passed review carries no note and a review revision no episode: %+v", gate)
	}
}

func TestNormalizeAttempts_ReconstructsALiveRun(t *testing.T) {
	t0 := time.Date(2026, 9, 1, 9, 0, 0, 0, time.UTC)
	row := projectstate.ActivityExecution{
		ActivityID: "C-X",
		// The requirements and test_plan gates passed; detailed_design's did not (the
		// send-back below), so the phase this run is working IN derives to detailed_design
		// — the first phase the resolved set does not hold complete. That derivation
		// replaces the stored CurrentPhase, which was stamped at phase entry and never
		// cleared.
		Attempts: []projectstate.TaskAttempt{
			avAttempt(projectstate.TaskSRS, 1, projectstate.OutcomePassed, projectstate.OriginBackfilled),
			avAttempt(projectstate.TaskSRSReview, 1, projectstate.OutcomePassed, projectstate.OriginBackfilled),
			avAttempt(projectstate.TaskSTPReview, 1, projectstate.OutcomePassed, projectstate.OriginBackfilled),
		},
		OperatorNotes: []projectstate.OperatorNote{{NoteID: "n1", Kind: projectstate.NoteSendBack, Gate: "detailed_design", Text: "redo", RecordedAt: t0.Add(20 * time.Minute)}},
	}
	episodes := []episode.EpisodeRecord{
		{EpisodeID: "ep-srs", TargetRef: "C-X:srs:1", StartedAt: t0, EndedAt: t0.Add(5 * time.Minute)},
		{EpisodeID: "ep-dd1", TargetRef: "C-X:detailedDesign:1", StartedAt: t0.Add(6 * time.Minute), EndedAt: t0.Add(15 * time.Minute)},
		{EpisodeID: "ep-dd2", TargetRef: "C-X:detailedDesign:2", StartedAt: t0.Add(21 * time.Minute), EndedAt: t0.Add(40 * time.Minute)},
		{EpisodeID: "ep-gap", TargetRef: "C-X:construction:1", StartedAt: t0.Add(51 * time.Minute), EndedAt: t0.Add(52 * time.Minute), Outcome: episode.EpisodeGap},
		{EpisodeID: "ep-legacy", TargetRef: "C-X"},       // pre-attempt-key record: not an attempt
		{EpisodeID: "ep-other", TargetRef: "C-XY:srs:1"}, // another activity sharing the prefix
	}
	live := &ConstructionSessionView{Stage: StagePipelineRunning}
	got := normalizeAttempts("C-X", row, avResolved(row), episodes, live)

	type key struct {
		id      string
		outcome projectstate.TaskOutcome
		origin  projectstate.RecordOrigin
	}
	var have []key
	for _, a := range got {
		have = append(have, key{a.AttemptID, a.Outcome, a.Provenance.Origin})
	}
	bf := projectstate.OriginBackfilled
	want := []key{
		{"C-X:srs:1", projectstate.OutcomePassed, bf},             // N1: the ledger row, verbatim
		{"C-X:srsReview:1", projectstate.OutcomePassed, bf},       // N1
		{"C-X:stpReview:1", projectstate.OutcomePassed, bf},       // N1
		{"C-X:detailedDesign:1", projectstate.OutcomePassed, bf},  // N2
		{"C-X:detailedDesign:2", projectstate.OutcomePassed, bf},  // N2
		{"C-X:construction:1", projectstate.OutcomeFailed, bf},    // N2: a gap is a failed attempt
		{"C-X:detailedDesign:3", projectstate.OutcomePending, bf}, // N3: the dispatch running now
		{"C-X:designReview:1", projectstate.OutcomeRejected, bf},  // N4: the send-back note
	}
	if !slices.Equal(have, want) {
		t.Fatalf("normalized attempts:\n got %v\nwant %v", have, want)
	}
	if got[0].Evidence.Ref != "ep-srs" {
		t.Errorf("N1: the ledger attempt must gain its episode as evidence, got %+v", got[0].Evidence)
	}
	for _, a := range got[1:] {
		if a.Provenance.Basis == "" {
			t.Errorf("%s: a reconstructed attempt must name its basis", a.AttemptID)
		}
	}
}

func TestNormalizeAttempts_ALiveGateIsAPendingGateAttempt(t *testing.T) {
	since := time.Date(2026, 9, 1, 10, 0, 0, 0, time.UTC)
	// A live gate hangs on the work it judges: the dispatch attempt is what materializes
	// the row's lifecycle inventory now that no phase set is stored.
	row := projectstate.ActivityExecution{ActivityID: "C-X", Attempts: []projectstate.TaskAttempt{
		avObserved(projectstate.TaskDetailedDesign, 1, projectstate.OutcomePassed)}}
	live := &ConstructionSessionView{Stage: StageAwaitingApproval, AwaitingGate: ptrTo("detailed_design"), AwaitingSince: &since}
	got := normalizeAttempts("C-X", row, avResolved(row), nil, live)
	gate := got[len(got)-1]
	if len(got) != 2 || gate.AttemptID != "C-X:designReview:1" || gate.Outcome != projectstate.OutcomePending ||
		gate.StartedAt == nil || !gate.StartedAt.Equal(since) {
		t.Fatalf("want a pending designReview#1 since %v behind its dispatch, got %+v", since, got)
	}
}

// ENTRY CRITERION (a), spec §8. Once the workflow persists a gate rejection (stage 3
// Task 5) the send-back note that accompanies it is EVIDENCE OF THAT ATTEMPT, not of
// another one. N4 used to append one rejected attempt per note unconditionally and
// number it after the ledger's highest, so a single send-back read as two revisions AND
// the last gate attempt was a rejection on an activity whose gate had already passed.
func TestNormalizeAttempts_APersistedRejectionIsNotReconstructedTwice(t *testing.T) {
	row := projectstate.ActivityExecution{
		ActivityID: "C-X",
		Attempts: []projectstate.TaskAttempt{
			avObserved(projectstate.TaskDetailedDesign, 1, projectstate.OutcomePassed),
			avObserved(projectstate.TaskDesignReview, 1, projectstate.OutcomeRejected),
			avObserved(projectstate.TaskDetailedDesign, 2, projectstate.OutcomePassed),
			avObserved(projectstate.TaskDesignReview, 2, projectstate.OutcomePassed),
		},
		OperatorNotes: []projectstate.OperatorNote{
			avSendBack("detailed_design", "tighten the contract"),
		},
	}
	got := normalizeAttempts("C-X", row, avResolved(row), nil, nil)
	gates := 0
	var last projectstate.TaskOutcome
	for _, a := range got {
		if a.Task == projectstate.TaskDesignReview {
			gates++
			last = a.Outcome
		}
	}
	if gates != 2 {
		t.Fatalf("the ledger holds 2 designReview attempts and the note is evidence of the first; got %d:\n%s", gates, avDump(got))
	}
	if last != projectstate.OutcomePassed {
		t.Fatalf("the gate passed on revision 2; the last designReview attempt reads %q", last)
	}
}

// The reconstruction path is unchanged for a row that predates the ledger: a note with
// NO recorded rejection is still the only evidence there is.
func TestNormalizeAttempts_ANoteWithoutALedgerRejectionIsStillReconstructed(t *testing.T) {
	row := projectstate.ActivityExecution{
		ActivityID: "C-X",
		// The work attempt is what materializes the row's lifecycle inventory now that no
		// phase set is stored; the note is the only evidence of the gate that judged it.
		Attempts:      []projectstate.TaskAttempt{avObserved(projectstate.TaskDetailedDesign, 1, projectstate.OutcomePassed)},
		OperatorNotes: []projectstate.OperatorNote{avSendBack("detailed_design", "tighten the contract")},
	}
	got := normalizeAttempts("C-X", row, avResolved(row), nil, nil)
	gates := 0
	for _, a := range got {
		if a.Task == projectstate.TaskDesignReview && a.Outcome == projectstate.OutcomeRejected {
			gates++
		}
	}
	if gates != 1 {
		t.Fatalf("a note with no ledger rejection must still reconstruct one; got %d:\n%s", gates, avDump(got))
	}
}

// Tails aligned: two notes, one recorded rejection — the NEWER note is the recorded
// one, so only the OLDER is reconstructed.
func TestNormalizeAttempts_MoreNotesThanLedgerRejectionsReconstructsTheOldest(t *testing.T) {
	row := projectstate.ActivityExecution{
		ActivityID: "C-X",
		Attempts: []projectstate.TaskAttempt{
			avObserved(projectstate.TaskDesignReview, 1, projectstate.OutcomeRejected),
		},
		OperatorNotes: []projectstate.OperatorNote{
			avSendBack("detailed_design", "older"),
			avSendBack("detailed_design", "newer"),
		},
	}
	got := normalizeAttempts("C-X", row, avResolved(row), nil, nil)
	gates := 0
	for _, a := range got {
		if a.Task == projectstate.TaskDesignReview {
			gates++
		}
	}
	if gates != 2 {
		t.Fatalf("2 notes, 1 recorded rejection ⇒ exactly 1 reconstructed; got %d designReview attempts:\n%s", gates, avDump(got))
	}
}

// ENTRY CRITERION (a), spec §8 — the STRADDLING row, end to end. The ledger holds a real
// rejection AND the real pass that followed it; an OLDER send-back note has no ledger
// match because it predates the ledger. Numbering the reconstructed rejection after the
// ledger's highest made it the gate's LAST attempt, so phaseRevisions (which sorts by
// .Attempt) put it last and reviewEvidenceState read a passed, merged gate as sentBack.
// A pre-ledger rejection is the OLDEST revision and must sort first.
func TestNormalizeAttempts_APreLedgerNoteSortsBeforeTheLedgersGateAttempts(t *testing.T) {
	row := projectstate.ActivityExecution{
		ActivityID: "C-X",
		Attempts: []projectstate.TaskAttempt{
			avObserved(projectstate.TaskDetailedDesign, 1, projectstate.OutcomePassed),
			avObserved(projectstate.TaskDesignReview, 1, projectstate.OutcomeRejected),
			avObserved(projectstate.TaskDetailedDesign, 2, projectstate.OutcomePassed),
			avObserved(projectstate.TaskDesignReview, 2, projectstate.OutcomePassed),
		},
		OperatorNotes: []projectstate.OperatorNote{
			avSendBack("detailed_design", "older, from before the ledger"),
			avSendBack("detailed_design", "the recorded rejection's own note"),
		},
	}
	attempts := normalizeAttempts("C-X", row, avResolved(row), nil, nil)
	v := avTask(t, deriveTaskViews(avServiceLifecycle(), attempts, row.OperatorNotes, nil, ""), "designReview")
	if want := []string{revSentBack, revSentBack, revPassed}; !slices.Equal(avOutcomes(v), want) {
		t.Fatalf("designReview revisions = %v, want %v (the pre-ledger note is the OLDEST revision):\n%s", avOutcomes(v), want, avDump(attempts))
	}
	if v.State != taskPassed {
		t.Fatalf("the gate passed on its last revision; designReview reads %q:\n%s", v.State, avDump(attempts))
	}
}

// The ledger may hold MORE rejections than the phase has notes — a rejection recorded
// with no note, or a note the operator never wrote. The subtraction goes negative and
// must add nothing at all.
func TestNormalizeAttempts_MoreLedgerRejectionsThanNotesReconstructsNothing(t *testing.T) {
	row := projectstate.ActivityExecution{
		ActivityID: "C-X",
		Attempts: []projectstate.TaskAttempt{
			avObserved(projectstate.TaskDesignReview, 1, projectstate.OutcomeRejected),
			avObserved(projectstate.TaskDesignReview, 2, projectstate.OutcomeRejected),
			avObserved(projectstate.TaskDesignReview, 3, projectstate.OutcomePassed),
		},
		OperatorNotes: []projectstate.OperatorNote{avSendBack("detailed_design", "only one note survived")},
	}
	got := normalizeAttempts("C-X", row, avResolved(row), nil, nil)
	var gates []projectstate.TaskAttempt
	for _, a := range got {
		if a.Task == projectstate.TaskDesignReview {
			gates = append(gates, a)
		}
	}
	if len(gates) != 3 {
		t.Fatalf("3 recorded gate attempts and 1 note ⇒ nothing reconstructed; got %d:\n%s", len(gates), avDump(got))
	}
	for _, a := range gates {
		if a.Provenance.Origin != projectstate.OriginObserved {
			t.Fatalf("%s is reconstructed (%s); the ledger already held every rejection:\n%s", a.AttemptID, a.Provenance.Origin, avDump(got))
		}
	}
}

// ENTRY CRITERION (b), spec §8. ResolveConstructionRow reconciles the stored phase
// slice against the profile — dropping stored phases the profile does not carry and
// materializing profile phases the store never had — and QueryActivityView threw that
// reconciliation away while N4 re-derived completion from the raw slice. Two rules for
// one fact. A row stamped at dispatch as one type and classified at read as another is
// the case the resolver exists for, and the raw slice reconstructs a passed gate for a
// phase this activity's lifecycle does not have.
func TestNormalizeAttempts_GateCompletionComesFromTheResolvedSetOnly(t *testing.T) {
	row := projectstate.ActivityExecution{
		ActivityID: "N-STP",
		// A ledger written under the zero-value (service) task vocabulary; the read-time
		// classification is testing/plan, whose profile is requirements + construction
		// + integration and carries no detailed_design phase at all. The send-back note
		// names that phase, and the reconstruction must still refuse to invent a gate for
		// a phase the resolved profile does not carry.
		Attempts:      []projectstate.TaskAttempt{avObserved(projectstate.TaskSRS, 1, projectstate.OutcomePassed)},
		OperatorNotes: []projectstate.OperatorNote{avSendBack("detailed_design", "not a phase this lifecycle has")},
	}
	item := projectstate.ActivityItem{Name: "N-STP", WorkerClass: "test-engineer", Coding: false}
	_, _, resolved, classified := projectstate.ResolveConstructionRow(row, item)
	if !classified {
		t.Fatalf("N-STP must classify; the fixture is wrong")
	}
	got := normalizeAttempts("N-STP", row, resolved, nil, nil)
	for _, a := range got {
		if a.Phase == projectstate.MethodPhaseDetailedDesign {
			t.Fatalf("a detailed_design gate attempt on an activity whose resolved profile has no such phase: %+v\nresolved=%+v", a, resolved)
		}
	}
}

// The view's phase completion and the resolver's must be the SAME fact. A row whose
// gate task has a passed ATTEMPT but whose stored slice says otherwise (or vice versa)
// used to render one answer on the Activity Experience and another to the pump.
func TestActivityViewFrom_PhaseCompletionIsTheResolvedSet(t *testing.T) {
	lc := avServiceLifecycle()
	resolved := []projectstate.PhaseCompletion{
		{Phase: projectstate.MethodPhaseRequirements, Completed: true},
		{Phase: projectstate.MethodPhaseDetailedDesign, Completed: false},
	}
	// No task views at all: the derived task states are all pending, so the OLD rule
	// (states[ph.Gate] == taskPassed) says nothing is complete.
	// TestingVariant is an int enum; a service row's variant is never read (only a
	// testing row emits one), so the zero value stands for "no variant".
	got := activityViewFrom("C-X", projectstate.ActivityItem{Name: "C-X"}, projectstate.ActivityTypeService, projectstate.TestVariantPlan, lc, resolved, nil)
	for _, ph := range got.Phases {
		want := ph.ID == string(projectstate.MethodPhaseRequirements)
		if ph.Completed != want {
			t.Fatalf("phase %s completed=%v, want %v — the view must report the resolved set", ph.ID, ph.Completed, want)
		}
	}
}

// ===========================================================================
// QueryActivityView — the PERSISTED rounds (stage 3, task 7).
// ===========================================================================

// avRound is one round a real run wrote on the C-X row, with the construction rail's own
// id (projectstate.AttemptID) and its round number EQUAL to the gate attempt's number.
func avRound(gate projectstate.MethodTask, n int, outcome projectstate.ReviewRoundOutcome) projectstate.ReviewRound {
	p := projectstate.PhaseForTask(gate)
	return projectstate.ReviewRound{
		RoundID: projectstate.AttemptID("C-X", gate, n), TaskID: gate, Reviews: projectstate.AgentTaskFor(p),
		Round: int64(n), Outcome: outcome, SubjectRef: projectstate.SubjectRef{Kind: projectstate.SubjectArtifact, Ref: "C-X:detailedDesign:" + strconv.Itoa(n)},
		Provenance: projectstate.AttemptProvenance{Origin: projectstate.OriginObserved},
	}
}

// avArchitectureLifecycle is the architecture design activity as the pinned assets state
// it: ONE phase, one draft task, one review gate. A literal, like avServiceLifecycle, so
// the test pins the derivation rather than the data file.
func avArchitectureLifecycle() methodassets.Lifecycle {
	return methodassets.Lifecycle{
		Type:   "architecture",
		Phases: []methodassets.LifecyclePhase{{ID: "architecture", Label: "Architecture", Weight: 100, Gate: "architectureReview"}},
		Tasks: []methodassets.LifecycleTask{
			{ID: "architectureDraft", Kind: methodassets.LifecycleTaskDispatch, Title: "architectureDraft", Phase: "architecture"},
			{ID: "architectureReview", Kind: methodassets.LifecycleTaskReview, Title: "architectureReview", Phase: "architecture",
				Reviews: "architectureDraft", DependsOn: []string{"architectureDraft"}},
		},
	}
}

// The persisted round IS the revision. R4's tails-aligned note matching was a
// reconstruction for a world with no rounds; where a round exists, an ordering heuristic
// must not get a vote.
func TestDeriveTaskViews_PersistedRoundsWin(t *testing.T) {
	sentBack := avRound(projectstate.TaskDesignReview, 1, projectstate.RoundSentBack)
	sentBack.DecidedBy = "operator"
	sentBack.DecidedAt = "2026-09-20T10:00:00Z"
	sentBack.Reviewers = []projectstate.RoundReviewer{{Role: "architect", Actor: "architect"}, {Role: "human", Actor: "operator", Required: true}}
	sentBack.Verdicts = []projectstate.ReviewVerdict{
		{ReviewerRole: "architect", Actor: "architect", Verdict: projectstate.VerdictSendBack, Summary: "too wide", AttemptID: "C-X:detailedDesign:1", At: "2026-09-20T09:55:00Z"},
	}
	sentBack.Thread = []projectstate.ReviewComment{
		{ID: "r1c1", Anchor: "$.ops[0]", Text: "split this op", AuthorRole: "architect", Round: 1, Status: "answered",
			Replies: []projectstate.ReviewCommentReply{{ID: "r1c1a1", AuthorRole: "seniorDeveloper", Text: "split", At: "2026-09-20T11:00:00Z"}}},
	}
	rounds := []projectstate.ReviewRound{sentBack, avRound(projectstate.TaskDesignReview, 2, projectstate.RoundPassed)}
	// A misleading note: recorded, but the rounds are the record now.
	notes := []projectstate.OperatorNote{avSendBack("detailed_design", "stale note")}
	attempts := append(slices.Clone(avSRSPassed),
		avObserved(projectstate.TaskDetailedDesign, 1, projectstate.OutcomePassed),
		avObserved(projectstate.TaskDesignReview, 1, projectstate.OutcomeRejected),
		avObserved(projectstate.TaskDetailedDesign, 2, projectstate.OutcomePassed),
		avObserved(projectstate.TaskDesignReview, 2, projectstate.OutcomePassed),
	)
	view := avTask(t, deriveTaskViews(avServiceLifecycle(), attempts, notes, rounds, ""), "designReview")
	if got := avOutcomes(view); !slices.Equal(got, []string{revSentBack, revPassed}) {
		t.Fatalf("the persisted rounds are the revisions; got %v", got)
	}
	rev := view.Revisions[0]
	if rev.Provenance != projectstate.OriginObserved {
		t.Fatalf("a round a run wrote is observed, not backfilled; got %q", rev.Provenance)
	}
	if rev.Note == "stale note" {
		t.Fatalf("the OperatorNote must not reach a round-backed revision; got %q", rev.Note)
	}
	if len(rev.Verdicts) != 1 || rev.Verdicts[0].Summary != "too wide" {
		t.Fatalf("the round's verdicts are the revision's; got %+v", rev.Verdicts)
	}
	if len(rev.Thread) != 1 || rev.Thread[0].Status != "answered" || len(rev.Thread[0].Replies) != 1 {
		t.Fatalf("the round's thread travels with its replies and its status; got %+v", rev.Thread)
	}
	if rev.Round != 1 || rev.DecidedBy != "operator" || rev.DecidedAt != "2026-09-20T10:00:00Z" {
		t.Fatalf("the round's own number and decision must travel; got %+v", rev)
	}
	if rev.SubjectRef.Ref != "C-X:detailedDesign:1" {
		t.Fatalf("the revision judged the round's subject; got %+v", rev.SubjectRef)
	}
	// The join is by FIELDS — the gate attempt whose number IS the round's — never by
	// splitting the round id, which the design rail spells with four parts.
	if !slices.Equal(rev.AttemptIDs, []string{"C-X:designReview:1"}) {
		t.Fatalf("round 1 joins gate attempt 1; got %v", rev.AttemptIDs)
	}
	if len(rev.Reviewers) != 2 {
		t.Fatalf("the persisted roster travels with the revision; got %+v", rev.Reviewers)
	}
}

// A row that predates the ledger still reconstructs, and says so.
func TestDeriveTaskViews_PreLedgerRowStillReconstructs(t *testing.T) {
	notes := []projectstate.OperatorNote{avSendBack("detailed_design", "tighten it")}
	attempts := append(slices.Clone(avSRSPassed), avObserved(projectstate.TaskDesignReview, 1, projectstate.OutcomeRejected))
	views := deriveTaskViews(avServiceLifecycle(), attempts, notes, nil, "")
	rev := avTask(t, views, "designReview").Revisions[0]
	if rev.Outcome != revSentBack || rev.Note != "tighten it" {
		t.Fatalf("reconstruction must survive for pre-ledger rows; got %+v", rev)
	}
	if len(rev.Verdicts) != 0 || len(rev.Thread) != 0 {
		t.Fatalf("a reconstructed revision has no verdicts and no thread to offer; got %+v", rev)
	}
	if rev.Round != 1 {
		t.Fatalf("a reconstructed revision carries the gate attempt's number as its round; got %d", rev.Round)
	}
}

// The boundary row: SOME gates have rounds, SOME only have the older notes. The rule is
// per GATE, not per row — designReview reads its rounds, codeReview still reconstructs.
func TestDeriveTaskViews_RoundsBeatNotesPerGate(t *testing.T) {
	attempts := append(slices.Clone(avSRSPassed),
		avObserved(projectstate.TaskDetailedDesign, 1, projectstate.OutcomePassed),
		avObserved(projectstate.TaskDesignReview, 1, projectstate.OutcomePassed),
		avObserved(projectstate.TaskConstruction, 1, projectstate.OutcomePassed),
		avObserved(projectstate.TaskCodeReview, 1, projectstate.OutcomeRejected),
	)
	notes := []projectstate.OperatorNote{
		avSendBack("detailed_design", "a note the rounds already record"),
		avSendBack("construction", "the only record this gate has"),
	}
	rounds := []projectstate.ReviewRound{avRound(projectstate.TaskDesignReview, 1, projectstate.RoundPassed)}
	views := deriveTaskViews(avServiceLifecycle(), attempts, notes, rounds, "")
	if got := avOutcomes(avTask(t, views, "designReview")); !slices.Equal(got, []string{revPassed}) {
		t.Fatalf("designReview has a round and reads it alone; got %v", got)
	}
	code := avTask(t, views, "codeReview").Revisions
	if len(code) != 1 || code[0].Note != "the only record this gate has" {
		t.Fatalf("a gate with no round still reconstructs from its note; got %+v", code)
	}
}

// The design rails' round id has FOUR parts (activity:gate:artifactKind:n) because three
// artifact kinds share the architecture gate, so two kinds can hold the SAME round number
// on the same row. Nothing may parse the id: the join is (TaskID, Round) plus the ledger's
// own order, and the revision number is the position in that order.
func TestDeriveTaskViews_DesignRoundsAreReadWithoutParsingTheirIDs(t *testing.T) {
	round := func(kind string, n int, outcome projectstate.ReviewRoundOutcome) projectstate.ReviewRound {
		return projectstate.ReviewRound{
			RoundID: "architecture:architectureReview:" + kind + ":" + strconv.Itoa(n),
			TaskID:  "architectureReview", Reviews: "architectureDraft", Round: int64(n), Outcome: outcome,
			SubjectRef: projectstate.SubjectRef{Kind: projectstate.SubjectArtifact, Ref: kind},
			Provenance: projectstate.AttemptProvenance{Origin: projectstate.OriginObserved},
		}
	}
	// The design rail writes rounds and NO attempts (stage 3 gives it rounds only).
	rounds := []projectstate.ReviewRound{
		round("system", 1, projectstate.RoundSentBack),
		round("system", 2, projectstate.RoundPassed),
		round("operationalConcepts", 1, projectstate.RoundPassed),
	}
	views := deriveTaskViews(avArchitectureLifecycle(), nil, nil, rounds, "")
	gate := avTask(t, views, "architectureReview")
	if got := avOutcomes(gate); !slices.Equal(got, []string{revSentBack, revPassed, revPassed}) {
		t.Fatalf("three rounds, three revisions in stored order; got %v", got)
	}
	if gate.Revisions[2].Round != 1 || gate.Revisions[2].N != 3 {
		t.Fatalf("the second kind's round 1 is revision 3 with round 1; got n=%d round=%d", gate.Revisions[2].N, gate.Revisions[2].Round)
	}
	for _, rev := range gate.Revisions {
		if len(rev.AttemptIDs) != 0 {
			t.Fatalf("the design rail records no attempts, so a design round joins none; got %v", rev.AttemptIDs)
		}
	}
	if gate.State != taskPassed {
		t.Fatalf("the last round passed, so the gate reads passed; got %q", gate.State)
	}
	// Rule 8: the gate is the exit criterion, and the draft it judged has no attempts.
	if s := avTask(t, views, "architectureDraft").State; s != taskPassed {
		t.Fatalf("a passed gate carries its draft task; got %q", s)
	}
}

// TASK 5's PENDING-ROUND WINDOW. The construction rail opens the round at the gate and
// writes the gate ATTEMPT only when the round is decided, so a round with no attempt is
// the ordinary awaiting-human state — and a run that died in between leaves one forever.
// Either way the round alone is the revision, and N4 must not invent a second one beside
// it.
func TestDeriveTaskViews_APendingRoundWithNoGateAttemptIsTheRevision(t *testing.T) {
	row := projectstate.ActivityExecution{
		ActivityID: "C-X",
		Attempts: append(slices.Clone(avSRSPassed),
			avObserved(projectstate.TaskDetailedDesign, 1, projectstate.OutcomePassed)),
		Reviews: []projectstate.ReviewRound{avRound(projectstate.TaskDesignReview, 1, projectstate.RoundPending)},
	}
	live := &ConstructionSessionView{Stage: StageAwaitingApproval, AwaitingGate: strPtrOrNil("detailed_design")}
	attempts := normalizeAttempts("C-X", row, avResolved(row), nil, live)
	for _, a := range attempts {
		if a.Task == projectstate.TaskDesignReview {
			t.Fatalf("the pending ROUND is the record; N4 must not add a gate attempt beside it:\n%s", avDump(attempts))
		}
	}
	gate := avTask(t, deriveTaskViews(avServiceLifecycle(), attempts, row.OperatorNotes, row.Reviews, "detailed_design"), "designReview")
	if got := avOutcomes(gate); !slices.Equal(got, []string{revAwaitingHuman}) {
		t.Fatalf("one pending round at the live gate = one awaitingHuman revision; got %v", got)
	}
	if gate.Revisions[0].EndedAt != nil {
		t.Fatalf("an undecided round has not ended; got %v", gate.Revisions[0].EndedAt)
	}
	// The same round, with the session gone: still one revision, no longer at a human.
	away := avTask(t, deriveTaskViews(avServiceLifecycle(), attempts, row.OperatorNotes, row.Reviews, ""), "designReview")
	if got := avOutcomes(away); !slices.Equal(got, []string{revRunning}) {
		t.Fatalf("a pending round off the live gate is running; got %v", got)
	}
}

// THE BOUNDARY INSIDE ONE GATE. A row mid-flight when the ledger arrived has gate attempts
// recorded BEFORE any round, and the first round it opens is numbered off that ledger, so
// it starts above them. Those attempts are real, recorded send-backs; "any round at this
// gate wins outright" would drop them out of the history altogether.
func TestDeriveTaskViews_ARecordedAttemptBelowTheFirstRoundSurvives(t *testing.T) {
	attempts := append(slices.Clone(avSRSPassed),
		avObserved(projectstate.TaskDetailedDesign, 1, projectstate.OutcomePassed),
		avObserved(projectstate.TaskDesignReview, 1, projectstate.OutcomeRejected), // pre-round: no round was ever opened for it
		avObserved(projectstate.TaskDetailedDesign, 2, projectstate.OutcomePassed),
		avObserved(projectstate.TaskDesignReview, 2, projectstate.OutcomePassed),
	)
	notes := []projectstate.OperatorNote{avSendBack("detailed_design", "the send-back the ledger recorded before rounds existed")}
	rounds := []projectstate.ReviewRound{avRound(projectstate.TaskDesignReview, 2, projectstate.RoundPassed)}
	gate := avTask(t, deriveTaskViews(avServiceLifecycle(), attempts, notes, rounds, ""), "designReview")
	if got := avOutcomes(gate); !slices.Equal(got, []string{revSentBack, revPassed}) {
		t.Fatalf("the pre-round rejection is revision 1 and the round is revision 2; got %v", got)
	}
	pre := gate.Revisions[0]
	if pre.Note != "the send-back the ledger recorded before rounds existed" {
		t.Fatalf("a pre-round revision keeps its note; got %+v", pre)
	}
	if len(pre.Verdicts) != 0 || pre.DecidedBy != "" {
		t.Fatalf("a pre-round revision has no round facts; got %+v", pre)
	}
	if !slices.Equal(pre.AttemptIDs, []string{"C-X:designReview:1"}) {
		t.Fatalf("it is the RECORDED attempt, not a reconstruction of one; got %v", pre.AttemptIDs)
	}
	if gate.Revisions[1].N != 2 || gate.Revisions[1].Round != 2 {
		t.Fatalf("the round-backed revision continues the numbering; got n=%d round=%d", gate.Revisions[1].N, gate.Revisions[1].Round)
	}
	if gate.State != taskPassed {
		t.Fatalf("the LAST revision decides the gate's state, and the round passed; got %q", gate.State)
	}
}

// Its two null cases, so the split cannot quietly grow a third behaviour: a gate whose
// ledger starts AT the first round loses nothing to it, and a design gate (rounds, no
// attempts at all) is unchanged.
func TestDeriveTaskViews_TheSplitIsANoOpWhenNothingPrecedesTheRounds(t *testing.T) {
	attempts := append(slices.Clone(avSRSPassed),
		avObserved(projectstate.TaskDetailedDesign, 1, projectstate.OutcomePassed),
		avObserved(projectstate.TaskDesignReview, 1, projectstate.OutcomeRejected),
	)
	rounds := []projectstate.ReviewRound{avRound(projectstate.TaskDesignReview, 1, projectstate.RoundSentBack)}
	gate := avTask(t, deriveTaskViews(avServiceLifecycle(), attempts, nil, rounds, ""), "designReview")
	if got := avOutcomes(gate); !slices.Equal(got, []string{revSentBack}) {
		t.Fatalf("attempt 1 IS round 1 — one revision, not two; got %v", got)
	}
	if gate.Revisions[0].Provenance != projectstate.OriginObserved || gate.Revisions[0].Round != 1 {
		t.Fatalf("and it is the ROUND's revision; got %+v", gate.Revisions[0])
	}
}

// A gate that already has a round must not also have its phase completion reconstructed
// into a second, passed attempt: that is the double count Task 1 removed for notes, in
// its round-shaped form.
func TestNormalizeAttempts_AGateWithRoundsGetsNoReconstruction(t *testing.T) {
	row := projectstate.ActivityExecution{
		ActivityID: "C-X",
		Attempts: []projectstate.TaskAttempt{
			avObserved(projectstate.TaskDetailedDesign, 1, projectstate.OutcomePassed),
			avObserved(projectstate.TaskDesignReview, 1, projectstate.OutcomePassed),
		},
		Reviews:       []projectstate.ReviewRound{avRound(projectstate.TaskDesignReview, 1, projectstate.RoundPassed)},
		OperatorNotes: []projectstate.OperatorNote{avSendBack("detailed_design", "a note the round already records")},
	}
	got := normalizeAttempts("C-X", row, avResolved(row), nil, nil)
	gates := 0
	for _, a := range got {
		if a.Task == projectstate.TaskDesignReview {
			gates++
			if a.Provenance.Origin != projectstate.OriginObserved {
				t.Fatalf("%s is reconstructed; the round is the record:\n%s", a.AttemptID, avDump(got))
			}
		}
	}
	if gates != 1 {
		t.Fatalf("the ledger's own attempt and nothing else; got %d designReview attempts:\n%s", gates, avDump(got))
	}
}

// ===========================================================================
// QueryActivityView — the façade (contract amendment, stage 0).
// ===========================================================================

// avManager builds a façade over a project, an episode ledger and a strict client.
func avManager(c client.Client, proj projectstate.Project, eps *fakeEpisodes) *constructionManager {
	ps := &csFakeProjectState{project: proj}
	return newConstructionManager(c, fakeFullProjectState{ps}, nil, nil, nil, nil, nil, fakeConstructionTransition{ps}, nil, nil, nil, nil, eps, 0, "", nil, sdpEngines{})
}

func TestQueryActivityView_RefusesBlankIDs(t *testing.T) {
	m := avManager(nil, ledgerChain(), &fakeEpisodes{})
	for _, c := range []struct{ project, activity string }{{"", "A"}, {"p", ""}} {
		_, err := m.QueryActivityView(testCtx(), ProjectID(c.project), ActivityID(c.activity))
		if e := asConstructionError(t, err); e.Kind != fwmanager.ContractMisuse {
			t.Fatalf("(%q,%q): want ContractMisuse, got %s", c.project, c.activity, e.Kind)
		}
	}
}

// An id the committed plan does not hold is NotFound. Stage 0 also listed the three
// design ids here, because the derived plan did not hold them yet; stage 2 puts them in
// it, so they are served (TestQueryActivityView_ServesTheDesignPrefix) rather than 404'd.
func TestQueryActivityView_UnknownActivityIsNotFound(t *testing.T) {
	m := avManager(nil, ledgerChain(), &fakeEpisodes{})
	for _, id := range []string{"C-nope"} {
		_, err := m.QueryActivityView(testCtx(), "p", ActivityID(id))
		if e := asConstructionError(t, err); e.Kind != fwmanager.NotFound || !strings.Contains(e.Detail, id) {
			t.Fatalf("%s: want NotFound naming it, got %s %q", id, e.Kind, e.Detail)
		}
	}
}

// Stage 0 returned NotFound for these three because they were not activities yet. They
// are now, and each one serves its method-assets lifecycle.
func TestQueryActivityView_ServesTheDesignPrefix(t *testing.T) {
	want := map[string]struct{ phases, tasks int }{
		"requirements":  {4, 8},
		"architecture":  {1, 2},
		"projectDesign": {1, 1},
	}
	for id, w := range want {
		v, err := avManager(nil, planWithDesignPrefix(), &fakeEpisodes{}).QueryActivityView(testCtx(), "p", ActivityID(id))
		if err != nil {
			t.Fatalf("%s: %v", id, err)
		}
		if v.Type != id || len(v.Phases) != w.phases || len(v.Tasks) != w.tasks {
			t.Errorf("%s: type=%s phases=%d tasks=%d, want %s/%d/%d", id, v.Type, len(v.Phases), len(v.Tasks), id, w.phases, w.tasks)
		}
	}
}

// Not started: the whole lifecycle is returned, nothing has a revision, only the root is
// pending, and no session is asked for (a nil client would panic if it were).
func TestQueryActivityView_NotStarted_ReturnsTheWholeLifecycle(t *testing.T) {
	v, err := avManager(nil, ledgerChain(), &fakeEpisodes{}).QueryActivityView(testCtx(), "p", "A")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if v.State != ActivityViewNotStarted || v.Type != "service" || v.Name != "A" || v.ReviewSet != nil {
		t.Fatalf("view = %+v, want a not-started service activity with no review set", v)
	}
	if len(v.Phases) != 5 || len(v.Tasks) != 10 {
		t.Fatalf("want Figure A-1's 5 phases and 10 tasks, got %d and %d", len(v.Phases), len(v.Tasks))
	}
	for _, task := range v.Tasks {
		want := ActivityTaskLocked
		if len(task.DependsOn) == 0 {
			want = ActivityTaskPending
		}
		if task.State != want || task.Revisions == nil || len(task.Revisions) != 0 || task.DependsOn == nil {
			t.Errorf("%s: state=%s revisions=%v dependsOn=%v; want %s and empty, non-nil arrays", task.ID, task.State, task.Revisions, task.DependsOn, want)
		}
	}
}

// Done by its backfilled ledger: every task passed, every phase completed, provenance carried.
func TestQueryActivityView_Done_FromTheLedger(t *testing.T) {
	proj := ledgerChain()
	proj.ActivityExecution = map[string]projectstate.ActivityExecution{
		"A": {ActivityID: "A", Attempts: passedLedger("A", servicePhases...)},
	}
	v, err := avManager(nil, proj, &fakeEpisodes{}).QueryActivityView(testCtx(), "p", "A")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if v.State != ActivityViewDone {
		t.Fatalf("state = %s, want done", v.State)
	}
	for _, ph := range v.Phases {
		if !ph.Completed {
			t.Errorf("lifecycle phase %s not completed", ph.ID)
		}
	}
	for _, task := range v.Tasks {
		if task.State != ActivityTaskPassed || len(task.Revisions) != 1 || task.Revisions[0].Provenance != TaskRevisionBackfilled {
			t.Errorf("%s: %+v, want passed with one backfilled revision", task.ID, task)
		}
	}
}

// A live gate: the session is asked (the row is Running), the review task awaits the
// human, the send-back is revision 1 with its note and comments, the episode is joined
// by TargetRef = AttemptID, and the review set rides along.
func TestQueryActivityView_LiveGate_AfterASendBack(t *testing.T) {
	t0 := time.Date(2026, 9, 1, 9, 0, 0, 0, time.UTC)
	since := t0.Add(31 * time.Minute)
	eps := &fakeEpisodes{listRecords: []episode.EpisodeRecord{
		{EpisodeID: "ep-1", TargetRef: "A:detailedDesign:1", StartedAt: t0, EndedAt: t0.Add(10 * time.Minute)},
		{EpisodeID: "ep-2", TargetRef: "A:detailedDesign:2", StartedAt: t0.Add(21 * time.Minute), EndedAt: t0.Add(30 * time.Minute)},
	}}
	live := awaitingAt("detailed_design")
	live.AwaitingSince = &since
	live.ReviewSet = &ReviewSet{Reviewers: []Reviewer{{Role: "architect", Perspective: "architecture", MayAmend: true}}}
	mc := &temporalmocks.Client{}
	mc.On("QueryWorkflow", mock.Anything, deliveryActivityWorkflowID("p", "A"), "", querySessionState).Return(encodedJSON{v: live}, nil)

	v, err := avManager(mc, avSentBackAtTheDesignGate(t0), eps).QueryActivityView(testCtx(), "p", "A")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if eps.lastQuery.TargetRef == nil || *eps.lastQuery.TargetRef != "A" {
		t.Fatalf("episodes must be listed for the activity, got %+v", eps.lastQuery)
	}
	if v.State != ActivityViewAwaitingHuman || v.ReviewSet == nil || len(v.ReviewSet.Reviewers) != 1 {
		t.Fatalf("state=%s reviewSet=%+v, want awaitingHuman with the live review set", v.State, v.ReviewSet)
	}
	if v.ReviewSetError != nil {
		t.Fatalf("the engine answered, so nothing explains an absent set; got reviewSetError=%q", *v.ReviewSetError)
	}
	byID := map[string]ActivityTaskView{}
	for _, task := range v.Tasks {
		byID[task.ID] = task
	}
	avCheckLiveGateStates(t, byID)
	avCheckLiveGateRevisions(t, byID["designReview"].Revisions, since)
}

// avSentBackAtTheDesignGate is a Running service activity whose requirements phase is
// backfilled and whose detailed design was sent back once, with an anchored comment.
func avSentBackAtTheDesignGate(t0 time.Time) projectstate.Project {
	proj := ledgerChain()
	proj.ActivityExecution = map[string]projectstate.ActivityExecution{"A": {
		ActivityID: "A", StartedAt: &testExitAt, Attempts: passedLedger("A", projectstate.MethodPhaseRequirements),
		OperatorNotes: []projectstate.OperatorNote{{
			NoteID: "n1", Kind: projectstate.NoteSendBack, Gate: "detailed_design", Text: "split the op", RecordedAt: t0.Add(20 * time.Minute),
			Comments: []projectstate.NoteComment{{JSONPath: "$.ops[0]", Text: "too wide"}},
		}},
	}}
	return proj
}

// avCheckLiveGateStates asserts the task states around a live gate: the redraft passed
// and is joined to its episode, the gate awaits the human, and the DAG holds — the
// test-plan branch is open while construction waits behind the design gate.
func avCheckLiveGateStates(t *testing.T, byID map[string]ActivityTaskView) {
	t.Helper()
	work, gate := byID["detailedDesign"], byID["designReview"]
	if work.State != ActivityTaskPassed || len(work.Revisions) != 2 || work.Revisions[1].EpisodeID == nil || *work.Revisions[1].EpisodeID != "ep-2" {
		t.Fatalf("detailedDesign = %+v, want passed with revision 2 joined to ep-2", work)
	}
	if gate.State != ActivityTaskAwaitingHuman || len(gate.Revisions) != 2 {
		t.Fatalf("designReview = %+v, want awaitingHuman with 2 revisions", gate)
	}
	if byID["stp"].State != ActivityTaskPending || byID["construction"].State != ActivityTaskLocked {
		t.Errorf("the test-plan branch is open (%s) and construction locked (%s) behind the design gate", byID["stp"].State, byID["construction"].State)
	}
}

// avCheckLiveGateRevisions asserts the gate's two revisions: the send-back carries its
// note and anchored comment, and the occurrence now waiting started when the session says.
func avCheckLiveGateRevisions(t *testing.T, gate []TaskRevisionView, since time.Time) {
	t.Helper()
	r1, r2 := gate[0], gate[1]
	if r1.Outcome != TaskRevisionSentBack || r1.Note == nil || *r1.Note != "split the op" || r1.CommentCount != 1 || len(r1.Comments) != 1 || r1.Comments[0].JSONPath != "$.ops[0]" {
		t.Errorf("revision 1 = %+v, want sentBack carrying the note and its one comment", r1)
	}
	if r2.Outcome != TaskRevisionAwaitingHuman || r2.StartedAt == nil || !r2.StartedAt.Equal(since) {
		t.Errorf("revision 2 = %+v, want awaitingHuman since %v", r2, since)
	}
}

// A live gate with no roster explains itself: the engine's refusal rides the view beside
// the absent set, under the same live-gate condition (M1). Off a live gate neither shows.
func TestQueryActivityView_LiveGate_CarriesTheEngineRefusal(t *testing.T) {
	t0 := time.Date(2026, 9, 1, 9, 0, 0, 0, time.UTC)
	refusal := "ProposeReviews: unrecognised artifactKind"
	for _, c := range []struct {
		name    string
		live    ConstructionSessionView
		wantErr bool
	}{
		{"at the gate", awaitingAt("detailed_design"), true},
		{"no gate is live", ConstructionSessionView{Stage: StagePipelineRunning}, false},
	} {
		t.Run(c.name, func(t *testing.T) {
			live := c.live
			live.ReviewSetError = &refusal
			mc := &temporalmocks.Client{}
			mc.On("QueryWorkflow", mock.Anything, deliveryActivityWorkflowID("p", "A"), "", querySessionState).Return(encodedJSON{v: &live}, nil)
			v, err := avManager(mc, avSentBackAtTheDesignGate(t0), &fakeEpisodes{}).QueryActivityView(testCtx(), "p", "A")
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if v.ReviewSet != nil {
				t.Fatalf("a refused proposal leaves no set, got %+v", v.ReviewSet)
			}
			if got := v.ReviewSetError != nil; got != c.wantErr {
				t.Fatalf("reviewSetError present = %v, want %v (%+v)", got, c.wantErr, v.ReviewSetError)
			}
			if c.wantErr && *v.ReviewSetError != refusal {
				t.Fatalf("reviewSetError = %q, want the engine's reason %q", *v.ReviewSetError, refusal)
			}
		})
	}
}

// A Running row whose session is gone (past retention) still reads — without a live gate.
func TestQueryActivityView_RunningWithNoSession_StillReads(t *testing.T) {
	proj := ledgerChain()
	proj.ActivityExecution = map[string]projectstate.ActivityExecution{
		"A": {ActivityID: "A", StartedAt: &testExitAt},
	}
	mc := &temporalmocks.Client{}
	mc.On("QueryWorkflow", mock.Anything, deliveryActivityWorkflowID("p", "A"), "", querySessionState).
		Return(nil, serviceerror.NewNotFound("workflow not found"))
	v, err := avManager(mc, proj, &fakeEpisodes{}).QueryActivityView(testCtx(), "p", "A")
	if err != nil || v.State != ActivityViewRunning || v.ReviewSet != nil {
		t.Fatalf("view=%+v err=%v, want a running view with no review set", v, err)
	}
}

// QueryActivityView looks the activity's lifecycle up by projectstate.LifecycleKeyFor;
// the key RULE is pinned in projectstate (TestLifecycleKeyFor_CoversEveryTypeAndVariant).
// What is the Manager's business is that the pinned method-assets answers for every key
// this Manager can build — an unresolvable key surfaces as an Infrastructure error at a
// read the Activity Experience makes on every poll.
func TestQueryActivityView_EveryLifecycleKeyResolvesInThePinnedAssets(t *testing.T) {
	for _, c := range []struct {
		typ     projectstate.ActivityType
		variant projectstate.TestingVariant
	}{
		{projectstate.ActivityTypeService, projectstate.TestVariantPlan},
		{projectstate.ActivityTypeFrontend, projectstate.TestVariantPlan},
		{projectstate.ActivityTypeDeployment, projectstate.TestVariantPlan},
		{projectstate.ActivityTypeDocumentation, projectstate.TestVariantPlan},
		{projectstate.ActivityTypeUIDesign, projectstate.TestVariantPlan},
		{projectstate.ActivityTypeIntegration, projectstate.TestVariantPlan},
		{projectstate.ActivityTypeTesting, projectstate.TestVariantPlan},
		{projectstate.ActivityTypeTesting, projectstate.TestVariantHarness},
		{projectstate.ActivityTypeTesting, projectstate.TestVariantPerf},
		{projectstate.ActivityTypeTesting, projectstate.TestVariantSystemTest},
		{projectstate.ActivityTypeTesting, projectstate.TestVariantQAProcess},
	} {
		key := projectstate.LifecycleKeyFor(c.typ, c.variant)
		if _, ok := methodassets.LifecycleFor(key); !ok {
			t.Errorf("method-assets has no lifecycle for key %q", key)
		}
	}
}

// Task 7's wire strings ARE the contract's enum values; this is what lets the façade
// convert instead of mapping.
func TestActivityViewWireStringsMatchTheContract(t *testing.T) {
	pairs := map[string]string{
		taskPending: string(ActivityTaskPending), taskLocked: string(ActivityTaskLocked), taskRunning: string(ActivityTaskRunning),
		taskAwaitingHuman: string(ActivityTaskAwaitingHuman), taskPassed: string(ActivityTaskPassed),
		taskSentBack: string(ActivityTaskSentBack), taskFailed: string(ActivityTaskFailed),
		"rev:" + revRunning: "rev:" + string(TaskRevisionRunning), "rev:" + revAwaitingHuman: "rev:" + string(TaskRevisionAwaitingHuman),
		"rev:" + revPassed: "rev:" + string(TaskRevisionPassed), "rev:" + revSentBack: "rev:" + string(TaskRevisionSentBack),
		"rev:" + revFailed: "rev:" + string(TaskRevisionFailed), "rev:" + revSkipped: "rev:" + string(TaskRevisionSkipped),
		"rev:" + revWithdrawn:              "rev:" + string(TaskRevisionWithdrawn),
		methodassets.LifecycleTaskDispatch: string(ActivityTaskDispatch), methodassets.LifecycleTaskReview: string(ActivityTaskReview),
	}
	for internal, wire := range pairs {
		if internal != wire {
			t.Errorf("internal %q != contract %q", internal, wire)
		}
	}
}

// avVal reads an optional wire member as its zero value when absent, so an assertion
// reads as the fact it is checking rather than as a nil guard. Absent and zero are
// different on the wire and the tests below distinguish them where it matters.
func avVal[T comparable](p *T) T {
	var zero T
	if p == nil {
		return zero
	}
	return *p
}

// avSubjectKind is avVal for the one nested optional the revision carries.
func avSubjectKind(s *ReviewSubjectRef) string {
	if s == nil {
		return ""
	}
	return s.Kind
}

// avRoles, avVerdicts, avThread and avAnchors render the revision's four wire arrays as
// one comparable line each, so a failure prints what travelled instead of a struct dump.
func avRoles(seats []ReviewRosterSeat) []string {
	out := make([]string, 0, len(seats))
	for _, s := range seats {
		out = append(out, s.Role)
	}
	return out
}

func avVerdicts(verdicts []ReviewVerdictView) []string {
	out := make([]string, 0, len(verdicts))
	for _, v := range verdicts {
		out = append(out, fmt.Sprintf("%s/%s@%s", v.ReviewerRole, v.Verdict, v.At))
	}
	return out
}

func avThread(thread []ReviewThreadComment) []string {
	out := make([]string, 0, len(thread))
	for _, c := range thread {
		out = append(out, fmt.Sprintf("%s/%s/%d", c.ID, c.Status, len(c.Replies)))
	}
	return out
}

func avAnchors(comments []TaskRevisionComment) []string {
	out := make([]string, 0, len(comments))
	for _, c := range comments {
		out = append(out, c.JSONPath)
	}
	return out
}

// Task 8: the round's facts reach the WIRE. The revision-level members are optional
// because a pre-ledger row honestly has none of them, so what has to be pinned is that a
// round-backed revision carries them and a reconstructed one carries nothing it cannot
// back — an omitted member is the contract's way of saying "this record does not hold
// this", and a zero value shipped in its place would read as a fact.
func TestRevisionViews_ARoundBackedRevisionCarriesTheRoundOnTheWire(t *testing.T) {
	round := avRound(projectstate.TaskDesignReview, 2, projectstate.RoundSentBack)
	round.DecidedBy, round.DecidedAt = "operator", "2026-09-20T10:00:00Z"
	round.Reviewers = []projectstate.RoundReviewer{{Role: "architect", Actor: "architect"}}
	round.Verdicts = []projectstate.ReviewVerdict{
		{ReviewerRole: "architect", Actor: "architect", Verdict: projectstate.VerdictSendBack, Summary: "fold the pair", AttemptID: "C-X:detailedDesign:2", At: "2026-09-20T09:55:00Z"},
	}
	round.Thread = []projectstate.ReviewComment{
		{ID: "r2c1", Anchor: "$.ops[0]", Text: "fold them", AuthorRole: "architect", Round: 2, Status: "answered", Type: "changeRequest",
			Replies: []projectstate.ReviewCommentReply{{ID: "r2c1a1", AuthorRole: "seniorDeveloper", Text: "folded", At: "2026-09-20T11:00:00Z"}}},
	}
	got := revisionViews(roundRevisions([]projectstate.ReviewRound{round}, nil, false))
	if len(got) != 1 {
		t.Fatalf("one round, one revision; got %d", len(got))
	}
	v := got[0]
	// A table, not a chain of ifs: every row is one fact of the round that has to survive
	// the crossing, and the failure names the fact rather than the field.
	for _, c := range []struct {
		held bool
		what string
	}{
		{avVal(v.Round) == 2, "the round number"},
		{avVal(v.DecidedBy) == "operator", "who decided it"},
		{avVal(v.DecidedAt) == "2026-09-20T10:00:00Z", "when it was decided, verbatim"},
		{avSubjectKind(v.SubjectRef) == string(projectstate.SubjectArtifact), "what it judged"},
		{slices.Equal(avRoles(v.Reviewers), []string{"architect"}), "the roster"},
		{slices.Equal(avVerdicts(v.Verdicts), []string{"architect/sendBack@2026-09-20T09:55:00Z"}), "the verdicts, their timestamps verbatim and never parsed"},
		{slices.Equal(avThread(v.Thread), []string{"r2c1/answered/1"}), "the thread, with its status and its replies"},
		// The flat anchors stay too: a reader that has only ever known `comments` keeps
		// working on a round-backed revision, and the thread is where the rest lives.
		{v.CommentCount == 1, "the comment count"},
		{slices.Equal(avAnchors(v.Comments), []string{"$.ops[0]"}), "the thread's projection onto the flat comments"},
		{avVal(v.Note) == "fold the pair", "the send-back note, as the human-readable verdict summary"},
		{v.Provenance == TaskRevisionObserved, "observed provenance — a run wrote this round"},
	} {
		if !c.held {
			t.Errorf("%s does not reach the wire: %+v", c.what, v)
		}
	}
}

// Stage 4b1 entry criterion: a withdrawn round reads as withdrawn, not as failed. Before
// this, roundOutcome collapsed projectstate.RoundWithdrawn to revFailed for want of a wire
// member — a withdrawal is deliberate, and `failed` claimed the revision faulted.
func TestRevisionViews_AWithdrawnRoundReadsAsWithdrawn_NotFailed(t *testing.T) {
	round := avRound(projectstate.TaskDesignReview, 1, projectstate.RoundWithdrawn)
	round.DecidedBy = "operator"
	got := revisionViews(roundRevisions([]projectstate.ReviewRound{round}, nil, false))
	if len(got) != 1 {
		t.Fatalf("one round, one revision; got %d", len(got))
	}
	if got[0].Outcome != TaskRevisionWithdrawn {
		t.Fatalf("a withdrawn round must read as withdrawn, not %q", got[0].Outcome)
	}
}

// Its twin: a reconstruction ships NONE of the round's members, so the screen can tell
// "nobody recorded this" from "nobody reviewed".
func TestRevisionViews_AReconstructedRevisionShipsNoRoundMembers(t *testing.T) {
	rejected := avObserved(projectstate.TaskDesignReview, 1, projectstate.OutcomeRejected)
	notes := []projectstate.OperatorNote{avSendBack("detailed_design", "tighten it")}
	got := revisionViews(reconstructedReviewRevisions([]projectstate.TaskAttempt{rejected}, notes, "detailed_design", false))
	v := got[0]
	if len(v.Verdicts) != 0 || len(v.Thread) != 0 || len(v.Reviewers) != 0 {
		t.Errorf("a reconstruction has no round facts to ship; got %+v", v)
	}
	if v.SubjectRef != nil || v.DecidedBy != nil || v.DecidedAt != nil {
		t.Errorf("a reconstruction records no subject and no decision; got %+v", v)
	}
	if v.Round == nil || *v.Round != 1 {
		t.Errorf("it does carry the gate attempt's number as its round; got %v", v.Round)
	}
	if v.Note == nil || *v.Note != "tighten it" {
		t.Errorf("the send-back note is still the OperatorNote here; got %v", v.Note)
	}
	// And the pre-ledger placement beneath the ledger ships NO round: that number is a
	// sort position, not a count of reviews.
	below := avObserved(projectstate.TaskDesignReview, 1, projectstate.OutcomeRejected)
	below.Attempt = 0
	if r := revisionViews(reconstructedReviewRevisions([]projectstate.TaskAttempt{below}, nil, "detailed_design", false))[0].Round; r != nil {
		t.Fatalf("an attempt placed beneath the ledger has no round number to give; got %v", *r)
	}
}

// Test_ReviewRounds_TwoKindsOnOneGateDoNotBindOneAttempt is the stage-3 entry criterion
// made executable. Two rounds numbered 1 on ONE review task, judging DIFFERENT artifact
// kinds, must read as TWO revisions — and neither may claim the other's gate attempt.
//
// The four-part design RoundID keeps them distinct ROWS — nothing collides in storage —
// but the read path joins a round to the attempt it settled on the ROUND NUMBER alone,
// because ReviewRoundInput.roundId's own contract says nothing may parse a RoundID. So
// two kinds' round 1 both bound gate attempt 1, and the reader was shown one kind's
// revision citing the other's evidence.
//
// It is driven at the DERIVATION rather than through a lifecycle, deliberately: v0.9.0
// carries no lifecycle that puts two kinds on one gate task (measured — 14 lifecycles,
// and only sdpReview carries an artifactKind of its own), so a lifecycle-driven case
// would be asserting a shape the data cannot currently produce. What the read path must
// guarantee is that when it CAN — one method-assets release after GAP-4B-4 gives
// operationalConcepts a task on `architecture` — the ledger is already honest. A defence
// written after the data arrives is a migration; written before, it is a contract.
func Test_ReviewRounds_TwoKindsOnOneGateDoNotBindOneAttempt(t *testing.T) {
	gate := projectstate.TaskDesignReview
	system, concepts := avRound(gate, 1, projectstate.RoundSentBack), avRound(gate, 1, projectstate.RoundPassed)
	system.RoundID, system.ArtifactKind = "C-X:designReview:system:1", kindPtr(projectstate.KindSystem)
	concepts.RoundID, concepts.ArtifactKind = "C-X:designReview:operationalConcepts:1", kindPtr(projectstate.KindOperationalConcepts)
	// The ONE gate attempt the construction rail recorded at this gate. It is what the two
	// design rounds were both claiming.
	attempt := avObserved(gate, 1, projectstate.OutcomeRejected)

	revs := roundRevisions([]projectstate.ReviewRound{system, concepts}, []projectstate.TaskAttempt{attempt}, false)
	if len(revs) != 2 {
		t.Fatalf("two rounds at one gate are two revisions; got %d", len(revs))
	}
	// The identity rule, stated as the code states it: the gate is (task, kind) and the
	// revision is that plus the round number, so two kinds' round 1 are two identities.
	if roundJoinKey(system) == roundJoinKey(concepts) {
		t.Fatalf("two kinds' round 1 share one join key %q — the revision identity is still (taskId, round)", roundJoinKey(system))
	}
	if roundGateKey(gate, nil) != string(gate) {
		t.Errorf("a construction round has no kind and keys on the task alone; got %q", roundGateKey(gate, nil))
	}
	// THE ENTRY CRITERION. Before the kind was a field both revisions cited
	// "C-X:designReview:1"; a kinded round cannot claim a kindless attempt, and there is
	// no honest third answer while the design rails record no attempt ledger of their own.
	for i, rev := range revs {
		if len(rev.AttemptIDs) != 0 {
			t.Errorf("revision %d (round %d, kind %s) binds gate attempt %v; a round that judges an artifact kind may not claim an attempt recorded without one",
				i+1, rev.Round, []projectstate.ReviewRound{system, concepts}[i].ArtifactKind.WireName(), rev.AttemptIDs)
		}
	}
	// And the kindless round it shares the gate with still binds, exactly as it always
	// did: this widens the join, it does not move it.
	plain := avRound(gate, 1, projectstate.RoundSentBack)
	if got := roundRevisions([]projectstate.ReviewRound{plain}, []projectstate.TaskAttempt{attempt}, false); len(got[0].AttemptIDs) != 1 {
		t.Fatalf("a construction round still settles the gate attempt of its own number; got %v", got[0].AttemptIDs)
	}
}

// kindPtr is the optional field's constructor, used wherever a test opens a round that
// judges an artifact.
func kindPtr(k projectstate.ArtifactKind) *projectstate.ArtifactKind { return &k }

// Test_ReviewRounds_KindComesFromTheJudgedTask pins the resolution rule the real data
// forces (and which Task 8 implements at its writer): NO review task in v0.9.0 carries an
// artifactKind of its own except `sdpReview`, so a round's kind is
// lifecycleTaskByID(lc, t.Reviews).ArtifactKind. Measured spread: `designReview` appears
// in 8 lifecycles, `testing` and `codeReview` in 9, `srsReview` in 5 — so a reader that
// resolved the kind from the TASK ID would be guessing between up to nine answers, which
// is the whole reason the kind has to be stored ON the round.
func Test_ReviewRounds_KindComesFromTheJudgedTask(t *testing.T) {
	lifecycles := methodassets.Lifecycles()
	if len(lifecycles) != 14 {
		t.Fatalf("this case is measured against the 14 lifecycles v0.9.0 ships; got %d — re-measure before trusting the spread below", len(lifecycles))
	}
	spread := map[string]map[string]bool{}
	reviews := 0
	for _, lc := range lifecycles {
		for _, task := range lc.Tasks {
			if task.Kind != methodassets.LifecycleTaskReview {
				continue
			}
			reviews++
			kind := task.ArtifactKind
			if task.Reviews == "" {
				// sdpReview: the ONE review task that judges no dispatch, so it carries its
				// own kind or it names nothing.
				if kind == "" {
					t.Errorf("%s/%s reviews no task and carries no artifactKind — its round could name nothing", lc.Type, task.ID)
				}
			} else {
				if kind != "" {
					t.Errorf("%s/%s carries its OWN artifactKind %q as well as reviewing %q; the resolution rule would have two answers",
						lc.Type, task.ID, kind, task.Reviews)
				}
				judged, ok := lifecycleTaskByID(lc, task.Reviews)
				if !ok {
					t.Fatalf("%s/%s reviews %q, which the lifecycle does not declare", lc.Type, task.ID, task.Reviews)
				}
				kind = judged.ArtifactKind
				if kind == "" {
					t.Errorf("%s/%s resolves an EMPTY kind through %q; every dispatch must name what it produces", lc.Type, task.ID, task.Reviews)
				}
			}
			if spread[task.ID] == nil {
				spread[task.ID] = map[string]bool{}
			}
			spread[task.ID][kind] = true
		}
	}
	if reviews == 0 {
		t.Fatal("no review task was examined; the table asserted nothing")
	}
	// The measured spread, as the justification cites it. A task id that appears in more
	// than one lifecycle is exactly the case a (taskId, round) key cannot resolve.
	for id, want := range map[string]int{"designReview": 8, "codeReview": 9, "testing": 9, "srsReview": 5, "stpReview": 2} {
		if got := len(spreadCount(lifecycles, id)); got != want {
			t.Errorf("%s appears in %d lifecycles; the justification is measured at %d", id, got, want)
		}
	}
}

// spreadCount is the lifecycles one review task id appears in — the number that makes a
// (taskId, round) key a question with several answers.
func spreadCount(lifecycles []methodassets.Lifecycle, taskID string) []string {
	var out []string
	for _, lc := range lifecycles {
		if _, ok := lifecycleTaskByID(lc, taskID); ok {
			out = append(out, lc.Type)
		}
	}
	return out
}

// ===========================================================================
// STAGE 4a — THE SHARED REPLAY GUARD
//
// Before stage 4a each of the three Manager packages owned its own
// testdata/replay/ tree and its replay test could glob the whole of it. The
// three packages are now one, so the glob has to be scoped per rail and the
// "no fixture directory sits there unreplayed" half of the guard has to be
// stated once, for all three rails together. Nothing about what is asserted
// changed: every captured history still replays, a missing fixture still fails,
// an empty fixture directory is still a failure rather than a pass, and a
// fixture nothing names is still an error.
// ===========================================================================

// replayFixtureFiles globs the captured histories under the named fixture
// directories and keeps the per-directory vacuity guard: an empty directory is a
// failure, not a silent pass.
func replayFixtureFiles(t *testing.T, dirs []string) []string {
	t.Helper()
	var files []string
	for _, d := range dirs {
		got, err := filepath.Glob(filepath.Join("testdata", "replay", d, "*.json"))
		if err != nil {
			t.Fatal(err)
		}
		if len(got) == 0 {
			t.Fatalf("no replay fixtures found under testdata/replay/%s", d)
		}
		files = append(files, got...)
	}
	return files
}

func Test_ConstructRepoTarget_GitLocalRefIsNotAConstructionVenue(t *testing.T) {
	const projectID = ProjectID("proj-local-1")
	wf := &csWorkflows{Repo: func(pid ProjectID) (sourcecontrol.RepoRef, bool) {
		return sourcecontrol.GitLocalRepoRefForProject(sourcecontrol.ProjectID(pid)), true
	}}

	target, workflowFile, err := wf.constructRepoTarget(projectID)
	if err != nil {
		t.Fatalf("a GitLocal ref must resolve quietly, not error: %v", err)
	}
	if target != (agenticjob.RepoTarget{}) {
		t.Fatalf("RepoTarget = %+v, want the ZERO target — construction falls back to the configured central repo", target)
	}
	if workflowFile != "" {
		t.Fatalf("workflow file = %q, want \"\" so the RA leaves the dispatch's repo fields zero", workflowFile)
	}
}

// Test_ConstructRepoTarget_CatalogRefIsTheVenue is the positive companion: a real
// (catalog-resolved) RepoRef still retargets the dispatch at the project's own repo, so
// the guard above narrows nothing but the GitLocal case.
func Test_ConstructRepoTarget_CatalogRefIsTheVenue(t *testing.T) {
	// the same opaque literal every other rail fixture in this file uses.
	wf := &csWorkflows{Repo: func(ProjectID) (sourcecontrol.RepoRef, bool) {
		return sourcecontrol.RepoRef("acme|acme/billing-svc"), true
	}}

	target, workflowFile, err := wf.constructRepoTarget("proj-1")
	if err != nil {
		t.Fatalf("constructRepoTarget: %v", err)
	}
	if target.Owner != "acme" || target.Name != "billing-svc" {
		t.Fatalf("RepoTarget = %+v, want {acme billing-svc}", target)
	}
	if workflowFile != constructWorkflowFileName {
		t.Fatalf("workflow file = %q, want %q", workflowFile, constructWorkflowFileName)
	}
}

// ===========================================================================
// STAGE 4a fix round 2 — the CONSTRUCTION RAIL stays dormant on the local profile.
//
// Round 1 taught ONE construction reader (constructRepoTarget) that a GitLocal ref is
// not a venue. The second reader, the rail LIFECYCLE, was left reading the collapsed
// hook's design arm: rail != nil && repo != nil, both true on local, so RailEnabled
// flipped false → true and with it (a) startedCred took the CLOUD arm and minted a rail
// credential — a durable sourceControlAccess.getInstallationToken command the
// construction history never had — and (b) runLocalMergeStep skipped, so no local
// activity branch would ever merge. railLifecycleEnabled now reads what the resolver
// ANSWERS, through the same isGitLocalVenue recognition.
//
// The composition-root half of the pair is
// Test_DeliveryManagerRepo_LocalProfile_ResolvesTheGitLocalRef +
// Test_DeliveryManagerRepo_LocalProfile_AnswersTheRefConstructionRefuses (cmd/server).
// ===========================================================================

// railWired is the RailEnabled a test rig hands a WIRED PR-rail slice: enabled for every
// project, which is what the boot-level derivation answers for a catalog resolver.
func railWired(ProjectID) bool { return true }

// THE DRAIN CONTRACT IS A SET OF LITERAL STRINGS, RE-PINNED (final fix wave, B3). The
// deleted Test_WorkflowIDDerivation was the only assertion over them, and after it went
// neither replanSweepWorkflowID (in EITHER form) nor pauseTargetWorkflowID had a single test
// reference — the literals appeared in no assertion anywhere.
//
// These are not internal details: they are what the drain note TELLS AN OPERATOR TO DRAIN
// before this branch deploys, and what the pause signal is addressed to. A rename is invisible
// to every other gate in the repo — the code would keep compiling, the drain would silently
// cover nothing, and an in-flight sweep would survive a deploy it was supposed to be drained
// for. So the shapes are written out here as strings rather than derived, which is the only
// way a pin can fail when the deriver changes.
func Test_WorkflowIDDerivation(t *testing.T) {
	const pid = ProjectID("proj-1")
	scoped := pid
	for _, c := range []struct{ name, got, want string }{
		{"pump (tick-invariant)", pumpWorkflowID(pid), "proj-1:nextActivity"},
		{"pause / supervision target", pauseTargetWorkflowID(pid), "proj-1:construction"},
		{"replan sweep, per project", replanSweepWorkflowID(&scoped, "t7"), "proj-1:replanSweep:t7"},
		{"replan sweep, all projects", replanSweepWorkflowID(nil, "t7"), ":all:replanSweep:t7"},
		{"round sweep", roundSweepWorkflowID(pid, "t7"), "proj-1:roundSweep:t7"},
		{"generic activity child", deliveryActivityWorkflowID(pid, "C-MST"), "proj-1:activity:C-MST"},
	} {
		if c.got != c.want {
			t.Errorf("%s: id = %q, want %q — this string is in the drain note; changing it silently strands in-flight executions", c.name, c.got, c.want)
		}
	}
}

// THE LOCAL ARM, RESTORED (final fix wave, B2). It was the one assertion of the retired
// Test_DeliveryManager_LocalProfile_ConstructionRailDormant_DesignRailsResolveGitLocal that
// did NOT get retargeted, and it is the one that pins the CONSEQUENCE the stage-4a defect
// was made of: with railEnabled true on a local profile, csWorkflows.gitEnabled answers
// true, startedCred takes the CLOUD arm and mints a rail credential — a durable
// sourceControlAccess.getInstallationToken command the construction history never had — and
// runWalkMerge skips, so no local activity branch ever merges.
//
// It also guards the final fix wave's own work: liveCred re-mints on expiry and
// railWithAuthRetry bounds 403s, and BOTH are reached through gitEnabled. A local profile
// that answered true here would start minting and retrying against a rail that is not there.
func Test_DeliveryManager_LocalProfile_ConstructionRailDormant(t *testing.T) {
	m := fullyWiredDeliveryManager()
	m.cs.repo = func(pid ProjectID) (sourcecontrol.RepoRef, bool) {
		return sourcecontrol.GitLocalRepoRefForProject(sourcecontrol.ProjectID(pid)), true
	}
	if m.cs.railEnabled()("proj-1") {
		t.Fatal("a GitLocal ref is not a PR-rail venue; the construction rail must stay dormant")
	}
	// And the reader that matters: the workflow's own gate. gitEnabled is what every rail
	// verb and every credential mint routes through.
	wf := csNewWorkflows(wfDeps{
		Intervention: &fakeIntervention{directive: intervention.VarianceRetry},
		Review:       &fakeReview{},
		RailEnabled:  m.cs.railEnabled(),
		GitStatus:    newStubGitStatus(0),
		Repo:         m.cs.repo,
	})
	if _, ok := wf.gitEnabled("proj-1"); ok {
		t.Fatal("csWorkflows.gitEnabled must be false on the local profile — a true here mints a rail credential the local venue has no use for and skips the local merge")
	}
}

// The cloud arm of the same boot-level question: a catalog-resolved repo still lights
// the construction PR rail, so the recognition above narrows nothing but the GitLocal
// case.
func Test_DeliveryManager_CatalogResolver_ConstructionRailEnabled(t *testing.T) {
	m := fullyWiredDeliveryManager()
	m.cs.repo = func(ProjectID) (sourcecontrol.RepoRef, bool) {
		return sourcecontrol.RepoRef("acme|acme/billing-svc"), true
	}
	if !m.cs.railEnabled()("proj-1") {
		t.Fatal("a catalog-resolved project repo must light the construction PR rail")
	}
}

// ---------------------------------------------------------------------------
// THE LIFECYCLE-SHAPE ORACLE (stage 4b1 Task 1). Spec §9 asks for a Temporal
// test-suite case per lifecycle SHAPE: linear, fork/join in both branch orders,
// send-back re-opens only the judged pair, join waits for all, M0 no-send-back,
// human floor under vibes. They are written HERE, against the pre-4b1 rails, so
// that the generic DAG child is judged by cases that already ran rather than by
// cases written alongside it.
//
// THREE OF THE SEVEN FAIL TODAY, DELIBERATELY. The current child walks
// in.Activity.Phases — a FLAT []ActivityMethodPhase from
// ProfileFor(typ,variant).PhaseIDs() — so `service`'s phase order runs test_plan
// AFTER detailed_design and the fork in lifecycles.json (stp dependsOn
// [srsReview]; testing dependsOn [integration, stpReview]) is never read. A case
// marked shapeFailsUntilTheDAG asserts the parallel order and is SKIPPED with its
// reason until Task 8 lands; Task 8 Step 10 flips it to shapePassesToday and the
// flip is the acceptance. A skipped case that is never flipped is a plan failure,
// which is why shapeFailsUntilTheDAG names the task that owes it.
// ---------------------------------------------------------------------------

// shapeExpectation says whether a shape case can pass against the code in the
// tree at the commit that reads it.
type shapeExpectation int

const (
	shapePassesToday shapeExpectation = iota
	shapeFailsUntilTheDAG
)

// shapeOutcome is what every shape case asserts on.
//
// TWO order fields, and the distinction is the whole reason the fork is testable.
// TaskOrder is the order tasks were STARTED, and it is IDENTICAL in both branch-order
// cases by construction: readyTasks fans out in lifecycle DECLARATION order, which is
// deterministic, so once srsReview passes it always returns [detailedDesign, stp] in
// that order. Branch order is not a walker variable and must never be asserted as one.
// What a branch order actually changes is which branch's pipeline COMPLETES first, so
// CompletedOrder is the discriminator.
//
// Timeline is the THIRD field, and it is here because the fork's own claim — "both
// branches were in flight at once" — cannot be stated on the other two at all. They are
// separate projections of one walk, so "detailedDesign started before stp finished"
// compares an index in one slice against an index in another, which means nothing: the
// FIRST draft of this oracle did exactly that and passed today's strictly serial walk
// for the design-first case. Timeline is the merged log those two are projections of —
// "start:<task>" / "done:<task>" in the order they happened — and the overlap is
// asserted there. TaskOrder and CompletedOrder stay because Tasks 8 Step 10 and 11 Step
// 5 name them, and because declaration order and the completion discriminator read
// better as their own lists.
type shapeOutcome struct {
	TaskOrder      []string
	CompletedOrder []string
	Timeline       []string
	Dispatched     []string
	RoundsOpened   []string
	RoundsDecided  map[string]string
	Reopened       []string
	PhaseAdvanced  bool
	// SignalsDelivered is "<taskId>:<kind>" per routed signal that reached an inbox, in
	// order. Added by Task 8 for the same reason Task 1 added Timeline: the router's claim —
	// "the override reached the gate and not the polling sibling" — is not an ordering fact
	// about task starts and cannot be stated on any of the fields above.
	SignalsDelivered []string
	// SignalsDropped is the same for the messages the walk refused, so "too late" is a fact
	// the oracle can assert rather than an absence it has to infer.
	SignalsDropped []string
}

// The Timeline event prefixes. Bare literals on purpose: the log is read by an assertion
// in this file and by nothing else, and a shared constant would invite a reader to
// believe it is a wire format.
const (
	shapeEventStarted   = "start:"
	shapeEventCompleted = "done:"
)

// lifecycleShapeCase is one shape, its lifecycle key, the driver that runs it on
// whatever child the tree currently registers, and what it may assert today.
type lifecycleShapeCase struct {
	name      string
	typeKey   string
	drive     func(t *testing.T, rig *shapeRig) shapeOutcome
	wantToday shapeExpectation
}

// shapeRecorder is the observation side. Every task start, dispatch, round open and
// round decision the rig's fakes see is appended here in the order it happened;
// nothing is sorted, because order IS the assertion.
type shapeRecorder struct {
	mu        sync.Mutex
	started   []string
	completed []string
	events    []string
	jobs      []string
	opened    []string
	decided   map[string]string
	// delivered is "<taskId>:<kind>" per routed signal an INBOX actually took
	// (walkState.deliver). It exists because the walk's terminal cannot tell a delivered
	// override from a lost one: a gate that never receives one just waits for its decision
	// instead, so a case checking only the terminal would pass with the message gone.
	delivered []string
	// dropped is the same for a message the walk refused to deliver — a task that had already
	// finished. It is recorded because "dropped" and "quietly buffered for the next revision"
	// look identical from `delivered` alone, and the second is a real leak.
	dropped []string
}

func newShapeRecorder() *shapeRecorder {
	return &shapeRecorder{decided: map[string]string{}}
}

func (r *shapeRecorder) taskStarted(taskID string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.started = append(r.started, taskID)
	r.events = append(r.events, shapeEventStarted+taskID)
}

// taskCompleted is the fork's discriminator. It is recorded where the task's
// PIPELINE reaches a terminal — not where the walker marks the task passed — because
// a gated branch's task passes only after its human decision, and the fork's claim is
// about the work overlapping, not the gates.
func (r *shapeRecorder) taskCompleted(taskID string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.completed = append(r.completed, taskID)
	r.events = append(r.events, shapeEventCompleted+taskID)
}

func (r *shapeRecorder) jobDispatched(command string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.jobs = append(r.jobs, command)
}

// signalDelivered implements walkDeliveryRecorder.
func (r *shapeRecorder) signalDelivered(taskID, kind string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.delivered = append(r.delivered, taskID+":"+kind)
}

// signalDropped implements walkDeliveryRecorder.
func (r *shapeRecorder) signalDropped(taskID, kind string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.dropped = append(r.dropped, taskID+":"+kind)
}

func (r *shapeRecorder) roundOpened(roundID string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.opened = append(r.opened, roundID)
}

func (r *shapeRecorder) roundDecided(roundID, outcome string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.decided[roundID] = outcome
}

// outcome snapshots the recorder. Copies rather than handing out the slices, so a
// case that keeps driving after reading cannot retro-edit its own assertion.
func (r *shapeRecorder) outcome(reopened []string, phaseAdvanced bool) shapeOutcome {
	r.mu.Lock()
	defer r.mu.Unlock()
	out := shapeOutcome{
		TaskOrder:      append([]string(nil), r.started...),
		CompletedOrder: append([]string(nil), r.completed...),
		Timeline:       append([]string(nil), r.events...),
		Dispatched:     append([]string(nil), r.jobs...),
		RoundsOpened:   append([]string(nil), r.opened...),
		RoundsDecided:  make(map[string]string, len(r.decided)),
		Reopened:       append([]string(nil), reopened...),
		PhaseAdvanced:  phaseAdvanced,

		SignalsDelivered: append([]string(nil), r.delivered...),
		SignalsDropped:   append([]string(nil), r.dropped...),
	}
	maps.Copy(out.RoundsDecided, r.decided)
	return out
}

// shapeRig wraps whichever rig the tree's current child needs, plus the recorder
// the outcome is read out of. It declares NO fake of its own: the doubles are the
// ones the existing scenarios already register — registerConstruct's
// csFakeProjectState + csFakePipeline, registerCoAuthor's fakeProjectState +
// fakePipeline, pdRegisterGenActivities' pdFakeProjectState — each simply handed the
// recorder, so a shape case and a replay fixture exercise ONE set of store semantics
// rather than two that drift. Task 8 re-points `register` at the generic child;
// nothing else in this region changes.
type shapeRig struct {
	env      *testsuite.TestWorkflowEnvironment
	rec      *shapeRecorder
	register func(env *testsuite.TestWorkflowEnvironment)

	// The STORE of the rail this lifecycle runs on today — exactly one is wired, and
	// each driver reads the one its case belongs to. A store is here, while the
	// pipeline double is not, for one reason: the two ledger-derived fields of
	// shapeOutcome (Reopened, PhaseAdvanced) are read out of the store rather than
	// observed at a hook, because a re-dispatch is a second attempt on a work task
	// and that is a row, not an event. Everything else arrives through the recorder.
	cs *csFakeProjectState
	// (shapeRig.design — the CO-AUTHOR rail's store — went with the `requirements` arm when
	// stage 4b1 Task 10 re-pointed it at the generic child. Every shape case now reads the one
	// construction-rail double, which is what "one set of store semantics" was always for.)
	// cswf + pipe are the construction-rail receiver and pipeline double the generic child
	// runs on. They are here, unlike the design rails', because reenter re-runs the SAME
	// receiver over the SAME ledger on a second environment to finish a continued walk.
	cswf *csWorkflows
	pipe *csFakePipeline
	// branchCompletesFirst is the fork's only knob: which branch of the
	// srsReview fan-out the case wants to reach its pipeline terminal FIRST. It is applied
	// through forkWinner, which makes the OTHER branch's JOB lag on the production observe
	// ladder — since stage 4b1 Task 11 the real dispatch strategy runs these cases, so the
	// pacing belongs to the venue double and not to a substituted strategy.
	branchCompletesFirst projectstate.MethodTask
}

// forkWinner tells the venue double which branch of the srsReview fan-out finishes first: the
// other one reports RUNNING for laggingPolls observes, so the winner's whole remaining chain —
// its gate, the next phase's dispatch and gate, the integration dispatch — happens first.
// laggingPolls of 0 takes shapeDefaultLaggingPolls.
//
// The WAITING IS THE PRODUCTION LADDER'S (observeInterval's durable timers), which is what
// makes the fork a fact about the child rather than about a stub's sleep — and it is also the
// yield the SDK needs: without one it would run each coroutine to completion in schedule order
// and both branch-order cases would produce the same CompletedOrder, the serialisation
// assertShapeForkOverlap exists to catch.
func (r *shapeRig) forkWinner(winner projectstate.MethodTask, laggingPolls int) {
	r.branchCompletesFirst = winner
	lagging := projectstate.TaskSTP
	if winner == projectstate.TaskSTP {
		lagging = projectstate.TaskDetailedDesign
	}
	r.pipe.laggingTask, r.pipe.laggingPolls = lagging, laggingPolls
	// EVERY job now takes at least one poll, which is the yield described above.
	r.pipe.runningPolls = 1
}

// reenter returns a rig for the NEXT run of a walk that continued as new: a fresh test
// environment over the SAME store, the same pipeline double, the same receiver and the SAME
// recorder. Sharing the recorder is what makes the continued walk assertable as ONE walk —
// the point of the case is that run 2 finishes what run 1 started, so the two runs' events
// belong in one timeline.
func (r *shapeRig) reenter(t *testing.T) *shapeRig {
	t.Helper()
	var ts testsuite.WorkflowTestSuite
	next := &shapeRig{
		env: ts.NewTestWorkflowEnvironment(), rec: r.rec,
		cs: r.cs, cswf: r.cswf, pipe: r.pipe,
		branchCompletesFirst: r.branchCompletesFirst,
	}
	next.register = func(env *testsuite.TestWorkflowEnvironment) {
		registerDeliveryActivity(env, next.cswf, next.cs, next.pipe)
	}
	return next
}

// The ids the shape cases run under. Stable literals, because a shape case's
// assertions are read against the ledger row these key.
const (
	shapeProjectID    = ProjectID("shape-p")
	shapeServiceID    = "C-Orders"
	shapeDeploymentID = "R-Deploy"
	shapeSDPActivity  = "P-SDP"
)

// newShapeRig builds the rig for one lifecycle on the rails as they stand. The
// per-lifecycle arm is the ONE place that knows which child a lifecycle runs on
// today, so Tasks 8/9/10 re-point a lifecycle by editing one arm.
//
// Every construction-rail rig wires the REAL review engine: the gate verdict is the
// behaviour under test in four of the seven shapes, and a scripted verdict would let
// exactly the regression the vibes defect was made of pass.
func newShapeRig(t *testing.T, typeKey string) *shapeRig {
	t.Helper()
	var ts testsuite.WorkflowTestSuite
	rig := &shapeRig{env: ts.NewTestWorkflowEnvironment(), rec: newShapeRecorder()}
	switch typeKey {
	case "deployment", "service":
		ps := newFakeProjectStateWithPolicy(projectstate.ReviewPolicy{})
		ps.rec = rig.rec
		pipe := &csFakePipeline{phase: PipelineSucceeded, episode: csCaptureSeamSummary(), rec: rig.rec}
		deps := gateDeps(ps)
		deps.Review = review.NewReviewEngine()
		deps.SDPEngines = shapeSDPEngines()
		wf := csNewWorkflows(deps)
		// THE REAL STRATEGIES (stage 4b1 Task 11). These two lifecycles ran against a STUB
		// dispatch slot while the construction arm was unwritten; they now run the production
		// registry, so the fork, the join and the send-back are proved through the same
		// submit → observe → attempt sequence a real construction job takes. The registry seam
		// STAYS — it is what let the DAG be proved two tasks before this one, and it is what a
		// future venue substitutes at.
		wf.Deliveries = rig.rec
		rig.cs, rig.cswf, rig.pipe = ps, wf, pipe
		rig.register = func(env *testsuite.TestWorkflowEnvironment) { registerDeliveryActivity(env, wf, ps, pipe) }
	case "requirements":
		// RE-POINTED AT THE GENERIC CHILD (stage 4b1 Task 10). The rail moved from
		// CoAuthorArtifactWorkflow-per-kind to ONE DeliveryActivityWorkflow walking the whole
		// four-phase `requirements` lifecycle, so the case's subject widened with it: it used to
		// drive the mission kind alone and now drives the activity that owns all four. The design
		// job double FULFILS each job the way the seated aiarch-design.yml does, so the read-back
		// has something to read and the auto-approve is an approve OF something.
		designRig, _ := designShapeRig(t, projectstate.ReviewPresetVibes)
		return designRig
	case "projectDesign":
		// RE-POINTED AT THE GENERIC CHILD (stage 4b1 Task 9). The rail moved from
		// AssembleSDPReviewWorkflow to DeliveryActivityWorkflow, so the store moved with it:
		// the compute stages through the execution ledger's own verb and the M0 seal commits
		// and advances, all on the construction-rail double.
		//
		// The project is THIS REPO'S OWN committed slots 5/8/10/11-14, not a toy: the
		// acceptance is that the derived dials reproduce the committed ones, and a
		// two-component fixture could satisfy every assertion while the doctrine table was
		// wrong. The REAL strategies are wired (no stub): projectDesign has no dispatch task
		// at all, so a stubbed dispatch slot would be a substitution with nothing to
		// substitute for, and the compute is the thing under test.
		ps := &csFakeProjectState{project: projectDesignFixtureProject(t)}
		ps.rec = rig.rec
		pipe := &csFakePipeline{phase: PipelineSucceeded, episode: csCaptureSeamSummary(), rec: rig.rec}
		deps := gateDeps(ps)
		deps.Review = review.NewReviewEngine()
		deps.SDPEngines = shapeSDPEngines()
		wf := csNewWorkflows(deps)
		wf.Deliveries = rig.rec
		rig.cs, rig.cswf, rig.pipe = ps, wf, pipe
		rig.register = func(env *testsuite.TestWorkflowEnvironment) { registerDeliveryActivity(env, wf, ps, pipe) }
	default:
		t.Fatalf("newShapeRig: no rail is wired for lifecycle %q — add its arm rather than defaulting it, "+
			"because a shape case silently driving the wrong child would pass for the wrong reason", typeKey)
	}
	return rig
}

// lifecycleShapeCases returns the seven shapes spec §9 names, in a fixed order.
// Task 8 Step 10 appends three more — continue-as-new-mid-walk (R-L),
// fork-signal-reaches-the-named-task and full-inbox-does-not-wedge-the-router (the
// signal router) — none of which spec §9 names, because collapsing four per-kind
// executions into one walk is what creates an unbounded history, a shared-channel
// race and a delivery-overflow path all at once.
// The names are contract: Task 8 Step 10, Task 9 Step 7, Task 10 Step 6 and Task 11
// Step 5 each name the subset they must turn green.
func lifecycleShapeCases() []lifecycleShapeCase {
	return []lifecycleShapeCase{
		{
			// LINEAR. `deployment` is three phases, D→R each, no fork — the shape the
			// flat phase walk and the DAG walk must agree on exactly.
			name: "linear-deployment", typeKey: "deployment",
			drive: driveLinearDeployment, wantToday: shapePassesToday,
		},
		{
			// FORK, STP BRANCH COMPLETING FIRST. srsReview passes, then stp and
			// detailedDesign are BOTH started (in declaration order, which is fixed);
			// this case lets the STP branch's pipeline reach terminal first.
			name: "fork-join-service-stp-first", typeKey: "service",
			drive: driveServiceForkSTPFirst, wantToday: shapePassesToday,
		},
		{
			// FORK, DESIGN BRANCH COMPLETING FIRST. The same DAG, the other completion
			// order. Two cases, not one: a walker that serialized the branches would
			// pass whichever single case matched its accident.
			name: "fork-join-service-design-first", typeKey: "service",
			drive: driveServiceForkDesignFirst, wantToday: shapePassesToday,
		},
		{
			// SEND-BACK RE-OPENS ONLY THE JUDGED PAIR. designReview sends back; the
			// assertion is that Reopened == ["detailedDesign"] and that stp/srs are NOT
			// in it — a re-walk that re-dispatched the whole phase list would pass a
			// naive "it redrafted" assertion.
			name: "sendback-reopens-only-the-judged-pair", typeKey: "service",
			drive: driveServiceSendBackJudgedPair, wantToday: shapePassesToday,
		},
		{
			// JOIN WAITS FOR ALL. `testing` dependsOn [integration, stpReview]; the
			// assertion is that its round does NOT open while either is unpassed.
			name: "join-waits-for-all", typeKey: "service",
			drive: driveServiceJoinWaits, wantToday: shapePassesToday,
		},
		{
			// M0 NO SEND-BACK. The projectDesign lifecycle's one review task: approve
			// advances the root phase; a send-back is refused, not absorbed.
			name: "m0-no-sendback", typeKey: "projectDesign",
			drive: driveM0NoSendBack, wantToday: shapePassesToday,
		},
		{
			// CONTINUE-AS-NEW MID-WALK (R-L). Drives a service walk with the history budget
			// set to a value the walk crosses, and asserts that the child continues-as-new,
			// that it continues with NOTHING in flight, and that the resumed run finishes the
			// SAME walk — same tasks, none re-dispatched. A continue that lost the snapshot
			// would re-run passed work; one that lost the feedback map would silently redraft
			// against the prompt that was just rejected.
			name: "continue-as-new-mid-walk", typeKey: "service",
			drive: driveContinueAsNewMidWalk, wantToday: shapePassesToday,
		},
		{
			// SIGNAL ROUTING ON A FORK. `stp` is mid-dispatch while `designReview` waits at
			// its gate, and an operator override is sent naming the GATE. Asserts the gate
			// received it and the in-flight sibling did NOT — which two receivers on one
			// shared ReceiveChannel could never guarantee, because the SDK hands each message
			// to exactly one of them. It also drives a signal for a task that has not started
			// yet (buffered in ws.pending, flushed in order at openInbox) and one for a task
			// that has already finished (dropped, and NOT handed to anything).
			name: "fork-signal-reaches-the-named-task", typeKey: "service",
			drive: driveForkSignalRouting, wantToday: shapePassesToday,
		},
		{
			// A FULL INBOX MUST NOT WEDGE THE ROUTER. Sends 65 signals — one more than
			// deliveryTaskInboxCapacity — to a task that then retires WITHOUT draining them,
			// and asserts that a LATER task's decision is still delivered and the walk still
			// reaches its terminal. With a blocking Send this deadlocks: the parked send
			// outlives closeInbox, no receiver can ever exist for that channel again, the
			// router never selects a second time, and every later signal in the activity is
			// silently swallowed. The 65th is asserted NOT delivered, which is what proves it
			// went to `pending` rather than into a channel nothing would read.
			name: "full-inbox-does-not-wedge-the-router", typeKey: "service",
			drive: driveInboxOverflow, wantToday: shapePassesToday,
		},
		{
			// HUMAN FLOOR UNDER VIBES. Preset "vibes" auto-approves a design review and
			// STILL holds M0 for a human — the non-overridable spend floor
			// (reviewengine.go:432). One case, both halves.
			name: "human-floor-under-vibes", typeKey: "requirements",
			drive: driveVibesFloor, wantToday: shapePassesToday,
		},
	}
}

// ---- the drivers -----------------------------------------------------------

// shapeDeploymentActivity is the LINEAR activity: three phases, each a dispatch and
// the review that judges it, and no fan-out anywhere in the lifecycle.
func shapeDeploymentActivity() constructionActivity {
	return constructionActivity{
		ActivityID:  shapeDeploymentID,
		Kind:        activityKindConstruction,
		ComponentID: "comp-deploy",
		Layer:       "engine",
		Type:        projectstate.ActivityTypeDeployment,
		Phases:      projectstate.ProfileFor(projectstate.ActivityTypeDeployment, 0).PhaseIDs(),
	}
}

func driveLinearDeployment(t *testing.T, rig *shapeRig) shapeOutcome {
	t.Helper()
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	shapeRequireCompleted(t, rig.env)
	return rig.csOutcome(shapeDeploymentID)
}

// driveServiceWalk is the body the three ungated service cases share: one `service`
// activity, no gate, run to its terminal. They differ in ONE field — which branch the
// case wants to reach its pipeline terminal first — and in nothing else, deliberately:
// the START order is lifecycle declaration order, which is not a case variable, so a
// driver that also reordered the starts would be asserting its own script instead of
// the walker's.
func driveServiceWalk(t *testing.T, rig *shapeRig, completesFirst projectstate.MethodTask) shapeOutcome {
	t.Helper()
	rig.forkWinner(completesFirst, 0)
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeServiceID, Activity: sampleActivity(),
	})
	shapeRequireCompleted(t, rig.env)
	return rig.csOutcome(shapeServiceID)
}

func driveServiceForkSTPFirst(t *testing.T, rig *shapeRig) shapeOutcome {
	return driveServiceWalk(t, rig, projectstate.TaskSTP)
}

func driveServiceForkDesignFirst(t *testing.T, rig *shapeRig) shapeOutcome {
	return driveServiceWalk(t, rig, projectstate.TaskDetailedDesign)
}

// driveServiceJoinWaits runs the same walk as the fork cases and asserts on the JOIN
// rather than on the fan-out: `testing` depends on both `integration` and `stpReview`,
// and its round must not open while either is unpassed.
//
// It asks for the DESIGN branch first, which is what makes the join observable at all:
// the STP branch then lags behind the design branch's whole pipeline — detailed design
// → construction → integration — so `stpReview` passes AFTER `integration` and the
// joining review genuinely has to wait for a predecessor it did not gate. Under the
// flat phase walk stpReview always passes before integration is dispatched, so the wait
// is never exercised; that is why this case is skipped rather than green today.
func driveServiceJoinWaits(t *testing.T, rig *shapeRig) shapeOutcome {
	return driveServiceWalk(t, rig, projectstate.TaskDetailedDesign)
}

// driveServiceSendBackJudgedPair gates detailed_design, sends the draft back once,
// then approves the redraft. The claim is about what the send-back did NOT touch.
func driveServiceSendBackJudgedPair(t *testing.T, rig *shapeRig) shapeOutcome {
	t.Helper()
	rig.cs.project.ReviewPolicy = replayGatedOn(projectstate.MethodPhaseDetailedDesign)
	// stp LAGS far past the reject, so the send-back's real claim — it re-opens only the judged
	// pair — is made while the sibling branch is genuinely MID-FLIGHT. With both branches already
	// finished, "stp was not re-opened" is true of a walk that re-set everything too.
	rig.forkWinner(projectstate.TaskDetailedDesign, 20)
	rig.register(rig.env)
	rig.env.RegisterDelayedCallback(shapeReject(rig.env, shapeDesignReviewTask, "name the failure"), 30*time.Second)
	rig.env.RegisterDelayedCallback(shapeApprove(rig.env, shapeDesignReviewTask), 90*time.Second)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeServiceID, Activity: sampleActivity(),
	})
	shapeRequireCompleted(t, rig.env)
	return rig.csOutcome(shapeServiceID)
}

// shapeSDPActivityRow is the projectDesign activity the M0 case walks: ONE review task, no
// dispatch, no component. Phases is deliberately left nil — the generic child reads the
// lifecycle DAG, not the flat profile, and a populated Phases here would let a regression to
// the flat walk pass.
func shapeSDPActivityRow() constructionActivity {
	return constructionActivity{
		ActivityID: shapeSDPActivity,
		Kind:       activityKindConstruction,
		Type:       projectstate.ActivityTypeProjectDesign,
	}
}

// driveM0NoSendBack drives the projectDesign lifecycle's single review task through the
// GENERIC CHILD (stage 4b1 Task 9; it ran on AssembleSDPReviewWorkflow before).
//
// It sends a REJECT first and then an approve, so the case's real claim is exercised rather
// than assumed: the reject must be REFUSED at the gate — no round decided, no attempt
// rejected, the walk not stalled — because the projectDesign lifecycle has no send-back
// edge to re-open (Task 8 review finding 6). Then the approve commits the derived plan and
// seals the root phase.
func driveM0NoSendBack(t *testing.T, rig *shapeRig) shapeOutcome {
	t.Helper()
	rig.register(rig.env)
	rig.env.RegisterDelayedCallback(shapeReject(rig.env, sdpReviewTaskID, "cut the cost"), 30*time.Second)
	rig.env.RegisterDelayedCallback(shapeApprove(rig.env, sdpReviewTaskID), 90*time.Second)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeSDPActivity, Activity: shapeSDPActivityRow(),
	})
	shapeRequireCompleted(t, rig.env)

	// PhaseAdvanced is read off the store, like every other ledger-derived field: M0's
	// approve commits the eight computed slots and THEN advances the root phase, and both
	// halves have to have happened for the plan to be materialised.
	rig.cs.mu.Lock()
	advanced := rig.cs.advanced == 1 &&
		slices.Equal(rig.cs.committedSlots, projectDesignComputedKinds())
	rig.cs.mu.Unlock()
	return rig.rec.outcome(nil, advanced)
}

// driveVibesFloor is ONE case with two halves, because the claim is a conjunction:
// under the SAME committed vibes policy a design review auto-approves AND M0 still
// holds for a human. Splitting them would let a policy that auto-approved everything
// pass the first half alone.
//
// The M0 half is asked of the REAL review engine rather than driven as a second
// workflow: the floor is the engine's answer (requiresHuman's row 2), the SDP rail
// has no autogate to consult it today, and a second execution on a second env would
// prove only that a workflow with no autogate waits.
func driveVibesFloor(t *testing.T, rig *shapeRig) shapeOutcome {
	t.Helper()
	// HALF ONE: the whole four-phase design activity runs to its terminal with NO human signal
	// at all. Under `vibes` every design gate auto-passes — which is the two-month defect this
	// project measured, now visible in the ledger instead of invisible.
	got := driveRequirementsWalk(t, rig)

	// HALF TWO: the SAME preset does not release M0. The non-overridable spend floor is asked
	// directly, because the two halves belong to two different activities and driving the second
	// here would make this case a duplicate of m0-no-sendback.
	set, err := review.NewReviewEngine().ProposeReviews(
		fweng.Context{Context: context.Background()},
		review.ReviewChange{ActivityID: shapeSDPActivity},
		review.ActivityTypeProjectDesign, "sdp", "",
		review.ReviewPolicy{Preset: projectstate.ReviewPresetVibes}, false, nil)
	if err != nil {
		t.Fatalf("the review engine must answer for the M0 gate: %v", err)
	}
	if !set.RequiresHuman {
		t.Fatalf("the non-overridable spend floor must hold M0 for a human even under vibes; the engine said no, reason %q", set.Reason)
	}
	// And every design gate was closed by the POLICY, not by a person — the half that makes
	// "auto-approved" a fact about the data rather than about the absence of a signal.
	for _, r := range rig.cs.execution("requirements").Reviews {
		if r.DecidedBy != gateActorSystem {
			t.Errorf("round %s was decided by %q; under vibes the committed policy closes it", r.RoundID, r.DecidedBy)
		}
	}
	return got
}

// ---- shared driver plumbing ------------------------------------------------

// shapeRequireCompleted is the precondition every case shares: a driver that did not
// reach a terminal proves nothing about the shape, and a nil workflow error on an
// incomplete execution is the failure mode that reads as a pass.
func shapeRequireCompleted(t *testing.T, env *testsuite.TestWorkflowEnvironment) {
	t.Helper()
	if !env.IsWorkflowCompleted() {
		t.Fatal("the shape driver did not reach a terminal; the outcome it would read is a snapshot of an unfinished walk")
	}
	if err := env.GetWorkflowError(); err != nil {
		t.Fatalf("workflow error: %v", err)
	}
}

// csOutcome snapshots the recorder plus the two facts that live in the STORE rather
// than at a hook: which work tasks were re-opened, and whether the activity reached
// its binary exit.
func (r *shapeRig) csOutcome(activityID string) shapeOutcome {
	return r.rec.outcome(shapeReopenedWorkTasks(r.cs.execution(activityID)), shapeExitedCompleted(r.cs, activityID))
}

// shapeReopenedWorkTasks reads the re-opened set off the attempt ledger: a WORK task
// with a second attempt is a task that was dispatched again. The review task of the
// judged pair is deliberately not in it — every send-back opens a second round by
// construction, so counting rounds would make the set unfalsifiable, while a second
// DISPATCH is the fact a re-walk of the whole phase list would get wrong.
func shapeReopenedWorkTasks(row projectstate.ActivityExecution) []string {
	var out []string
	seen := map[projectstate.MethodTask]bool{}
	for _, a := range row.Attempts {
		if a.Attempt < 2 || seen[a.Task] || projectstate.AgentTaskFor(a.Phase) != a.Task {
			continue
		}
		seen[a.Task] = true
		out = append(out, string(a.Task))
	}
	return out
}

// shapeExitedCompleted reports the activity's binary exit, read through the double's
// one answer for it (csFakeProjectState.exited is fed by BOTH the retired verb and
// the ledger's RecordActivityOutcome, so this holds whichever rail wrote it).
func shapeExitedCompleted(ps *csFakeProjectState, activityID string) bool {
	ps.mu.Lock()
	defer ps.mu.Unlock()
	for _, e := range ps.exited {
		if e.activityID == activityID && e.outcome == projectstate.ActivityOutcomeCompleted {
			return true
		}
	}
	return false
}

// ---- the runner ------------------------------------------------------------

// Test_LifecycleShapes is the differential oracle: the seven shapes, run against
// whatever child this commit registers. A shapeFailsUntilTheDAG case is skipped
// with the task that owes it named in the skip message, so `go test -v` prints the
// remaining work rather than hiding it.
func Test_LifecycleShapes(t *testing.T) {
	for _, c := range lifecycleShapeCases() {
		t.Run(c.name, func(t *testing.T) {
			if c.wantToday == shapeFailsUntilTheDAG {
				t.Skip("asserts the lifecycle DAG's parallelism; the flat phase walk cannot satisfy it — flipped to shapePassesToday by stage 4b1 Task 8")
			}
			assertShape(t, c.name, c.drive(t, newShapeRig(t, c.typeKey)))
		})
	}
}

// assertShape holds the per-case expectations. There is no default arm that passes:
// a case added without its assertion is a Fatalf, so the table cannot grow a row
// that goes green by saying nothing.
func assertShape(t *testing.T, name string, got shapeOutcome) {
	t.Helper()
	switch name {
	case "linear-deployment":
		assertShapeLinearDeployment(t, name, got)
	case "fork-join-service-stp-first":
		assertShapeForkOverlap(t, name, got)
		shapeWantBefore(t, name, "CompletedOrder", got.CompletedOrder, "stp", "detailedDesign")
	case "fork-join-service-design-first":
		assertShapeForkOverlap(t, name, got)
		shapeWantBefore(t, name, "CompletedOrder", got.CompletedOrder, "detailedDesign", "stp")
	case "sendback-reopens-only-the-judged-pair":
		assertShapeSendBackJudgedPair(t, name, got)
	case "join-waits-for-all":
		assertShapeJoinWaits(t, name, got)
	case "m0-no-sendback":
		assertShapeM0NoSendBack(t, name, got)
	case "continue-as-new-mid-walk":
		assertShapeContinueAsNew(t, name, got)
	case "fork-signal-reaches-the-named-task":
		assertShapeForkSignalRouting(t, name, got)
	case "full-inbox-does-not-wedge-the-router":
		assertShapeInboxOverflow(t, name, got)
	case "human-floor-under-vibes":
		assertShapeVibesFloor(t, name, got)
	default:
		t.Fatalf("no assertion is written for shape case %q; a case without one would pass by saying nothing", name)
	}
}

// assertShapeLinearDeployment pins the shape the flat walk and the DAG walk must agree
// on EXACTLY: three phases, each one dispatch then the review that judges it, every
// round auto-passed by a policy that gates nothing, nothing re-opened.
//
// The merge job is in Dispatched on purpose. It is the one dispatch that is not a
// lifecycle task — the local merge hold's own job — and naming it is what keeps this
// case honest: an assertion that only counted the three commands would not notice a
// fourth dispatch appearing or the merge hold disappearing.
func assertShapeLinearDeployment(t *testing.T, name string, got shapeOutcome) {
	t.Helper()
	pairs := []string{"detailedDesign", "designReview", "construction", "codeReview", "integration", "testing"}
	shapeWantOrder(t, name, "TaskOrder", got.TaskOrder, pairs)
	shapeWantOrder(t, name, "CompletedOrder", got.CompletedOrder, pairs)
	shapeWantOrder(t, name, "Dispatched", got.Dispatched, []string{
		"deployment-detailed-design", "deployment-construction", "deployment-integration", "job:merge",
	})
	shapeWantOrder(t, name, "RoundsOpened", got.RoundsOpened, []string{
		shapeDeploymentID + ":designReview:1", shapeDeploymentID + ":codeReview:1", shapeDeploymentID + ":testing:1",
	})
	shapeWantEveryRound(t, name, got.RoundsDecided, string(projectstate.RoundPassed))
	if len(got.Reopened) != 0 {
		t.Fatalf("%s: a linear lifecycle with no send-back re-opens nothing; got %v", name, got.Reopened)
	}
	shapeWantAdvanced(t, name, got.PhaseAdvanced)
}

// assertShapeForkOverlap is the half both branch-order cases share: the fan-out STARTS
// in lifecycle declaration order (asserted, so a data reorder in lifecycles.json is
// caught rather than absorbed) and BOTH branches are in flight at once. The overlap is
// read off the MERGED Timeline and nowhere else — the two starts must both precede the
// first completion of either — because that is the one statement TaskOrder and
// CompletedOrder cannot make between them (see shapeOutcome.Timeline). A walker that
// serialises the branches satisfies the declaration-order half and fails this one, which
// is the whole reason there are two fork cases instead of one.
func assertShapeForkOverlap(t *testing.T, name string, got shapeOutcome) {
	t.Helper()
	shapeWantBefore(t, name, "TaskOrder", got.TaskOrder, "detailedDesign", "stp")
	firstDone := shapeFirstIndexOf(got.Timeline,
		shapeEventCompleted+"detailedDesign", shapeEventCompleted+"stp")
	if firstDone < 0 {
		t.Fatalf("%s: neither fork branch ever completed; Timeline=%v", name, got.Timeline)
	}
	for _, branch := range []string{"detailedDesign", "stp"} {
		if started := slices.Index(got.Timeline, shapeEventStarted+branch); started < 0 || started > firstDone {
			t.Fatalf("%s: the branches were SERIALISED — %q happened before %q, so the two were never in flight at once. Timeline=%v",
				name, got.Timeline[firstDone], shapeEventStarted+branch, got.Timeline)
		}
	}
	shapeWantAdvanced(t, name, got.PhaseAdvanced)
}

// assertShapeSendBackJudgedPair is the send-back's real claim, which is about what did
// NOT happen: exactly ONE work task was dispatched again, and the siblings the re-walk
// of a flat phase list would have re-dispatched are absent from Reopened.
func assertShapeSendBackJudgedPair(t *testing.T, name string, got shapeOutcome) {
	t.Helper()
	shapeWantOrder(t, name, "Reopened", got.Reopened, []string{string(projectstate.TaskDetailedDesign)})
	for _, sibling := range []string{"srs", "stp", "construction", "integration"} {
		if slices.Contains(got.Reopened, sibling) {
			t.Fatalf("%s: the send-back judged detailed_design, so %q must not be re-opened; Reopened=%v",
				name, sibling, got.Reopened)
		}
	}
	// The pair: the judged dispatch ran twice and its review opened twice, and the round
	// that was sent back is the FIRST of them — round 2 is the one that passed.
	if n := shapeCount(got.TaskOrder, "detailedDesign"); n != 2 {
		t.Fatalf("%s: the judged dispatch must start exactly twice; got %d in %v", name, n, got.TaskOrder)
	}
	if n := shapeCount(got.TaskOrder, "designReview"); n != 2 {
		t.Fatalf("%s: the judging review must open exactly twice; got %d in %v", name, n, got.TaskOrder)
	}
	if n := shapeCount(got.CompletedOrder, "designReview"); n != 1 {
		t.Fatalf("%s: a sent-back round does not complete its task, so designReview completes ONCE; got %d in %v",
			name, n, got.CompletedOrder)
	}
	// And EVERY OTHER task ran exactly once. This half is not redundant with Reopened above:
	// Reopened is read off the attempt ledger, and a sibling re-dispatched at the SAME
	// revision mints the SAME AttemptID, which the store absorbs as a replay — so a re-open
	// that reset the whole walk leaves no second attempt to count. Measured: with
	// reopenJudgedPair resetting every task, Reopened stays ["detailedDesign"] and only this
	// assertion goes red.
	for _, task := range shapeServiceTasks {
		if task == string(projectstate.TaskDetailedDesign) || task == shapeDesignReviewTask {
			continue
		}
		if n := shapeCount(got.TaskOrder, task); n != 1 {
			t.Fatalf("%s: the send-back judged detailed_design, so %q must run exactly once; it ran %d times. TaskOrder=%v",
				name, task, n, got.TaskOrder)
		}
	}
	shapeWantRound(t, name, got.RoundsDecided, shapeServiceID+":designReview:1", string(projectstate.RoundSentBack))
	shapeWantRound(t, name, got.RoundsDecided, shapeServiceID+":designReview:2", string(projectstate.RoundPassed))
	if sent := shapeRoundsWith(got.RoundsDecided, string(projectstate.RoundSentBack)); len(sent) != 1 {
		t.Fatalf("%s: one send-back is one sent-back round; got %v", name, sent)
	}
	shapeWantAdvanced(t, name, got.PhaseAdvanced)
}

// assertShapeJoinWaits is the join: `testing` dependsOn [integration, stpReview], and
// the case drives the STP branch to LAG so the join is observable at all — under the
// flat phase walk stpReview always passes before integration is even dispatched, so
// the wait is never exercised and the assertion below cannot be satisfied.
func assertShapeJoinWaits(t *testing.T, name string, got shapeOutcome) {
	t.Helper()
	shapeWantBefore(t, name, "CompletedOrder", got.CompletedOrder, "integration", "stpReview")
	shapeWantBefore(t, name, "CompletedOrder", got.CompletedOrder, "stpReview", "testing")
	shapeWantBefore(t, name, "CompletedOrder", got.CompletedOrder, "integration", "testing")
	// And the join holds at the ROUND, not merely at the completion: the joining review
	// must not even OPEN while a predecessor is unpassed.
	shapeWantBefore(t, name, "RoundsOpened", got.RoundsOpened,
		shapeServiceID+":stpReview:1", shapeServiceID+":testing:1")
	if last := len(got.RoundsOpened) - 1; last < 0 || got.RoundsOpened[last] != shapeServiceID+":testing:1" {
		t.Fatalf("%s: the join's round is the last one opened; RoundsOpened=%v", name, got.RoundsOpened)
	}
	shapeWantAdvanced(t, name, got.PhaseAdvanced)
}

// assertShapeM0NoSendBack: the projectDesign lifecycle has ONE review task and no
// send-back edge, so no round of it may ever be DECIDED as a send-back — whatever the
// rail does with a rejection — and the approve advances the root phase.
//
// THE ROUND MUST EXIST BEFORE "NONE WAS SENT BACK" MEANS ANYTHING (Task 1 carry 3, and the
// ruling that made it explicit). Against the retired SDP rail this case held VACUOUSLY: that
// rail wrote no round at all, so "no round was decided sentBack" was true of a ledger with
// nothing in it. Against the child there is exactly ONE M0 round, opened at revision 1 and
// decided PASSED, and the rejection that arrived first left no trace on it — which is the
// claim, and it is now falsifiable.
func assertShapeM0NoSendBack(t *testing.T, name string, got shapeOutcome) {
	t.Helper()
	round := shapeSDPActivity + ":" + sdpReviewTaskID + ":1"
	// EXISTENCE FIRST. A case that asserted only the absence of a send-back would pass on a
	// walk that opened no round, which is exactly what the previous rail did.
	shapeWantOrder(t, name, "RoundsOpened", got.RoundsOpened, []string{round})
	shapeWantRound(t, name, got.RoundsDecided, round, string(projectstate.RoundPassed))
	// And ONE round, not two: a refused rejection must not withdraw the round and open a
	// second one, because there is no judged pair to re-open and the walk would stall.
	if len(got.RoundsDecided) != 1 {
		t.Fatalf("%s: M0 is ONE round; the refused rejection must not have opened a second. decided=%v", name, got.RoundsDecided)
	}
	if sent := shapeRoundsWith(got.RoundsDecided, string(projectstate.RoundSentBack)); len(sent) != 0 {
		t.Fatalf("%s: M0 has no send-back edge, so no round may be decided sentBack; got %v", name, sent)
	}
	if n := shapeCount(got.TaskOrder, sdpReviewTaskID); n > 1 {
		t.Fatalf("%s: the M0 gate must run ONCE — a refused rejection does not re-open it; TaskOrder=%v", name, got.TaskOrder)
	}
	// Nothing was DISPATCHED: Project Design is computed, and an agent job here would mean
	// the compute had been modelled as a dispatch after all.
	if len(got.Dispatched) != 0 {
		t.Fatalf("%s: Project Design is COMPUTED, so nothing may be dispatched; got %v", name, got.Dispatched)
	}
	shapeWantAdvanced(t, name, got.PhaseAdvanced)
}

// assertShapeVibesFloor is the design half of the conjunction; the M0 half is asserted
// inside driveVibesFloor, because "the engine holds M0 for a human" is not an order
// fact and forcing it into shapeOutcome would make it less legible, not more.
func assertShapeVibesFloor(t *testing.T, name string, got shapeOutcome) {
	t.Helper()
	// The whole activity: four drafts, and a critique after each draft whose review task carries
	// one — volatilities does not, which is why there are SEVEN dispatches and not eight.
	shapeWantOrder(t, name, "Dispatched", got.Dispatched, []string{
		"mission-draft", "mission-critique",
		"glossary-draft", "glossary-critique",
		"volatilities-draft",
		"core-use-cases-draft", "core-use-cases-critique",
		// The local merge lands activity/requirements on main, which is what makes the four slot
		// commits legal: DesignSessionCommitArtifactWithProvenance takes no branch.
		"job:merge",
	})
	shapeWantOrder(t, name, "TaskOrder", got.TaskOrder, []string{
		"missionReview", "glossaryReview", "volatilitiesReview", "coreUseCasesReview",
	})
	if len(got.RoundsDecided) == 0 {
		t.Fatalf("%s: an auto-approved gate is still a gate that HAPPENED — it must leave its round; got none", name)
	}
	shapeWantEveryRound(t, name, got.RoundsDecided, string(projectstate.RoundPassed))
	shapeWantAdvanced(t, name, got.PhaseAdvanced)
}

// ---- assertion vocabulary --------------------------------------------------

func shapeWantOrder(t *testing.T, name, field string, got, want []string) {
	t.Helper()
	if !slices.Equal(got, want) {
		t.Fatalf("%s: %s = %v, want %v", name, field, got, want)
	}
}

// shapeWantBefore is the ONE ordering primitive every shape shares. It fails loudly on
// an absent element rather than treating -1 as "earlier", which is how an ordering
// assertion quietly becomes vacuous.
func shapeWantBefore(t *testing.T, name, field string, got []string, first, second string) {
	t.Helper()
	i, j := slices.Index(got, first), slices.Index(got, second)
	switch {
	case i < 0:
		t.Fatalf("%s: %s does not contain %q at all; got %v", name, field, first, got)
	case j < 0:
		t.Fatalf("%s: %s does not contain %q at all; got %v", name, field, second, got)
	case i >= j:
		t.Fatalf("%s: %s must have %q before %q; got %v", name, field, first, second, got)
	}
}

func shapeWantAdvanced(t *testing.T, name string, advanced bool) {
	t.Helper()
	if !advanced {
		t.Fatalf("%s: the lifecycle must reach its terminal and advance its phase", name)
	}
}

func shapeWantRound(t *testing.T, name string, decided map[string]string, roundID, want string) {
	t.Helper()
	got, ok := decided[roundID]
	if !ok {
		t.Fatalf("%s: round %q was never decided; decided=%v", name, roundID, decided)
	}
	if got != want {
		t.Fatalf("%s: round %q decided %q, want %q", name, roundID, got, want)
	}
}

func shapeWantEveryRound(t *testing.T, name string, decided map[string]string, want string) {
	t.Helper()
	for _, roundID := range slices.Sorted(maps.Keys(decided)) {
		if decided[roundID] != want {
			t.Fatalf("%s: round %q decided %q, want every round %q", name, roundID, decided[roundID], want)
		}
	}
}

// shapeRoundsWith returns the round ids decided with the given outcome, sorted, so a
// failure names them instead of reporting a count.
func shapeRoundsWith(decided map[string]string, outcome string) []string {
	var out []string
	for roundID, got := range decided {
		if got == outcome {
			out = append(out, roundID)
		}
	}
	slices.Sort(out)
	return out
}

// shapeFirstIndexOf returns the position of the EARLIEST of the named events in the
// merged timeline, or -1 when none of them happened.
func shapeFirstIndexOf(timeline []string, events ...string) int {
	for i, e := range timeline {
		if slices.Contains(events, e) {
			return i
		}
	}
	return -1
}

func shapeCount(xs []string, v string) int {
	n := 0
	for _, x := range xs {
		if x == v {
			n++
		}
	}
	return n
}

// ---------------------------------------------------------------------------
// THE GENERIC DAG WALKER (stage 4b1 Task 8) — its two pins and its engine parity.
// ---------------------------------------------------------------------------

// Test_TaskStateOrdinalsNeverRenumber pins walkTaskState's iota, because
// walkSnapshot.ByTask encodes the ORDINAL and walkSnapshot rides a ContinueAsNew. A
// re-order would therefore silently re-interpret every in-flight walk at the moment the
// new image goes live: a task the previous run recorded as `passed` would resume as
// `sentBack`, re-open a judged pair nobody rejected and re-dispatch work that was already
// approved — with nothing in the ledger to show why.
//
// A new state is APPENDED with its number written here. The table is the contract; the
// count is asserted too, so appending one without recording it fails.
func Test_TaskStateOrdinalsNeverRenumber(t *testing.T) {
	want := map[walkTaskState]int{
		walkTaskPending:  0,
		walkTaskRunning:  1,
		walkTaskPassed:   2,
		walkTaskSentBack: 3,
		walkTaskFailed:   4,
		// APPENDED by stage 4b1 Task 11's fix round 1 — the variance loop's terminal, where the
		// ACTIVITY's own outcome is already on the ledger.
		walkTaskExited: 5,
	}
	for st, ordinal := range want {
		if int(st) != ordinal {
			t.Fatalf("walkTaskState ordinal moved: got %d, want %d — walkSnapshot.ByTask carries this number across a continue-as-new, so it is APPEND-ONLY", int(st), ordinal)
		}
	}
	if len(want) != 6 {
		t.Fatalf("this table must name EVERY walkTaskState; it names %d", len(want))
	}
	if int(walkTaskExited) != len(want)-1 {
		t.Fatalf("a walkTaskState was added without an entry here (highest ordinal %d, table size %d); append it with its number", int(walkTaskExited), len(want))
	}
}

// deliveryWalkerFuncs are the walk's own functions — the ones architect Ruling 3(a)
// forbids to know an activity type. It is FIVE rather than the plan's four because the
// entry func's loop was split out as walkTasks to stay under the cognitive-complexity
// budget, and a guard that did not follow the split would have left the loop unguarded.
var deliveryWalkerFuncs = []string{
	"DeliveryActivityWorkflow",
	"walkTasks",
	"readyTasks",
	"reopenJudgedPair",
	"runTask",
}

// deliveryWalkerBannedIdents are the vocabulary ROOTS a walker may not name. They are
// matched as SUBSTRINGS, not as whole identifiers, and that is load-bearing: the thing a
// walker would actually write is `ActivityTypeService`, not the bare type name, so a
// whole-name check passes the very mutation this guard exists to catch (measured — it did).
// Case matters, which is what keeps `activityTypeName` (a lower-case method on the
// activity, used by the GATE and not by the walk) out of the net.
//
// THE COST OF SUBSTRING MATCHING, recorded because the next reader will hit it (Task 8
// review finding 7): `ArtifactKind` also matches the FIELD SELECTOR `t.ArtifactKind`, which
// is a lifecycle field and exactly what the rule tells the walk to read. So the honest
// readers of that field — roundArtifactKind and isM0Gate — would be flagged if they were
// ever added to deliveryWalkerFuncs, and so would runGate, which calls them. That is
// deliberate: those three are the GATE's, not the walk's, and the walk is what Ruling 3(a)
// constrains. Adding any of them to the list above means loosening the match, not silencing
// the finding.
var deliveryWalkerBannedIdents = []string{
	"ActivityType",
	"ArtifactKind",
	"Kind" + "Mission",
	"CommandFor",
	"ProfileFor",
}

// Test_DeliveryActivityWalker_NamesNoTypeOrCommand is architect Ruling 3(a)'s guard,
// scoped to the WALKER FUNCTIONS rather than to the file — because arch.CheckFileLayout
// forbids a workflow.Context-taking func anywhere but a workflow file, so the strategies
// and the walker must share deliveryactivity.go.
//
// The failure it prevents: a walker that grows `if activityType == ActivityTypeService` is
// a god-workflow worse than the two types it replaced, and §9's smaller-than-sum
// acceptance is what pays for it. The technique is paramguard_arch_test.go's — key the
// bodies by name through go/ast — and it fails LOUDLY on a func it cannot find, so a
// rename cannot make it vacuous.
func Test_DeliveryActivityWalker_NamesNoTypeOrCommand(t *testing.T) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "deliveryactivity.go", nil, parser.ParseComments)
	if err != nil {
		t.Fatalf("parsing the walker's file: %v", err)
	}
	bodies := map[string]*ast.FuncDecl{}
	for _, decl := range f.Decls {
		if fd, ok := decl.(*ast.FuncDecl); ok && fd.Body != nil {
			bodies[fd.Name.Name] = fd
		}
	}
	commands := methodAssetsCommandSet()
	if len(commands) == 0 {
		t.Fatal("the command set is empty, so the string-literal half of this guard would be vacuous")
	}
	for _, name := range deliveryWalkerFuncs {
		fd, ok := bodies[name]
		if !ok {
			t.Fatalf("walker func %q is not in deliveryactivity.go — it was renamed or moved, and a guard that cannot find its subject proves nothing; re-point deliveryWalkerFuncs", name)
		}
		for _, hit := range walkerVocabularyHits(fset, fd, commands) {
			t.Errorf("%s: %s", name, hit)
		}
	}
}

// walkerVocabularyHits reports every banned identifier and every method-assets command
// literal one walker's body names.
func walkerVocabularyHits(fset *token.FileSet, fd *ast.FuncDecl, commands map[string]bool) []string {
	var hits []string
	ast.Inspect(fd.Body, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.Ident:
			for _, banned := range deliveryWalkerBannedIdents {
				if !strings.Contains(v.Name, banned) {
					continue
				}
				hits = append(hits, fmt.Sprintf("%s names %q (%s) — the walker must read lifecycle FIELDS, never an activity type or a command table",
					fset.Position(v.Pos()), v.Name, banned))
			}
		case *ast.BasicLit:
			if v.Kind != token.STRING {
				return true
			}
			if lit, err := strconv.Unquote(v.Value); err == nil && commands[lit] {
				hits = append(hits, fmt.Sprintf("%s names the command literal %q — a command belongs to the DATA, not to the walk",
					fset.Position(v.Pos()), lit))
			}
		}
		return true
	})
	return hits
}

// methodAssetsCommandSet is every slash-command slug the pinned lifecycles carry, on both
// dispatch and review tasks.
func methodAssetsCommandSet() map[string]bool {
	out := map[string]bool{}
	for _, lc := range methodassets.Lifecycles() {
		for _, task := range lc.Tasks {
			if task.Command != "" {
				out[task.Command] = true
			}
		}
	}
	return out
}

// Test_DeliveryWalker_EveryLifecyclePhaseIsOneTheEngineReasonsAbout is the parity the
// widened proposeReviewSet rests on. The claim is NOT that a lifecycle phase id
// round-trips through projectstate.ActivityMethodPhase — that enum has five values and
// none of mission/glossary/volatilities/coreUseCases/architecture/sdp is one of them. It
// is narrower and it is about the ENGINE: every phase id in the pinned lifecycles is a
// string the reviewEngine already reasons about, so no phase silently MISSES its roster.
//
// An empty roster with no reason is precisely the live defect stage 0 fixed once already,
// so an empty set is admitted for exactly TWO phases and is a failure everywhere else.
// MEASURED, and the plan predicted one: `volatilities` (the architect's own signature
// skill, which has never had a critique round) AND `sdp` — because a project-design option
// is COMPUTED, so its only judge is the human at M0. The engine's own narrowing says both
// in prose (reviewengine.go, the InternalInvariant guard) and the second one is real: the
// sdp row answers RequiresHuman with the non-overridable spend floor and staffs no agent.
// An empty roster is admitted here only where the engine also gives a REASON, which is
// what separates "nobody reviews this by design" from the silent miss.
func Test_DeliveryWalker_EveryLifecyclePhaseIsOneTheEngineReasonsAbout(t *testing.T) {
	engine := review.NewReviewEngine()
	seen := 0
	for _, lc := range methodassets.Lifecycles() {
		typ, ok := shapeReviewActivityTypeFor(lc.Type)
		if !ok {
			t.Fatalf("lifecycle %q maps to no review.ActivityType; the engine could not be asked about any of its phases", lc.Type)
		}
		for _, p := range lc.Phases {
			seen++
			set, err := engine.ProposeReviews(fweng.Context{Context: context.Background()},
				review.ReviewChange{ActivityID: "C-x", ComponentID: "x"}, typ, p.ID, "x",
				review.ReviewPolicy{Preset: projectstate.ReviewPresetCheckpoints}, false, nil)
			if err != nil {
				t.Fatalf("%s/%s: the engine refused a phase the data carries: %v", lc.Type, p.ID, err)
			}
			if len(set.Reviewers) == 0 {
				if p.ID != "volatilities" && p.ID != "sdp" {
					t.Fatalf("%s/%s: the engine staffed NO reviewer — an empty roster is the defect stage 0 fixed; only `volatilities` and `sdp` are reviewer-less by design",
						lc.Type, p.ID)
				}
				if set.Reason == "" {
					t.Fatalf("%s/%s: a reviewer-less phase must still carry the engine's REASON; it carried none, which is indistinguishable from a silent miss",
						lc.Type, p.ID)
				}
			}
		}
	}
	if seen != 39 {
		t.Fatalf("the pinned lifecycles carry %d phases, not the 39 this case was measured against; re-measure before changing the number", seen)
	}
}

// shapeReviewActivityTypeFor maps a lifecycle TYPE KEY onto the review engine's activity
// type. The key is "testing:plan" for a variant, so the prefix before ":" is the type.
func shapeReviewActivityTypeFor(typeKey string) (review.ActivityType, bool) {
	base := typeKey
	if i := strings.Index(base, ":"); i >= 0 {
		base = base[:i]
	}
	typ := review.ActivityType(base)
	switch typ {
	case review.ActivityTypeService, review.ActivityTypeFrontend, review.ActivityTypeTesting,
		review.ActivityTypeDeployment, review.ActivityTypeDocumentation, review.ActivityTypeUIDesign,
		review.ActivityTypeIntegration, review.ActivityTypeRequirements, review.ActivityTypeArchitecture,
		review.ActivityTypeProjectDesign:
		return typ, true
	}
	return "", false
}

// ---------------------------------------------------------------------------
// THE GENERIC CHILD'S SHAPE PLUMBING (stage 4b1 Task 8).
// ---------------------------------------------------------------------------

// The lifecycle task ids the construction-rail shape cases signal. Literals, because they
// are what an OPERATOR would send and the point of keying signals on a task is that the id
// is the wire value; a derivation here would test the derivation instead of the routing.
const (
	shapeDesignReviewTask = "designReview"
	shapeSTPTask          = "stp"
	shapeSRSTask          = "srs"
	shapeConstructionTask = "construction"
)

// (stubStrategy and stubStrategies stood here until stage 4b1 Task 11. They filled the
// dispatch slot while Tasks 10 and 11 were unwritten, which is what let the fork/join DAG be
// proved two tasks before either real dispatch existed — and they are the reason strategyFor
// reads an INJECTABLE registry rather than hard-coding its arms. Every case that drove them now
// drives the production registry, and the losing fork branch's pace moved onto
// csFakePipeline.laggingTask, where the waiting happens on the real observe ladder's own
// durable timers. The SEAM stays; only the substitute is gone.)

// shapeSDPEngines are the REAL three estimate Engines. A shape case runs them rather than a
// scripted double for the same reason every construction-rail rig wires the real review
// engine: on the projectDesign shape the Engines' numbers ARE the behaviour under test —
// the dial table's acceptance is that the derived options reproduce the committed ones, and
// a scripted estimate would let exactly that regression pass.
func shapeSDPEngines() sdpEngines {
	return sdpEngines{
		Estimation:   estimation.NewEstimationEngine(),
		OperationEst: operationestimation.NewOperationEstimationEngine(),
		Settlement:   billing.NewBillingEngine(),
	}
}

// registerDeliveryActivity registers the GENERIC child plus every Activity it reaches —
// registerConstruct's set, plus the two execution-ledger verbs only the new child calls
// (the round comment status its gate applies, and the operator note an override at a gate
// records).
func registerDeliveryActivity(env *testsuite.TestWorkflowEnvironment, wf *csWorkflows, ps *csFakeProjectState, pipe agenticjob.AgenticJobAccess) {
	env.RegisterWorkflowWithOptions(wf.DeliveryActivityWorkflow, workflow.RegisterOptions{Name: executionKindDeliveryActivity})
	registerGenPipeline(env, pipe)
	registerGenEpisodes(env, nil)
	registerGenDesignSessionRead(env, ps)
	// The projectDesign lifecycle's compute stages eight slots and its M0 approve commits
	// them and seals the root phase (stage 4b1 Task 9). Registered for EVERY delivery-child
	// case, not only the projectDesign one, because the production worker registers one set
	// per queue and a per-case registration would let a rail reach an unregistered verb.
	registerGenDesignSessionSlotWrites(env, ps)
	registerGenProjectStateVersion(env, ps)
	registerGenProjectStateAdvancePhase(env, ps)
	registerGenConstructionTransition(env, ps)
	csRegisterGenActivityExecution(env, ps)
	registerGenGitStatus(env, ps)
	acts := &genActivities{ActivityExecution: csFakeActivityExecution{ps}}
	env.RegisterActivityWithOptions(acts.ActivityExecutionSetReviewCommentStatus,
		activity.RegisterOptions{Name: "activityExecutionAccess.setReviewCommentStatus"})
	env.RegisterActivityWithOptions(acts.ActivityExecutionRecordOperatorNote,
		activity.RegisterOptions{Name: "activityExecutionAccess.recordOperatorNote"})
}

// shapeApprove / shapeReject are the generic child's gate signals: keyed by TASK, which is
// what lets the router hand each to exactly one coroutine. They replace b12Decide/b12SendBack
// for the construction-rail shape cases; the retired rail's own tests keep those.
func shapeApprove(env *testsuite.TestWorkflowEnvironment, taskID string) func() {
	return func() {
		env.SignalWorkflow(signalTaskDecision, taskDecisionSignal{
			TaskID: taskID, Decision: ReviewApprove, DecidedBy: gateActorOperator,
		})
	}
}

func shapeReject(env *testsuite.TestWorkflowEnvironment, taskID, notes string) func() {
	return func() {
		env.SignalWorkflow(signalTaskDecision, taskDecisionSignal{
			TaskID: taskID, Decision: ReviewReject, DecidedBy: gateActorOperator,
			Feedback: &ReviewFeedback{Notes: notes},
		})
	}
}

// shapeOverride sends an operator override naming ONE task.
func shapeOverride(env *testsuite.TestWorkflowEnvironment, taskID string) func() {
	return func() {
		env.SignalWorkflow(signalOperatorOverride, operatorOverrideSignal{
			TaskID:   taskID,
			Override: ActivityOverride{Kind: OverrideRetry, Notes: "steering " + taskID},
		})
	}
}

// driveContinueAsNewMidWalk runs a service walk under a history budget of ONE event, so the
// first moment nothing is in flight crosses it, then finishes the continued walk on a second
// environment over the SAME ledger and the SAME recorder.
//
// The two runs share the recorder deliberately: the claim is that run 2 finishes what run 1
// started, which is a statement about ONE walk.
func driveContinueAsNewMidWalk(t *testing.T, rig *shapeRig) shapeOutcome {
	t.Helper()
	// The SDK's test environment serves this as the workflow's history length, so the walk's
	// continue-as-new check runs against the PRODUCTION const rather than a smaller budget
	// substituted for it — which is the difference between testing the rule and testing a seam.
	rig.env.SetCurrentHistoryLength(deliveryActivityHistoryBudget + 1)
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeServiceID, Activity: sampleActivity(),
	})
	resume := shapeRequireContinuedAsNew(t, rig.env)

	// The resumed run's environment reports no history length at all, which is under the
	// budget, so it finishes the walk instead of continuing again.
	next := rig.reenter(t)
	next.register(next.env)
	next.env.ExecuteWorkflow(executionKindDeliveryActivity, resume)
	shapeRequireCompleted(t, next.env)
	return next.csOutcome(shapeServiceID)
}

// shapeRequireContinuedAsNew asserts the walk continued as new and returns the input it
// continued WITH, decoded off the error the SDK carries. Asserting the continue without
// reading its payload would pass a snapshot that carried nothing.
func shapeRequireContinuedAsNew(t *testing.T, env *testsuite.TestWorkflowEnvironment) deliveryActivityInput {
	t.Helper()
	if !env.IsWorkflowCompleted() {
		t.Fatal("the walk did not reach a terminal, so it never reached its continue-as-new point")
	}
	var canErr *workflow.ContinueAsNewError
	if err := env.GetWorkflowError(); !errors.As(err, &canErr) {
		t.Fatalf("the walk must continue as new once its history budget is crossed; got %v", err)
	}
	if canErr.WorkflowType == nil || canErr.WorkflowType.Name != executionKindDeliveryActivity {
		t.Fatalf("the continue must re-start the SAME workflow type; got %+v", canErr.WorkflowType)
	}
	var in deliveryActivityInput
	if err := converter.GetDefaultDataConverter().FromPayloads(canErr.Input, &in); err != nil {
		t.Fatalf("decoding the continued input: %v", err)
	}
	if in.Resume == nil {
		t.Fatal("the continue carried NO walkSnapshot; the resumed run would re-dispatch every task from scratch")
	}
	passed := 0
	for _, st := range in.Resume.ByTask {
		if walkTaskState(st) == walkTaskPassed {
			passed++
		}
		if walkTaskState(st) == walkTaskRunning {
			t.Fatalf("the snapshot holds a RUNNING task, so the continue was taken mid-dispatch: %v", in.Resume.ByTask)
		}
	}
	if passed == 0 {
		t.Fatalf("the continue happened before anything passed, so it proves nothing about carrying a walk: %v", in.Resume.ByTask)
	}
	return in
}

// driveForkSignalRouting is the case that would have caught the shared-channel hole: the
// STP branch is mid-dispatch while designReview waits at its gate, and three overrides are
// sent — one at the GATE, one at a task that has not STARTED, and one at a task that has
// already FINISHED.
func driveForkSignalRouting(t *testing.T, rig *shapeRig) shapeOutcome {
	t.Helper()
	rig.cs.project.ReviewPolicy = replayGatedOn(projectstate.MethodPhaseDetailedDesign)
	rig.forkWinner(projectstate.TaskDetailedDesign, 0)
	rig.register(rig.env)
	// t=30s: srs has PASSED and construction has not been scheduled, while designReview
	// waits at its gate and stp is still mid-dispatch (it paces at a minute).
	rig.env.RegisterDelayedCallback(shapeOverride(rig.env, shapeDesignReviewTask), 30*time.Second)
	rig.env.RegisterDelayedCallback(shapeOverride(rig.env, shapeConstructionTask), 31*time.Second)
	rig.env.RegisterDelayedCallback(shapeOverride(rig.env, shapeSRSTask), 32*time.Second)
	rig.env.RegisterDelayedCallback(shapeApprove(rig.env, shapeDesignReviewTask), 120*time.Second)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeServiceID, Activity: sampleActivity(),
	})
	shapeRequireCompleted(t, rig.env)
	return rig.csOutcome(shapeServiceID)
}

// shapeInboxFloodSize is one more than deliveryTaskInboxCapacity, which is the whole point:
// the 65th message cannot fit, and where it goes is the difference between a bound and a
// deadlock.
const shapeInboxFloodSize = deliveryTaskInboxCapacity + 1

// driveInboxOverflow floods a task that never reads its inbox with one more message than the
// inbox holds, lets it retire undrained, and then decides a LATER gate. A blocking deliver
// deadlocks here rather than failing an assertion, which is why the case asserts the walk's
// terminal as well as the counts.
func driveInboxOverflow(t *testing.T, rig *shapeRig) shapeOutcome {
	t.Helper()
	rig.cs.project.ReviewPolicy = replayGatedOn(projectstate.MethodPhaseDetailedDesign)
	// THE FLOOD LANDS INSIDE A DRAIN WINDOW, deliberately (Task 11 review, finding 3). It was
	// timed to MISS one at first, which made the case pass while hiding a real defect: a drained
	// flood used to be one recordOperatorNote CAS write per signal and the per-activity CAS
	// exhausted. Now the drain COALESCES the pass into one note per kind, so the honest place for
	// this flood is where a real operator's would land — mid-poll.
	//
	// Measured against the ladder: srs succeeds at t=15 and the fork opens; stp reports RUNNING at
	// t=15, t=30 and t=45, DRAINING after each, and succeeds at t=60. A flood at t=25 is therefore
	// taken by the drain at t=30 — sixty-four of it, which is all the inbox held — and the
	// SIXTY-FIFTH never reached anything, because ws.pending is only pulled by a receive loop and
	// a dispatch's drain is not one.
	rig.forkWinner(projectstate.TaskDetailedDesign, 3)
	rig.register(rig.env)
	rig.env.RegisterDelayedCallback(func() {
		for range shapeInboxFloodSize {
			shapeOverride(rig.env, shapeSTPTask)()
		}
	}, 25*time.Second)
	rig.env.RegisterDelayedCallback(shapeApprove(rig.env, shapeDesignReviewTask), 120*time.Second)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeServiceID, Activity: sampleActivity(),
	})
	shapeRequireCompleted(t, rig.env)
	// THE DRAINED FLOOD IS ONE WRITE, asserted here rather than in assertShapeInboxOverflow
	// because it is a fact about the STORE and the outcome carries only delivery. It is the
	// deterministic half of the CAS finding: the exhaustion itself needed a concurrent sibling
	// writer to surface, and a case that waited for the race would be flaky, while "sixty-four
	// overrides became one note" is true on every run.
	if n := countNotesAtGate(rig.cs, shapeServiceID, shapeSTPTask); n != 1 {
		t.Fatalf("the drained flood of %d overrides wrote %d operator notes, want exactly 1 — one CAS write per "+
			"signal is what exhausted the per-activity version", shapeInboxFloodSize, n)
	}
	return rig.csOutcome(shapeServiceID)
}

// assertShapeContinueAsNew: the continued walk is ONE walk. Every lifecycle task ran exactly
// once across the two runs — a continue that lost the snapshot would re-dispatch what run 1
// already passed — and the activity reached its binary exit.
func assertShapeContinueAsNew(t *testing.T, name string, got shapeOutcome) {
	t.Helper()
	for _, task := range shapeServiceTasks {
		if n := shapeCount(got.TaskOrder, task); n != 1 {
			t.Fatalf("%s: task %q started %d times across the continue, want exactly 1 — a continue that lost the snapshot re-dispatches passed work; TaskOrder=%v",
				name, task, n, got.TaskOrder)
		}
	}
	if len(got.Reopened) != 0 {
		t.Fatalf("%s: a continue is not a send-back; nothing may be re-opened. Reopened=%v", name, got.Reopened)
	}
	shapeWantEveryRound(t, name, got.RoundsDecided, string(projectstate.RoundPassed))
	shapeWantAdvanced(t, name, got.PhaseAdvanced)
}

// shapeServiceTasks is the `service` lifecycle's ten tasks, in declaration order.
var shapeServiceTasks = []string{
	"srs", "srsReview", "detailedDesign", "designReview",
	"construction", "codeReview", "integration", "stp", "stpReview", "testing",
}

// assertShapeForkSignalRouting is the router's claim, and it is a claim about WHICH TASK
// received a message — not about the walk's terminal, which a lost override would satisfy
// just as well (a gate that never receives one simply waits for its decision instead).
func assertShapeForkSignalRouting(t *testing.T, name string, got shapeOutcome) {
	t.Helper()
	gate := shapeDesignReviewTask + ":" + routedKindOverride
	if !slices.Contains(got.SignalsDelivered, gate) {
		t.Fatalf("%s: the override named the gate and the gate must have received it; SignalsDelivered=%v", name, got.SignalsDelivered)
	}
	// The in-flight SIBLING must not have received it. Two receivers on one shared
	// ReceiveChannel could never guarantee this: the SDK hands each message to exactly one
	// of them, so the polling task would eat it and the gate would wait forever.
	if stolen := shapeSTPTask + ":" + routedKindOverride; slices.Contains(got.SignalsDelivered, stolen) {
		t.Fatalf("%s: a sibling task in flight received the GATE's override; SignalsDelivered=%v", name, got.SignalsDelivered)
	}
	// TOO EARLY buffers: construction had not been scheduled when its override arrived, and
	// openInbox flushed it when it was.
	early := shapeConstructionTask + ":" + routedKindOverride
	if !slices.Contains(got.SignalsDelivered, early) {
		t.Fatalf("%s: a signal for a task that has not started must be BUFFERED and flushed at openInbox, not dropped; SignalsDelivered=%v", name, got.SignalsDelivered)
	}
	// TOO LATE drops, and it is asserted POSITIVELY. srs had already passed, and the
	// difference that matters is not "nothing received it" — a message quietly buffered for
	// srs's next revision satisfies that too — it is that the walk REFUSED it, which is what
	// stops an override of revision 1 deciding revision 2. Measured: with the drop arm
	// replaced by a buffer, the delivered-side assertion alone stays green.
	late := shapeSRSTask + ":" + routedKindOverride
	if !slices.Contains(got.SignalsDropped, late) {
		t.Fatalf("%s: a signal for a FINISHED task must be DROPPED, not held for its next revision; SignalsDropped=%v SignalsDelivered=%v",
			name, got.SignalsDropped, got.SignalsDelivered)
	}
	if slices.Contains(got.SignalsDelivered, late) {
		t.Fatalf("%s: a signal for a FINISHED task was delivered. SignalsDelivered=%v", name, got.SignalsDelivered)
	}
	shapeWantAdvanced(t, name, got.PhaseAdvanced)
}

// assertShapeInboxOverflow: the inbox took exactly its capacity and no more, the overflow
// reached nothing (it went to `pending`, which closeInbox then cleared), and the LATER gate's
// decision was still delivered — which is the half a wedged router makes impossible.
func assertShapeInboxOverflow(t *testing.T, name string, got shapeOutcome) {
	t.Helper()
	flooded := shapeSTPTask + ":" + routedKindOverride
	if n := shapeCount(got.SignalsDelivered, flooded); n != deliveryTaskInboxCapacity {
		t.Fatalf("%s: the inbox must take exactly its capacity (%d) of the %d sent and the overflow must reach NOTHING; it took %d",
			name, deliveryTaskInboxCapacity, shapeInboxFloodSize, n)
	}
	decision := shapeDesignReviewTask + ":" + routedKindDecision
	if !slices.Contains(got.SignalsDelivered, decision) {
		t.Fatalf("%s: the gate's decision must still be delivered after a sibling's inbox filled — a blocking deliver swallows every later signal in the activity; SignalsDelivered=%v",
			name, got.SignalsDelivered)
	}
	shapeWantAdvanced(t, name, got.PhaseAdvanced)
}

// designJobPipeline is the design venue's agentic-job double. It reads the FIVE dispatch
// inputs the Manager sends and does what the seated workflow file would do with them, which
// is what makes the case assert the Manager's own contract with that file: a wrong
// artifact_kind, a missing target_branch or a job_mode the Manager never set would leave the
// slot untouched and the read-back would fail by name.
type designJobPipeline struct {
	mu        sync.Mutex
	ps        *csFakeProjectState
	rec       *shapeRecorder
	submitted []agenticjob.PipelineSpec

	// reviseFirst names the kinds whose FIRST critique asks for a revise and whose second
	// approves — the critic-as-reviewer path, driven rather than asserted on a stub.
	reviseFirst map[string]bool
	// silentCritique names the kinds whose critique job SUCCEEDS and commits no verdict: the
	// ran-but-incomplete job the safe default exists for.
	silentCritique map[string]bool
	critiques      map[string]int
	// failDraft names the kinds whose draft job reaches a terminal FAILURE phase.
	failDraft map[string]bool
	// failCritique names the kinds whose CRITIQUE job reaches a terminal FAILURE phase — the
	// first of the three critique faults the retired rail routed to the human gate (Task 10
	// review, F1), and the one whose absence made a red critique run unrecoverable.
	failCritique map[string]bool
	// rejectCritique names the kinds whose critique DISPATCH is refused outright — the SECOND of
	// the three faults, and the one the first fix round left unpinned (Task 11 review, finding 2):
	// reverting only the dispatch-side arm left the package green.
	rejectCritique map[string]bool
	// drafts counts the draft dispatches per kind, so a case can assert a redraft happened.
	drafts map[string]int
}

func newDesignJobPipeline(ps *csFakeProjectState, rec *shapeRecorder) *designJobPipeline {
	return &designJobPipeline{
		ps: ps, rec: rec,
		reviseFirst: map[string]bool{}, silentCritique: map[string]bool{},
		critiques: map[string]int{}, failDraft: map[string]bool{}, drafts: map[string]int{},
		failCritique: map[string]bool{}, rejectCritique: map[string]bool{},
	}
}

func (p *designJobPipeline) SubmitAgenticJob(_ fwra.Context, spec agenticjob.PipelineSpec) (agenticjob.PipelineHandle, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.submitted = append(p.submitted, spec)
	kind := spec.DispatchInputs[dispatchInputArtifactKind]
	if p.rejectCritique[kind] && spec.DispatchInputs[dispatchInputJobMode] == jobModeCritique {
		// The venue REFUSED the dispatch: no run, no handle, nothing to observe. The Manager's own
		// refusals (an unresolvable repo target, an empty handle) arrive at the same arm.
		return "", fwra.New(fwra.Infrastructure, "the design venue refused the critique dispatch")
	}
	if p.rec != nil {
		// A job with no design COMMAND is the local merge — the one dispatch that is not a
		// lifecycle task — and it is recorded under the same job key csFakePipeline uses, so a
		// merge that appeared or disappeared is visible rather than an empty string in the record.
		if cmd := spec.DispatchInputs[dispatchInputCommand]; cmd != "" {
			p.rec.jobDispatched(cmd)
		} else {
			p.rec.jobDispatched("job:" + spec.DispatchInputs[agenticjob.DispatchInputJobKey])
		}
	}
	switch spec.DispatchInputs[dispatchInputJobMode] {
	case jobModeDraft:
		p.drafts[kind]++
		if !p.failDraft[kind] {
			p.commitDraft(kind)
		}
	case jobModeCritique:
		p.critiques[kind]++
		if !p.failCritique[kind] {
			p.commitCritique(kind)
		}
	}
	return agenticjob.PipelineHandle("design-" + kind + "-" + spec.DispatchInputs[dispatchInputJobMode]), nil
}

// commitDraft is the draft job's own commit: a typed zero-value model for the kind, on the
// slot the read-back reads. A FRESH model per dispatch, so a redraft's staged ref moves.
// Callers hold the lock.
func (p *designJobPipeline) commitDraft(kind string) {
	k, ok := projectstate.ArtifactKindFromWireName(kind)
	if !ok {
		return
	}
	model, ok := projectstate.NewModelForKind(k)
	if !ok {
		return
	}
	p.ps.mu.Lock()
	defer p.ps.mu.Unlock()
	setDesignSlotModel(&p.ps.project, k, model)
}

// commitCritique is the critique job's own commit: the verdict carrier on the same slot.
// Callers hold the lock.
func (p *designJobPipeline) commitCritique(kind string) {
	k, ok := projectstate.ArtifactKindFromWireName(kind)
	if !ok {
		return
	}
	verdict, notes := projectstate.CritiqueVerdictApprove, "the critic had no blocking objection"
	switch {
	case p.silentCritique[kind]:
		verdict, notes = "", ""
	case p.reviseFirst[kind] && p.critiques[kind] == 1:
		verdict, notes = projectstate.CritiqueVerdictRevise, "tighten the second objective"
	}
	p.ps.mu.Lock()
	defer p.ps.mu.Unlock()
	setDesignSlotCritique(&p.ps.project, k, verdict, notes)
}

func (p *designJobPipeline) ObserveAgenticJob(_ fwra.Context, handle agenticjob.PipelineHandle) (agenticjob.PipelineObservation, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	// THE MAP'S VALUE DECIDES, not its key's presence (stage 4b1 Task 12, fix round 1). These
	// loops used to iterate the keys, so `failDraft["glossary"] = false` — the natural way to say
	// "the venue is healthy again" between two runs over one double — still failed the observe
	// while the SUBMIT half read the value and committed the draft. The two halves have to agree
	// about whether a job failed, and a case that clears a fault must be able to clear it.
	for kind, fail := range p.failDraft {
		if fail && strings.Contains(string(handle), "design-"+kind+"-"+jobModeDraft) {
			return agenticjob.PipelineObservation{Phase: agenticjob.PhaseFailed, Diagnostic: "the draft job's CI check went red"}, nil
		}
	}
	for kind, fail := range p.failCritique {
		if fail && strings.Contains(string(handle), "design-"+kind+"-"+jobModeCritique) {
			return agenticjob.PipelineObservation{Phase: agenticjob.PhaseFailed, Diagnostic: "the critique job's run went red"}, nil
		}
	}
	return agenticjob.PipelineObservation{Phase: agenticjob.PhaseSucceeded}, nil
}

func (*designJobPipeline) CancelAgenticJob(fwra.Context, agenticjob.PipelineHandle) error { return nil }

// setDesignSlotModel / setDesignSlotCritique are the WRITE side of designSlotForKind, which
// this package has only ever needed to read. They cover the five kinds the two design
// lifecycles produce and Fatalf-free-ignore the rest, because a case naming a sixth would
// otherwise pass while writing nothing — which is why every case asserts what it read back.
func setDesignSlotModel(p *projectstate.Project, kind projectstate.ArtifactKind, model projectstate.ArtifactModel) {
	if slot := designSlotPtr(p, kind); slot != nil {
		slot.Model = model
	}
}

func setDesignSlotCritique(p *projectstate.Project, kind projectstate.ArtifactKind, verdict, notes string) {
	if slot := designSlotPtr(p, kind); slot != nil {
		slot.CritiqueVerdict, slot.CritiqueNotes = verdict, notes
	}
}

func designSlotPtr(p *projectstate.Project, kind projectstate.ArtifactKind) *projectstate.ArtifactSlot {
	switch kind {
	case projectstate.KindMission:
		return &p.Mission
	case projectstate.KindGlossary:
		return &p.Glossary
	case projectstate.KindVolatilities:
		return &p.Volatilities
	case projectstate.KindCoreUseCases:
		return &p.CoreUseCases
	case projectstate.KindSystem:
		return &p.SystemDesign
	}
	return nil
}

// designShapeRig builds a rig for one DESIGN lifecycle on the generic child: the REAL
// review engine (the gate verdict is the behaviour under test in three of these cases), the
// design job double, and a project at PhaseSystemDesign with NOTHING committed — so the
// walk genuinely drafts rather than being skipped by the skip-if-committed guard.
//
// preset is the project's committed ReviewPolicy preset. "vibes" is what the human-floor case
// needs; a gated preset is what the two-simultaneous-gates case needs.
func designShapeRig(t *testing.T, preset string) (*shapeRig, *designJobPipeline) {
	t.Helper()
	return designShapeRigOn(t, preset, nil)
}

// designShapeRigOn is designShapeRig with an explicit per-project REPO resolver. nil is the
// DORMANT venue (no repo resolves, the read-back and the stage ride main), which is what most
// of these cases want; the local profile's own resolver is what
// Test_DesignWalk_LocalVenue_DispatchesIntoTheGitLocalRepo passes, and it is the combination a
// founder boot actually runs (Task 10 review, minor (a)).
func designShapeRigOn(
	t *testing.T, preset string, repo func(ProjectID) (sourcecontrol.RepoRef, bool),
) (*shapeRig, *designJobPipeline) {
	t.Helper()
	var ts testsuite.WorkflowTestSuite
	rig := &shapeRig{env: ts.NewTestWorkflowEnvironment(), rec: newShapeRecorder()}
	policy := projectstate.ReviewPolicy{}
	if preset != "" {
		p := preset
		policy.Preset = &p
	}
	ps := &csFakeProjectState{project: projectstate.Project{
		ID:           projectstate.ProjectID("shape-design"),
		Version:      1,
		Phase:        projectstate.PhaseSystemDesign,
		ReviewPolicy: policy,
	}}
	ps.rec = rig.rec
	pipe := newDesignJobPipeline(ps, rig.rec)
	deps := gateDeps(ps)
	deps.Review = review.NewReviewEngine()
	deps.SDPEngines = shapeSDPEngines()
	deps.Repo = repo
	wf := csNewWorkflows(deps)
	wf.Deliveries = rig.rec
	rig.cs, rig.cswf = ps, wf
	rig.register = func(env *testsuite.TestWorkflowEnvironment) { registerDeliveryActivity(env, wf, ps, pipe) }
	return rig, pipe
}

// designActivity is one of the three reserved design activities as the derived plan authors
// it and the pump hydrates it: componentless, system-architect, its classified type carried.
func designActivity(id string, typ projectstate.ActivityType) constructionActivity {
	return constructionActivity{ActivityID: id, Kind: activityKindConstruction, Type: typ}
}

// driveRequirementsWalk runs the four-phase `requirements` activity to its terminal.
func driveRequirementsWalk(t *testing.T, rig *shapeRig) shapeOutcome {
	t.Helper()
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID:  shapeProjectID,
		ActivityID: "requirements",
		Activity:   designActivity("requirements", projectstate.ActivityTypeRequirements),
	})
	shapeRequireCompleted(t, rig.env)
	return rig.csOutcome("requirements")
}

// THE FOUR PHASES IN ORDER, one gate each, one round each, each round KINDED (Task 3's
// artifactKind field carrying its first real load). This is the whole of what
// SystemDesignPhaseWorkflow's fixed sequence became: four dependsOn edges in the lifecycle
// data and a walk that reads them.
func Test_DesignWalk_RequirementsWalksItsFourPhasesInOrder(t *testing.T) {
	rig, pipe := designShapeRig(t, projectstate.ReviewPresetVibes)
	got := driveRequirementsWalk(t, rig)

	assertDesignDraftOrder(t, got)
	assertDesignRoundsAreKindedAndPassed(t, rig, got)
	assertDesignCommitsWithoutSealing(t, rig)
	// And each draft was dispatched exactly once: nothing re-drafted.
	for _, kind := range []string{"mission", "glossary", "volatilities", "coreUseCases"} {
		if pipe.drafts[kind] != 1 {
			t.Errorf("%s drafted %d times, want 1", kind, pipe.drafts[kind])
		}
	}
}

// assertDesignDraftOrder pins the four phases' Method order, off the dispatched commands and
// off the gate order. TaskOrder holds the GATES, not the drafts: a review task's start IS its
// round opening (the store double's hook), and a design job's own start has no ledger event.
func assertDesignDraftOrder(t *testing.T, got shapeOutcome) {
	t.Helper()
	var drafts []string
	for _, cmd := range got.Dispatched {
		if strings.HasSuffix(cmd, "-draft") {
			drafts = append(drafts, cmd)
		}
	}
	want := []string{"mission-draft", "glossary-draft", "volatilities-draft", "core-use-cases-draft"}
	if !slices.Equal(drafts, want) {
		t.Fatalf("draft commands = %v, want %v — the four phases in Method order", drafts, want)
	}
	if !slices.Equal(got.TaskOrder, []string{"missionReview", "glossaryReview", "volatilitiesReview", "coreUseCasesReview"}) {
		t.Errorf("TaskOrder = %v, want the four gates in phase order", got.TaskOrder)
	}
}

// assertDesignRoundsAreKindedAndPassed: four rounds, one per phase gate, each numbered 1, each
// passed, and each carrying the JUDGED task's artifact kind — Task 3's field carrying its first
// real load.
func assertDesignRoundsAreKindedAndPassed(t *testing.T, rig *shapeRig, got shapeOutcome) {
	t.Helper()
	wantRounds := []string{
		"requirements:missionReview:1", "requirements:glossaryReview:1",
		"requirements:volatilitiesReview:1", "requirements:coreUseCasesReview:1",
	}
	if !slices.Equal(got.RoundsOpened, wantRounds) {
		t.Fatalf("RoundsOpened = %v, want %v", got.RoundsOpened, wantRounds)
	}
	for _, id := range wantRounds {
		if got.RoundsDecided[id] != string(projectstate.RoundPassed) {
			t.Errorf("round %s decided %q, want passed", id, got.RoundsDecided[id])
		}
	}
	byTask := map[string]*projectstate.ArtifactKind{}
	for _, r := range rig.cs.execution("requirements").Reviews {
		byTask[string(r.TaskID)] = r.ArtifactKind
	}
	for task, want := range map[string]projectstate.ArtifactKind{
		"missionReview": projectstate.KindMission, "glossaryReview": projectstate.KindGlossary,
		"volatilitiesReview": projectstate.KindVolatilities, "coreUseCasesReview": projectstate.KindCoreUseCases,
	} {
		if byTask[task] == nil || *byTask[task] != want {
			t.Errorf("round at %s carries kind %v, want %s", task, byTask[task], want.WireName())
		}
	}
}

// assertDesignCommitsWithoutSealing: the four slots land on main — after the merge, which is
// what makes the model BE on main to commit — and the Phase-1 seal does NOT fire, because
// `system` is the fifth required kind and this activity does not produce it.
func assertDesignCommitsWithoutSealing(t *testing.T, rig *shapeRig) {
	t.Helper()
	if !slices.Equal(rig.cs.committedSlots, []projectstate.ArtifactKind{
		projectstate.KindMission, projectstate.KindGlossary, projectstate.KindVolatilities, projectstate.KindCoreUseCases,
	}) {
		t.Errorf("committed = %v, want the four Phase-1 kinds this activity produces", rig.cs.committedSlots)
	}
	if rig.cs.advanced != 0 {
		t.Errorf("Phase 1 sealed with `system` still uncommitted (%d advances) — the seal must want all FIVE required kinds", rig.cs.advanced)
	}
}

// THE PHASE-1 SEAL, and the MAPPING that makes deleting SystemDesignPhaseWorkflow safe:
// the `architecture` activity commits the FIFTH required kind, and only then does the root
// phase move. Driven with the other four already committed, which is the state a real
// project is in when architecture runs.
func Test_DesignWalk_ArchitectureCommitsTheFifthKindAndSealsPhaseOne(t *testing.T) {
	rig, _ := designShapeRig(t, projectstate.ReviewPresetVibes)
	for _, k := range []projectstate.ArtifactKind{
		projectstate.KindMission, projectstate.KindGlossary,
		projectstate.KindVolatilities, projectstate.KindCoreUseCases,
	} {
		slot := designSlotPtr(&rig.cs.project, k)
		slot.Status = projectstate.ReviewCommitted
	}
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID:  shapeProjectID,
		ActivityID: "architecture",
		Activity:   designActivity("architecture", projectstate.ActivityTypeArchitecture),
	})
	shapeRequireCompleted(t, rig.env)

	if !slices.Equal(rig.cs.committedSlots, []projectstate.ArtifactKind{projectstate.KindSystem}) {
		t.Fatalf("committed = %v, want just the system kind", rig.cs.committedSlots)
	}
	if rig.cs.advanced != 1 {
		t.Fatalf("AdvancePhase called %d times, want exactly 1 — the fifth required kind seals Phase 1", rig.cs.advanced)
	}
	if rig.cs.project.Phase != projectstate.PhaseProjectDesign {
		t.Errorf("phase = %d, want PhaseProjectDesign — the seal moves Phase 1 to Phase 2, not straight to construction",
			rig.cs.project.Phase)
	}
}

// THE SKIP-IF-COMMITTED GUARD, moved from SystemDesignPhaseWorkflow (the 2026-07-16
// incident: a restart re-drafted a committed mission). The state it protects is committed
// Phase-1 slots with an EMPTY LEDGER, which is every project onboarded before the execution
// ledger existed and any whose stage-3 backfill has not run — a ledger-only seed marks every
// task pending there and re-drafts all four. (This repo's own three design activities DO hold
// backfilled attempts, so the earlier claim that no project has a row was wrong; re-measured
// in Task 10's review, F2.)
func Test_DesignWalk_AlreadyCommittedSlotsAreNotRedrafted(t *testing.T) {
	rig, pipe := designShapeRig(t, projectstate.ReviewPresetVibes)
	for _, k := range []projectstate.ArtifactKind{
		projectstate.KindMission, projectstate.KindGlossary,
		projectstate.KindVolatilities, projectstate.KindCoreUseCases,
	} {
		designSlotPtr(&rig.cs.project, k).Status = projectstate.ReviewCommitted
	}
	got := driveRequirementsWalk(t, rig)

	if len(pipe.submitted) != 0 {
		t.Fatalf("a walk over four committed slots dispatched %d jobs; want none", len(pipe.submitted))
	}
	if len(got.RoundsOpened) != 0 {
		t.Errorf("RoundsOpened = %v, want none — every task was already committed", got.RoundsOpened)
	}
	if len(rig.cs.committedSlots) != 0 {
		t.Errorf("re-committed %v; a walk that produced nothing must write nothing", rig.cs.committedSlots)
	}
	if !got.PhaseAdvanced {
		t.Error("the activity must still reach its binary exit: its work IS done")
	}
}

// A DESIGN SEND-BACK RE-OPENS ONLY THE JUDGED PAIR, and the round-2 subject DIFFERS from
// round 1's (Task 5's fix, now on the generic writer). Two claims in one drive because they
// are the same send-back: a re-draft that staged the same ref would make round 2 judge the
// artifact round 1 rejected.
func Test_DesignWalk_ArchitectureSendBackReopensOnlyItsPairAndMovesTheSubject(t *testing.T) {
	rig, pipe := designShapeRig(t, "") // legacy policy: the gate holds for a human
	// The PR rail is READ AS LIVE so the LOCAL merge step is skipped. Under the legacy policy
	// the review engine holds the merge gate for a human too, and this case has no merge
	// approver — so without this the walk would end waiting on a merge nobody was asked for,
	// and the send-back claim would never be reached.
	rig.cswf.RailEnabled = railWired
	rig.register(rig.env)
	// The two decisions are separated deliberately: a reject and an approve that both arrive
	// before round 1 opens are BOTH buffered, the gate takes the reject, and closeInbox then
	// drains the approve as too-late — so round 2 would await a decision that was already spent.
	rig.env.RegisterDelayedCallback(shapeReject(rig.env, "architectureReview", "draw the call chains"), time.Millisecond)
	rig.env.RegisterDelayedCallback(shapeApprove(rig.env, "architectureReview"), 200*time.Millisecond)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID:  shapeProjectID,
		ActivityID: "architecture",
		Activity:   designActivity("architecture", projectstate.ActivityTypeArchitecture),
	})
	shapeRequireCompleted(t, rig.env)
	got := rig.csOutcome("architecture")

	if !slices.Equal(got.Reopened, []string{"architectureDraft"}) {
		t.Fatalf("Reopened = %v, want exactly [architectureDraft] — nothing else may re-run", got.Reopened)
	}
	if pipe.drafts["system"] != 2 {
		t.Fatalf("system drafted %d times, want 2 (the original and its redraft)", pipe.drafts["system"])
	}
	row := rig.cs.execution("architecture")
	subjects := map[int64]string{}
	for _, r := range row.Reviews {
		if r.TaskID == "architectureReview" {
			subjects[r.Round] = r.SubjectRef.Ref
		}
	}
	if len(subjects) != 2 {
		t.Fatalf("want two architectureReview rounds, got %d: %v", len(subjects), subjects)
	}
	if subjects[1] == "" || subjects[2] == "" {
		t.Fatalf("both rounds must cite a staged subject: %v", subjects)
	}
	if subjects[1] == subjects[2] {
		t.Errorf("round 2 cites the SAME subject as round 1 (%q) — the redraft's staging did not move, "+
			"so round 2 judges the artifact round 1 rejected", subjects[1])
	}
}

// THE CRITIQUE IS AN ORDINARY REVIEWER. A revise verdict is recorded as a SEND-BACK verdict
// by the critic's own role — not as an abstention, which would erase the one thing the
// critique produced — and the round still reaches the human gate carrying it.
func Test_DesignWalk_CritiqueRevise_LandsAsTheCriticsSendBackVerdict(t *testing.T) {
	rig, pipe := designShapeRig(t, projectstate.ReviewPresetVibes)
	pipe.reviseFirst["mission"] = true
	// A HUMAN has to answer this gate now (Task 13): a critic's send-back holds it whatever the
	// preset says, so without the callback this walk never finishes. The claim under test is
	// still what the critique's revise LANDED AS, which the hold does not change.
	rig.env.RegisterDelayedCallback(shapeApprove(rig.env, "missionReview"), 2*time.Minute)
	got := driveRequirementsWalk(t, rig)

	row := rig.cs.execution("requirements")
	var missionVerdicts []projectstate.ReviewVerdict
	for _, r := range row.Reviews {
		if r.TaskID == "missionReview" && r.Round == 1 {
			missionVerdicts = r.Verdicts
		}
	}
	if len(missionVerdicts) == 0 {
		t.Fatal("missionReview round 1 carries no verdict; the critique landed nowhere")
	}
	first := missionVerdicts[0]
	if first.Verdict != projectstate.VerdictSendBack {
		t.Errorf("the critic's revise landed as %q, want sendBack", first.Verdict)
	}
	if first.ReviewerRole != "product-manager" || first.Actor != "product-manager" {
		t.Errorf("verdict role/actor = %q/%q, want product-manager — the lifecycle's own workerClass",
			first.ReviewerRole, first.Actor)
	}
	if first.Summary == "" {
		t.Error("the critic's notes must ride the verdict; an empty summary erases the critique")
	}
	// The walk still finished — the critique is a reviewer, not a gate of its own.
	if len(got.RoundsOpened) != 4 {
		t.Errorf("RoundsOpened = %v, want the four phase gates", got.RoundsOpened)
	}
}

// A CRITIC'S SEND-BACK HOLDS THE GATE FOR A HUMAN UNDER VIBES, WITH NO COMMENTS TO RESOLVE
// (stage 4b1 Task 13; Task 10's concern 7, left open by Task 12's fix round 2).
//
// THE DEFECT IT CLOSES: `criticVerdictFor` records the revise honestly and then the no-human arm
// closed the round anyway, because the critic DID judge. Fix round 2 made an open COMMENT hold
// the autogate — but runAgentReviewers appends its verdict with a NIL comment list, so a critic
// that asks for a revise files nothing for that check to find. The round passed carrying its own
// reviewer's rejection, and the only other candidate behaviour — synthesize the redraft — is
// unbounded under `vibes`: the critic rejects draft n+1 for the same reason it rejected draft n,
// `maxPhaseRedrafts` is spent, and nobody is ever warned.
//
// Asserted through the thread as well as the decider, because "no comment held this" is the half
// that distinguishes this hold from fix round 2's.
func Test_DesignWalk_CriticSendBack_HoldsTheGateForAHumanUnderVibes(t *testing.T) {
	rig, pipe := designShapeRig(t, projectstate.ReviewPresetVibes)
	pipe.reviseFirst["mission"] = true
	rig.register(rig.env)
	// Late, deliberately: without a human this walk does not finish.
	rig.env.RegisterDelayedCallback(shapeApprove(rig.env, "missionReview"), 2*time.Minute)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID:  shapeProjectID,
		ActivityID: "requirements",
		Activity:   designActivity("requirements", projectstate.ActivityTypeRequirements),
	})
	shapeRequireCompleted(t, rig.env)

	row := rig.cs.execution("requirements")
	round := latestRoundAt(row, "missionReview")
	if round.RoundID == "" {
		t.Fatal("the mission gate opened no round at all, so nothing held")
	}
	if round.DecidedBy != gateActorOperator {
		t.Errorf("missionReview was decided by %q; a critic's send-back must hold the gate for a HUMAN whatever the preset says",
			round.DecidedBy)
	}
	// The hold came from the VERDICT and not from a comment: the thread is empty.
	if len(round.Thread) != 0 {
		t.Errorf("the round carries %d comment(s); this hold must be the send-back VERDICT's doing, not fix round 2's open-comment check",
			len(round.Thread))
	}
	sentBack := false
	for _, v := range round.Verdicts {
		if v.Verdict == projectstate.VerdictSendBack {
			sentBack = true
		}
		if v.Verdict == projectstate.VerdictApprove && v.Actor == gateActorSystem {
			t.Error("the policy synthesized an approve over the critic's send-back")
		}
	}
	if !sentBack {
		t.Errorf("the critic's send-back must be on the round; verdicts=%+v", round.Verdicts)
	}
	// Exactly ONE critique ran: the hold is a human gate, not a redraft loop.
	if pipe.critiques["mission"] != 1 {
		t.Errorf("mission was critiqued %d times, want 1 — a held gate must not loop on redrafts", pipe.critiques["mission"])
	}
	// The three siblings auto-passed in the SAME walk, so the hold is the send-back's doing.
	for _, task := range []string{"glossaryReview", "volatilitiesReview", "coreUseCasesReview"} {
		if r := latestRoundAt(row, task); r.DecidedBy != gateActorSystem {
			t.Errorf("round at %s was decided by %q; under vibes its siblings auto-pass", task, r.DecidedBy)
		}
	}
	if !shapeExitedCompleted(rig.cs, "requirements") {
		t.Error("the activity must reach its binary exit once the held gate is answered")
	}
}

// A CRITIQUE THAT COMMITTED NO VERDICT HOLDS THE GATE FOR A HUMAN, EVEN UNDER VIBES. This is
// readBackCritiqueOn's safe default, carried into the child: the job reported success and
// judged nothing, so closing the gate on the policy's no-human arm would auto-approve an
// artifact nobody looked at. The case drives `vibes`, which auto-approves every OTHER gate in
// the same walk — so it is the critique's silence doing the work and not the policy.
func Test_DesignWalk_SilentCritique_HoldsTheGateForAHumanUnderVibes(t *testing.T) {
	rig, _ := designShapeRig(t, projectstate.ReviewPresetVibes)
	pipe := newDesignJobPipeline(rig.cs, rig.rec)
	pipe.silentCritique["mission"] = true
	rig.register = func(env *testsuite.TestWorkflowEnvironment) { registerDeliveryActivity(env, rig.cswf, rig.cs, pipe) }
	rig.register(rig.env)
	// The human answers, late — which is the point: without a human this walk never finishes.
	rig.env.RegisterDelayedCallback(shapeApprove(rig.env, "missionReview"), 2*time.Second)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID:  shapeProjectID,
		ActivityID: "requirements",
		Activity:   designActivity("requirements", projectstate.ActivityTypeRequirements),
	})
	shapeRequireCompleted(t, rig.env)

	row := rig.cs.execution("requirements")
	for _, r := range row.Reviews {
		if r.TaskID != "missionReview" {
			continue
		}
		if len(r.Verdicts) == 0 {
			t.Fatal("the silent critique must still leave a verdict on the round")
		}
		if r.Verdicts[0].Verdict != projectstate.VerdictAbstain {
			t.Errorf("a critique that judged nothing landed as %q, want abstain", r.Verdicts[0].Verdict)
		}
		if r.DecidedBy != gateActorOperator {
			t.Errorf("missionReview was decided by %q; a gate whose critic did not judge must be answered by a HUMAN, "+
				"whatever the policy says", r.DecidedBy)
		}
	}
	// Its three siblings, whose critics DID judge, were auto-passed by the vibes policy — which
	// is what proves the hold above came from the critique and not from the preset.
	for _, r := range row.Reviews {
		if r.TaskID == "glossaryReview" && r.DecidedBy != gateActorSystem {
			t.Errorf("glossaryReview decided by %q, want the policy's system actor", r.DecidedBy)
		}
	}
}

// volatilitiesReview STAFFS NO AGENT CRITIC while its three siblings do — the one
// reviewer-less row in the `requirements` lifecycle, and the fact the engine's own
// phaseVolatilities constant already names. Asserted off the DISPATCHED commands, because the
// claim is that no critique job was submitted for it.
func Test_DesignWalk_VolatilitiesReviewDispatchesNoAgentCritic(t *testing.T) {
	rig, _ := designShapeRig(t, projectstate.ReviewPresetVibes)
	got := driveRequirementsWalk(t, rig)

	var critiques []string
	for _, cmd := range got.Dispatched {
		if strings.HasSuffix(cmd, "-critique") {
			critiques = append(critiques, cmd)
		}
	}
	want := []string{"mission-critique", "glossary-critique", "core-use-cases-critique"}
	if !slices.Equal(critiques, want) {
		t.Fatalf("critique commands = %v, want %v — volatilities has no critic and must dispatch none", critiques, want)
	}
	// And its gate still ran and still passed: no critic is not no review.
	if got.RoundsDecided["requirements:volatilitiesReview:1"] != string(projectstate.RoundPassed) {
		t.Errorf("volatilitiesReview round = %q, want passed", got.RoundsDecided["requirements:volatilitiesReview:1"])
	}
}

// A TERMINAL DRAFT FAILURE records a FAILED attempt and fails the walk with the diagnostic —
// the child's rule since Task 9's compute, replacing the retired session's StageDraftFailed
// human gate. The claim is that the failure is VISIBLE in the ledger, not that it is silent.
func Test_DesignWalk_DraftJobFailure_RecordsTheAttemptAndFailsTheWalk(t *testing.T) {
	rig, _ := designShapeRig(t, projectstate.ReviewPresetVibes)
	pipe := newDesignJobPipeline(rig.cs, rig.rec)
	pipe.failDraft["mission"] = true
	rig.register = func(env *testsuite.TestWorkflowEnvironment) { registerDeliveryActivity(env, rig.cswf, rig.cs, pipe) }
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID:  shapeProjectID,
		ActivityID: "requirements",
		Activity:   designActivity("requirements", projectstate.ActivityTypeRequirements),
	})
	if !rig.env.IsWorkflowCompleted() {
		t.Fatal("the walk did not reach a terminal")
	}
	err := rig.env.GetWorkflowError()
	if err == nil {
		t.Fatal("a terminal draft failure must fail the walk; a nil error is the silent success this arm exists to refuse")
	}
	if !strings.Contains(err.Error(), "CI check went red") {
		t.Errorf("the failure must carry the venue's diagnostic, got %v", err)
	}
	row := rig.cs.execution("requirements")
	var failed bool
	for _, a := range row.Attempts {
		if a.Task == "missionDraft" && a.Outcome == projectstate.OutcomeFailed {
			failed = true
		}
	}
	if !failed {
		t.Errorf("no FAILED attempt at missionDraft; the ledger must say what happened: %+v", row.Attempts)
	}
	if len(rig.cs.committedSlots) != 0 {
		t.Errorf("a failed walk committed %v; nothing may be committed", rig.cs.committedSlots)
	}
}

// THE DISPATCH'S OWN CONTRACT WITH aiarch-design.yml: the five inputs, the per-project repo
// target and THAT workflow file. A design job sent to the construction venue runs the wrong
// file, which is exactly what routing it through csWorkflows.gitEnabled would have done on
// every local boot.
func Test_DesignWalk_DispatchCarriesTheDesignVenueAndItsFiveInputs(t *testing.T) {
	rig, pipe := designShapeRig(t, projectstate.ReviewPresetVibes)
	rig.cswf.Repo = func(ProjectID) (sourcecontrol.RepoRef, bool) { return sourcecontrol.RepoRef("acme|acme/app"), true }
	// The construction rail stays DORMANT, as it does on the local profile — and the design
	// dispatch must still resolve its venue.
	rig.cswf.RailEnabled = railDormant
	driveRequirementsWalk(t, rig)

	if len(pipe.submitted) == 0 {
		t.Fatal("nothing was dispatched")
	}
	first := pipe.submitted[0]
	if first.WorkflowFile != designWorkflowFileName {
		t.Errorf("workflow file = %q, want %q", first.WorkflowFile, designWorkflowFileName)
	}
	if first.TargetRepo.Owner != "acme" || first.TargetRepo.Name != "app" {
		t.Errorf("target repo = %+v, want the per-project design venue", first.TargetRepo)
	}
	want := map[string]string{
		dispatchInputArtifactKind:  "mission",
		dispatchInputCommand:       "mission-draft",
		dispatchInputTargetBranch:  activityBranchName("requirements"),
		dispatchInputPriorStateRef: "",
		dispatchInputJobMode:       jobModeDraft,
	}
	if !maps.Equal(first.DispatchInputs, want) {
		t.Errorf("dispatch inputs = %v, want %v", first.DispatchInputs, want)
	}
	// The critique rides the SAME branch under the critique mode.
	for _, spec := range pipe.submitted {
		if spec.DispatchInputs[dispatchInputJobMode] != jobModeCritique {
			continue
		}
		if spec.DispatchInputs[dispatchInputTargetBranch] != activityBranchName("requirements") {
			t.Errorf("a critique dispatched at branch %q, want the activity branch",
				spec.DispatchInputs[dispatchInputTargetBranch])
		}
	}
}

// A DORMANT VENUE reads back and stages on MAIN and dispatches with no workflow file —
// byte-for-byte the retired rail's dormant behaviour, and the posture every non-git
// composition runs in.
func Test_DesignWalk_DormantVenue_StagesOnMainAndFallsBackToTheConfiguredRepo(t *testing.T) {
	rig, pipe := designShapeRig(t, projectstate.ReviewPresetVibes)
	rig.cswf.Repo = nil
	driveRequirementsWalk(t, rig)

	if len(pipe.submitted) == 0 {
		t.Fatal("nothing was dispatched")
	}
	for _, spec := range pipe.submitted {
		if spec.WorkflowFile != "" {
			t.Errorf("a dormant venue must leave the workflow file empty so the RA falls back, got %q", spec.WorkflowFile)
		}
		if spec.DispatchInputs[dispatchInputTargetBranch] != "" {
			t.Errorf("a dormant venue names no branch, got %q", spec.DispatchInputs[dispatchInputTargetBranch])
		}
	}
}

// ---- the design arm's pure rules ------------------------------------------

// designSlotOfTask is what splits the two rails, and the split must come off the DATA rather
// than a table: every design lifecycle's dispatch task resolves a slot and every construction
// lifecycle's does not. Walked over all fourteen lifecycles, so a platform release that
// respelled a construction kind into a slot name fails HERE rather than misrouting a build.
func Test_DesignSlotOfTask_SplitsTheRailsOnTheData(t *testing.T) {
	designLifecycles := map[string]bool{"requirements": true, "architecture": true, "projectDesign": true}
	for _, lc := range methodassets.Lifecycles() {
		for _, task := range lc.Tasks {
			_, ok := designSlotOfTask(lc, task)
			want := designLifecycles[lc.Type]
			if ok != want {
				t.Errorf("%s/%s: designSlotOfTask = %v, want %v", lc.Type, task.ID, ok, want)
			}
		}
	}
}

// THE MAPPING, pinned. Phase1RequiredKinds() must be exactly the kinds the `requirements` and
// `architecture` lifecycles produce, four-then-one, with NO residue in either direction. This
// is the measurement that makes deleting SystemDesignPhaseWorkflow's sequence safe, and it is
// a test rather than a comment because a method-assets release could move it silently.
func Test_Phase1RequiredKinds_AreExactlyTheTwoDesignLifecyclesOutput(t *testing.T) {
	byLifecycle := map[string][]projectstate.ArtifactKind{}
	for _, key := range []string{"requirements", "architecture"} {
		lc, ok := methodassets.LifecycleFor(key)
		if !ok {
			t.Fatalf("the platform carries no %s lifecycle", key)
		}
		byLifecycle[key] = designSlotsOfLifecycle(lc)
	}
	if len(byLifecycle["requirements"]) != 4 {
		t.Errorf("requirements produces %v, want FOUR kinds", byLifecycle["requirements"])
	}
	if len(byLifecycle["architecture"]) != 1 {
		t.Errorf("architecture produces %v, want ONE kind", byLifecycle["architecture"])
	}
	produced := append(append([]projectstate.ArtifactKind{}, byLifecycle["requirements"]...), byLifecycle["architecture"]...)
	required := projectstate.Phase1RequiredKinds()
	if !slices.Equal(produced, required) {
		t.Fatalf("the two design lifecycles produce %v but Phase1RequiredKinds() is %v — "+
			"the four-then-one mapping has residue, and the Phase-1 seal would then wait on a kind nothing drafts "+
			"or seal without one it does", produced, required)
	}
}

// The command each design task runs is the LIFECYCLE'S, and DesignCommandFor must still agree
// with it — two answers to one question is how a platform release silently re-points a job.
func Test_DesignCommands_MatchTheLifecycleData(t *testing.T) {
	for _, key := range []string{"requirements", "architecture"} {
		lc, _ := methodassets.LifecycleFor(key)
		for _, task := range lc.Tasks {
			if task.Command == "" {
				continue
			}
			kind, ok := designSlotOfTask(lc, task)
			if !ok {
				t.Fatalf("%s/%s carries a command but resolves no design slot", key, task.ID)
			}
			mode := projectstate.DesignJobModeDraft
			if task.Kind == methodassets.LifecycleTaskReview {
				mode = projectstate.DesignJobModeCritique
			}
			if got := projectstate.DesignCommandFor(kind, mode, ""); got != task.Command {
				t.Errorf("%s/%s: lifecycle says %q, DesignCommandFor says %q", key, task.ID, task.Command, got)
			}
		}
	}
}

// criticVerdictFor is a three-way map and the third arm is the load-bearing one: an outcome
// that is neither a pass nor a rejection means the critic did NOT judge, and `judged=false` is
// what holds the gate for a human.
func Test_CriticVerdictFor_NeverApprovesWhatWasNotJudged(t *testing.T) {
	cases := map[projectstate.TaskOutcome]struct {
		verdict projectstate.VerdictKind
		judged  bool
	}{
		projectstate.OutcomePassed:   {projectstate.VerdictApprove, true},
		projectstate.OutcomeRejected: {projectstate.VerdictSendBack, true},
		projectstate.OutcomeFailed:   {projectstate.VerdictAbstain, false},
		projectstate.OutcomePending:  {projectstate.VerdictAbstain, false},
		projectstate.OutcomeSkipped:  {projectstate.VerdictAbstain, false},
	}
	for outcome, want := range cases {
		verdict, judged := criticVerdictFor(outcome)
		if verdict != want.verdict || judged != want.judged {
			t.Errorf("%s -> (%s, %v), want (%s, %v)", outcome, verdict, judged, want.verdict, want.judged)
		}
	}
}

// ===========================================================================
// THE CONSTRUCTION ARM (stage 4b1 Task 11). The generic child walking a BUILD
// lifecycle: the agentic construction job, the per-project venue, the pending→resolved
// attempt pair with its episode, the send-back's steer riding the redraft, the failed
// job, and the local merge's two profiles.
//
// These run on the SAME construction-rail doubles every other delivery-child case uses;
// the only addition is a rail-wired variant, because the PR rail is the one thing a local
// profile cannot exercise and the merge's two answers are the point of asserting it.
// ===========================================================================

// constructionShapeRig builds a rig for one BUILD lifecycle on the generic child with the
// PR rail DORMANT — the local profile, which is what a founder boot runs and what the local
// merge job belongs to.
func constructionShapeRig(t *testing.T, policy projectstate.ReviewPolicy) *shapeRig {
	t.Helper()
	var ts testsuite.WorkflowTestSuite
	rig := &shapeRig{env: ts.NewTestWorkflowEnvironment(), rec: newShapeRecorder()}
	ps := newFakeProjectStateWithPolicy(policy)
	ps.rec = rig.rec
	pipe := &csFakePipeline{phase: PipelineSucceeded, episode: csCaptureSeamSummary(), rec: rig.rec}
	deps := gateDeps(ps)
	deps.Review = review.NewReviewEngine()
	deps.SDPEngines = shapeSDPEngines()
	wf := csNewWorkflows(deps)
	wf.Deliveries = rig.rec
	rig.cs, rig.cswf, rig.pipe = ps, wf, pipe
	rig.register = func(env *testsuite.TestWorkflowEnvironment) { registerDeliveryActivity(env, wf, ps, pipe) }
	return rig
}

// THE DISPATCH IS THE LIFECYCLE'S, AND SO IS ITS COMMAND (stage 4b1 Task 11). `deployment` is
// the linear three-phase build, so the three dispatch inputs can be read one per phase without
// a fork in the way.
//
// The claim is the contract with the SEATED aiarch-construct.yml: activity_id, component_id,
// phase and command are what that workflow file reads, and the command comes off the LIFECYCLE
// TASK rather than from CommandFor — which is the thing this task changed and the thing a
// regression would silently revert (the two agree today, so nothing else would notice).
func Test_ConstructionWalk_DispatchCarriesTheLifecycleCommandAndItsPhase(t *testing.T) {
	rig := constructionShapeRig(t, projectstate.ReviewPolicy{})
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	shapeRequireCompleted(t, rig.env)

	lc, ok := methodassets.LifecycleFor("deployment")
	if !ok {
		t.Fatal("the pinned method assets carry no `deployment` lifecycle")
	}
	var want []map[string]string
	for _, task := range lc.Tasks {
		if task.Kind != methodassets.LifecycleTaskDispatch {
			continue
		}
		want = append(want, map[string]string{"phase": task.Phase, "command": task.Command})
	}
	var got []map[string]string
	for _, spec := range submittedSpecs(rig.pipe) {
		phase := spec.DispatchInputs["phase"]
		if phase == "" {
			continue // the merge job, asserted by its own case
		}
		if spec.DispatchInputs["activity_id"] != shapeDeploymentID {
			t.Errorf("dispatch at %s names activity %q, want %q", phase, spec.DispatchInputs["activity_id"], shapeDeploymentID)
		}
		if spec.DispatchInputs["component_id"] != "comp-deploy" {
			t.Errorf("dispatch at %s names component %q, want comp-deploy", phase, spec.DispatchInputs["component_id"])
		}
		got = append(got, map[string]string{"phase": phase, "command": spec.DispatchInputs["command"]})
	}
	if len(got) != len(want) {
		t.Fatalf("dispatched %d jobs, want one per dispatch task (%d): %v", len(got), len(want), got)
	}
	for i := range want {
		if got[i]["phase"] != want[i]["phase"] || got[i]["command"] != want[i]["command"] {
			t.Errorf("dispatch %d = %v, want %v — the command and the phase are the lifecycle task's own fields", i, got[i], want[i])
		}
	}
}

// THE ATTEMPT PAIR AND ITS EVIDENCE. A construction task stages no model, so the retired rail
// cited the EPISODE the dispatch burned and the generic child has to as well — otherwise every
// construction attempt cites EvidenceNone and the tokens spent sit in the episode ledger with
// nothing in the task ledger pointing at them, which is the link the cost views follow.
//
// It also asserts the attempt is opened PENDING before the dispatch and resolved in place under
// the SAME id: one id, one attempt, which is what makes a run that died mid-dispatch legible.
func Test_ConstructionWalk_AttemptsAreOpenedPendingAndResolvedWithTheEpisode(t *testing.T) {
	rig := constructionShapeRig(t, projectstate.ReviewPolicy{})
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	shapeRequireCompleted(t, rig.env)

	row := rig.cs.execution(shapeDeploymentID)
	seen := map[projectstate.MethodTask]projectstate.TaskAttempt{}
	for _, a := range row.Attempts {
		if a.Actor != projectstate.ActorAgent {
			continue
		}
		if prev, dup := seen[a.Task]; dup && prev.AttemptID != a.AttemptID {
			t.Errorf("task %s holds two attempt ids (%q and %q) for one dispatch", a.Task, prev.AttemptID, a.AttemptID)
		}
		seen[a.Task] = a
	}
	for _, task := range []projectstate.MethodTask{
		projectstate.TaskDetailedDesign, projectstate.TaskConstruction, projectstate.TaskIntegration,
	} {
		a, ok := seen[task]
		if !ok {
			t.Fatalf("no agent attempt recorded at %s; the ledger must hold one per dispatch", task)
		}
		if a.Outcome != projectstate.OutcomePassed {
			t.Errorf("attempt at %s resolved %q, want passed", task, a.Outcome)
		}
		if a.Evidence.Kind != projectstate.EvidenceEpisode || a.Evidence.Ref == "" {
			t.Errorf("attempt at %s cites %v/%q, want the EPISODE the dispatch burned", task, a.Evidence.Kind, a.Evidence.Ref)
		}
	}
}

// A FAILED CONSTRUCTION JOB FLAGS THE VARIANCE AND LEAVES THE FAILURE ON THE LEDGER. The four
// answers the variance loop can then give are driven one per case in the variance block below;
// what THIS case pins is the part that is true of all of them — the diagnostic is recorded on the
// attempt, the flagged variance is on the session view, and the DAG never made the next phase
// ready.
//
// It runs the DEFAULT rig, whose fakeIntervention answers Retry, so the loop exhausts its budget:
// the terminal is VarianceExhausted and the walk ends WITHOUT a workflow error, which is what the
// retired failVarianceExhausted did and what keeps the pump's cascade alive.
func Test_ConstructionWalk_JobFailure_FlagsTheVarianceAndRecordsATerminal(t *testing.T) {
	rig := constructionShapeRig(t, projectstate.ReviewPolicy{})
	rig.pipe.failTask = map[projectstate.MethodTask]bool{projectstate.TaskDetailedDesign: true}
	rig.pipe.diag = "the construct job's CI check went red"
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	shapeRequireCompleted(t, rig.env)
	if err := rig.env.GetWorkflowError(); err != nil {
		t.Fatalf("an exhausted supervision budget is a RECORDED terminal, not a workflow failure — a child that errors "+
			"fails the pump run blocked on it: %v", err)
	}
	row := rig.cs.execution(shapeDeploymentID)
	failed := false
	for _, a := range row.Attempts {
		if a.Task == projectstate.TaskDetailedDesign && a.Outcome == projectstate.OutcomeFailed {
			failed = true
			if a.Evidence.Kind != projectstate.EvidenceEpisode {
				t.Errorf("the failed attempt cites %v; a failed dispatch still burned tokens and still owes the episode",
					a.Evidence.Kind)
			}
		}
	}
	if !failed {
		t.Errorf("the FAILED attempt must be on the ledger — an operator reads the attempt, not the workflow error. attempts=%+v", row.Attempts)
	}
	if row.FailureReason != projectstate.VarianceExhausted {
		t.Errorf("the activity must carry a terminal failure reason so the pump stops seeing it Running; got %v", row.FailureReason)
	}
	if !strings.Contains(row.FailureDetail, "max attempts") {
		t.Errorf("the terminal's detail must say the budget was spent; got %q", row.FailureDetail)
	}
	// And NOTHING was dispatched after the failure: the DAG's successor tasks never became
	// ready, which is what a re-walk of a flat phase list would have got wrong.
	for _, spec := range submittedSpecs(rig.pipe) {
		if cmd := spec.DispatchInputs["command"]; cmd == "deployment-construction" {
			t.Errorf("the phase after the failed one was dispatched anyway (%q)", cmd)
		}
	}
}

// THE SEND-BACK'S STEER RIDES THE REDRAFT. Without it the redraft runs against the prompt that
// was just rejected, which is the send-back doing nothing — and the walk keeps the notes
// walk-locally (walkState.feedback), so this is the point where a walk-local fact becomes a
// dispatch input the seated workflow reads.
func Test_ConstructionWalk_SendBackRedraftCarriesTheOperatorSteer(t *testing.T) {
	const notes = "name the failure mode the retry policy assumes"
	rig := constructionShapeRig(t, projectstate.ReviewPolicy{
		GatedPhasesByType: map[string][]projectstate.ActivityMethodPhase{
			"deployment": {projectstate.MethodPhaseDetailedDesign},
		},
	})
	rig.register(rig.env)
	rig.env.RegisterDelayedCallback(shapeReject(rig.env, shapeDesignReviewTask, notes), 30*time.Second)
	rig.env.RegisterDelayedCallback(shapeApprove(rig.env, shapeDesignReviewTask), 90*time.Second)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	shapeRequireCompleted(t, rig.env)

	var designDispatches []string
	for _, spec := range submittedSpecs(rig.pipe) {
		if spec.DispatchInputs["command"] == "deployment-detailed-design" {
			designDispatches = append(designDispatches, spec.DispatchInputs[dispatchInputOperatorNote])
		}
	}
	if len(designDispatches) != 2 {
		t.Fatalf("the judged dispatch must run twice (draft, then redraft); got %d", len(designDispatches))
	}
	if designDispatches[0] != "" {
		t.Errorf("the FIRST dispatch carried an operator note (%q); nothing had been sent back yet", designDispatches[0])
	}
	if !strings.Contains(designDispatches[1], notes) {
		t.Errorf("the redraft's operator note = %q, want it to carry the send-back's own notes", designDispatches[1])
	}
}

// THE LOCAL MERGE'S TWO PROFILES (R6). On the rail-dormant local profile nothing else lands
// activity/<id> on main, so the child dispatches the merge job; when the PR rail is live the
// cloud git-forward lifecycle owns the merge and the job must NOT fire, or the branch is merged
// twice by two mechanisms.
func Test_ConstructionWalk_LocalMergeRunsOnTheLocalProfileOnly(t *testing.T) {
	local := constructionShapeRig(t, projectstate.ReviewPolicy{})
	local.register(local.env)
	local.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	shapeRequireCompleted(t, local.env)
	if n := mergeJobCount(submittedSpecs(local.pipe)); n != 1 {
		t.Fatalf("the local profile must dispatch exactly one merge job; got %d", n)
	}

	// The rail-wired half: the PR rail performs the merge and the job never fires.
	var ts testsuite.WorkflowTestSuite
	env := ts.NewTestWorkflowEnvironment()
	ps := newFakeProjectStateWithPolicy(projectstate.ReviewPolicy{})
	git := newStubGitStatus(0)
	rail := &stubRail{ciRollup: sourcecontrol.CheckSuccess}
	wf := gitWiredWorkflows(ps, rail, git, true)
	wf.Review = review.NewReviewEngine()
	pipe := &csFakePipeline{phase: PipelineSucceeded, episode: csCaptureSeamSummary()}
	env.RegisterWorkflowWithOptions(wf.DeliveryActivityWorkflow, workflow.RegisterOptions{Name: executionKindDeliveryActivity})
	registerGenPipeline(env, pipe)
	registerGenEpisodes(env, nil)
	registerGenDesignSessionRead(env, ps)
	registerGenDesignSessionSlotWrites(env, ps)
	registerGenProjectStateVersion(env, ps)
	registerGenProjectStateAdvancePhase(env, ps)
	registerGenConstructionTransition(env, ps)
	csRegisterGenActivityExecution(env, ps)
	registerGenGitStatus(env, git)
	registerGenRail(env, rail)
	acts := &genActivities{ActivityExecution: csFakeActivityExecution{ps}}
	env.RegisterActivityWithOptions(acts.ActivityExecutionSetReviewCommentStatus,
		activity.RegisterOptions{Name: "activityExecutionAccess.setReviewCommentStatus"})
	env.RegisterActivityWithOptions(acts.ActivityExecutionRecordOperatorNote,
		activity.RegisterOptions{Name: "activityExecutionAccess.recordOperatorNote"})
	env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: "p-rail", ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	shapeRequireCompleted(t, env)
	if n := mergeJobCount(submittedSpecs(pipe)); n != 0 {
		t.Errorf("the PR rail owns the merge, so the local merge job must NOT be dispatched; got %d", n)
	}
	rail.mu.Lock()
	merges := rail.merges
	rail.mu.Unlock()
	if merges != 1 {
		t.Errorf("the rail performed %d merges, want exactly 1 — the branch has to land somewhere", merges)
	}
	// And the per-project venue rode the dispatch: the project's OWN repo and the seated
	// construct workflow file, which is what the gh-mode venue switch is for.
	for _, spec := range submittedSpecs(pipe) {
		if spec.DispatchInputs["phase"] == "" {
			continue
		}
		if spec.TargetRepo.Owner != "owner" || spec.TargetRepo.Name != "repo-1" {
			t.Errorf("dispatch target = %+v, want the project's own repo", spec.TargetRepo)
		}
		if spec.WorkflowFile != constructWorkflowFileName {
			t.Errorf("dispatch workflow file = %q, want %q", spec.WorkflowFile, constructWorkflowFileName)
		}
	}
}

// mergeJobCount counts the dispatches that are the LOCAL MERGE job rather than a lifecycle
// task's: the merge carries the job key and no phase.
func mergeJobCount(specs []agenticjob.PipelineSpec) int {
	n := 0
	for _, spec := range specs {
		if spec.DispatchInputs[agenticjob.DispatchInputJobKey] == agenticjob.DispatchJobMerge {
			n++
		}
	}
	return n
}

// ---------------------------------------------------------------------------
// THE VARIANCE LOOP, through the child (stage 4b1 Task 11, fix round 1). The retired
// supervision loop's whole answer to a failed job — DECIDE, retry or take over up to
// maxVarianceAttempts, or escalate to a bounded operator override with a Skip terminal —
// reproduced per TASK instead of per activity, and asserted on the four answers it can give.
// ---------------------------------------------------------------------------

// varianceRig is a construction rig whose intervention Engine answers a fixed directive, so each
// case drives ONE arm of handleVariance's switch rather than whatever the default policy happens
// to decide.
func varianceRig(t *testing.T, directive intervention.VarianceDirective, wait time.Duration) *shapeRig {
	t.Helper()
	var ts testsuite.WorkflowTestSuite
	rig := &shapeRig{env: ts.NewTestWorkflowEnvironment(), rec: newShapeRecorder()}
	ps := newFakeProjectStateWithPolicy(projectstate.ReviewPolicy{})
	ps.rec = rig.rec
	pipe := &csFakePipeline{
		phase: PipelineSucceeded, episode: csCaptureSeamSummary(), rec: rig.rec,
		failTask: map[projectstate.MethodTask]bool{}, failTaskFirst: map[projectstate.MethodTask]int{},
	}
	deps := gateDeps(ps)
	deps.Intervention = &fakeIntervention{directive: directive}
	deps.Review = review.NewReviewEngine()
	deps.SDPEngines = shapeSDPEngines()
	deps.EscalationWaitTimeout = wait
	wf := csNewWorkflows(deps)
	wf.Deliveries = rig.rec
	rig.cs, rig.cswf, rig.pipe = ps, wf, pipe
	rig.register = func(env *testsuite.TestWorkflowEnvironment) { registerDeliveryActivity(env, wf, ps, pipe) }
	return rig
}

// A RETRY DIRECTIVE RE-DISPATCHES THE TASK AND THE WALK GOES ON. The ledger shows the failure
// AND the success at the SAME task, under two numbered attempts, with the walk's revision
// unmoved — a variance retry is not a send-back, so no round re-opens and no phase re-runs.
func Test_ConstructionVariance_RetryRedispatchesTheTaskAndPasses(t *testing.T) {
	rig := varianceRig(t, intervention.VarianceRetry, 0)
	rig.pipe.failTaskFirst[projectstate.TaskDetailedDesign] = 1
	rig.pipe.diag = "the construct job's CI check went red"
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	// The walk FINISHES, which is the whole point: one red CI run used to cost the activity.
	shapeRequireCompleted(t, rig.env)

	row := rig.cs.execution(shapeDeploymentID)
	var outcomes []projectstate.TaskOutcome
	var numbers []int
	for _, a := range row.Attempts {
		if a.Task == projectstate.TaskDetailedDesign {
			outcomes = append(outcomes, a.Outcome)
			numbers = append(numbers, a.Attempt)
		}
	}
	if !slices.Equal(outcomes, []projectstate.TaskOutcome{projectstate.OutcomeFailed, projectstate.OutcomePassed}) {
		t.Fatalf("the ledger at detailedDesign reads %v, want FAILED then PASSED — a retry that overwrote the "+
			"first attempt would erase the failure an operator has to see", outcomes)
	}
	if !slices.Equal(numbers, []int{1, 2}) {
		t.Errorf("the two dispatches are attempts %v, want 1 then 2 — each dispatch is its own numbered attempt", numbers)
	}
	// THE REVISION DID NOT MOVE: exactly one round at the gate that judges it, numbered 1.
	rounds := 0
	for _, r := range row.Reviews {
		if string(r.TaskID) == shapeDesignReviewTask {
			rounds++
			if r.Round != 1 {
				t.Errorf("the judging round is numbered %d; a variance retry is not a send-back and must not bump the revision", r.Round)
			}
		}
	}
	if rounds != 1 {
		t.Errorf("the judging gate opened %d rounds, want 1", rounds)
	}
	// And the activity still exits COMPLETED, with the later phases dispatched.
	if !shapeExitedCompleted(rig.cs, shapeDeploymentID) {
		t.Error("a retried-then-passed task must not stop the activity reaching its binary exit")
	}
}

// THE BUDGET IS SPENT: maxVarianceAttempts dispatches, then the activity records
// VarianceExhausted and the walk ends WITHOUT a workflow error — which is exactly what
// failVarianceExhausted did, and what keeps the pump's cascade alive past an activity that gave
// up. A returned error would fail the pump run blocked on this child.
func Test_ConstructionVariance_BudgetExhausted_RecordsTheTerminalAndEndsQuietly(t *testing.T) {
	rig := varianceRig(t, intervention.VarianceRetry, 0)
	rig.pipe.failTask[projectstate.TaskDetailedDesign] = true
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	shapeRequireCompleted(t, rig.env)

	row := rig.cs.execution(shapeDeploymentID)
	dispatched := 0
	for _, a := range row.Attempts {
		if a.Task == projectstate.TaskDetailedDesign {
			dispatched++
			if a.Outcome != projectstate.OutcomeFailed {
				t.Errorf("attempt %d at detailedDesign resolved %q, want failed", a.Attempt, a.Outcome)
			}
		}
	}
	if dispatched != maxVarianceAttempts {
		t.Errorf("the supervision budget allowed %d dispatches, want maxVarianceAttempts (%d) — the budget is checked at the "+
			"TOP of the loop, so the tenth failure escalates rather than the eleventh", dispatched, maxVarianceAttempts)
	}
	if row.FailureReason != projectstate.VarianceExhausted {
		t.Errorf("the activity's terminal reason is %v, want VarianceExhausted", row.FailureReason)
	}
	// The phase AFTER the failed one never ran: readyTasks never made it ready.
	for _, spec := range submittedSpecs(rig.pipe) {
		if spec.DispatchInputs["command"] == "deployment-construction" {
			t.Error("the phase after the exhausted one was dispatched anyway")
		}
	}
	if shapeExitedCompleted(rig.cs, shapeDeploymentID) {
		t.Error("an activity that exhausted its budget must NOT read Completed")
	}
}

// AN ESCALATION WAITS ON THE TASK'S OWN INBOX, and an operator's SKIP exits the activity Skipped
// — which the pump reads as Done, so the dependents unblock rather than stalling behind work
// nobody is going to do.
//
// The override is TaskID-addressed and reaches the escalated DISPATCH, not a gate: the shared
// operatorOverride channel would have handed it to whichever coroutine the SDK scheduled first.
func Test_ConstructionVariance_EscalatedThenOperatorSkip_ExitsTheActivitySkipped(t *testing.T) {
	rig := varianceRig(t, intervention.VarianceEscalate, 0)
	rig.pipe.failTask[projectstate.TaskDetailedDesign] = true
	rig.register(rig.env)
	rig.env.RegisterDelayedCallback(func() {
		rig.env.SignalWorkflow(signalOperatorOverride, operatorOverrideSignal{
			TaskID:   string(projectstate.TaskDetailedDesign),
			Override: ActivityOverride{Kind: OverrideSkip, Notes: "the provisioning spec is blocked on the vendor"},
		})
	}, time.Minute)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	shapeRequireCompleted(t, rig.env)

	row := rig.cs.execution(shapeDeploymentID)
	// ONE dispatch: the escalation happened on the first failure and the operator answered it.
	dispatched := 0
	for _, a := range row.Attempts {
		if a.Task == projectstate.TaskDetailedDesign {
			dispatched++
		}
	}
	if dispatched != 1 {
		t.Errorf("an Escalate directive must not retry on its own; got %d dispatches", dispatched)
	}
	if row.FailureReason != projectstate.FailureReasonUnknown {
		t.Errorf("a SKIP is not a failure; the terminal reason is %v, want none", row.FailureReason)
	}
	skipped := false
	rig.cs.mu.Lock()
	for _, e := range rig.cs.exited {
		if e.activityID == shapeDeploymentID && e.outcome == projectstate.ActivityOutcomeSkipped {
			skipped = true
		}
	}
	rig.cs.mu.Unlock()
	if !skipped {
		t.Error("the operator's Skip must record ActivityOutcomeSkipped — the pump reads it as Done and unblocks the dependents")
	}
	// The operator's steer is kept on the activity, exactly as executeOverride kept it — and
	// under the TAKEOVER gate, which is the gate an escalation's override answers.
	if n := countNotesAtGate(rig.cs, shapeDeploymentID, takeoverGateKey); n != 1 {
		t.Errorf("%d operator notes recorded at the takeover gate, want 1 — a skip with no recorded reason is a decision nobody can audit", n)
	}
}

// countNotesAtGate counts the operator notes the run recorded for one activity at one gate. The
// notes land through the constructionTransition facet (recordOperatorNote's verb), so they are
// read off the double's own call log rather than off the execution row.
func countNotesAtGate(ps *csFakeProjectState, activityID, gate string) int {
	ps.mu.Lock()
	defer ps.mu.Unlock()
	n := 0
	for _, c := range ps.notes {
		if c.activityID == activityID && c.note.Gate == gate {
			n++
		}
	}
	return n
}

// AN ESCALATION THAT NOBODY ANSWERS TIMES OUT AND RECORDS IT, rather than hanging forever on an
// override that never comes. The window is EscalationWaitTimeout; zero means wait-forever (the
// supervised EscalateEverything mode), which is why this case sets one.
func Test_ConstructionVariance_EscalationTimesOut_RecordsEscalationTimedOut(t *testing.T) {
	rig := varianceRig(t, intervention.VarianceEscalate, 10*time.Minute)
	rig.pipe.failTask[projectstate.TaskDetailedDesign] = true
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	shapeRequireCompleted(t, rig.env)
	if err := rig.env.GetWorkflowError(); err != nil {
		t.Fatalf("an unanswered escalation is a recorded terminal, not a workflow failure: %v", err)
	}
	row := rig.cs.execution(shapeDeploymentID)
	if row.FailureReason != projectstate.EscalationTimedOut {
		t.Fatalf("the activity's terminal reason is %v, want EscalationTimedOut", row.FailureReason)
	}
	if !strings.Contains(row.FailureDetail, "escalation timed out") || !strings.Contains(row.FailureDetail, "underlying") {
		t.Errorf("the timeout's detail must name itself AND the underlying failure; got %q", row.FailureDetail)
	}
}

// AN OVERRIDE STORM COALESCES TO ONE DECISION PER DISPATCH (fix round 1). Measured before the
// bound: 65 overrides to a live dispatch became 65 sequential recordOperatorNote writes from one
// coroutine while a sibling fork branch wrote its own attempts, and the per-activity CAS
// exhausted — an activity killed by an operator pressing a button repeatedly.
//
// The bound is also the honest reading: an override is a decision ABOUT the dispatch in flight,
// a second one says nothing new about it, and the next decision belongs to the next attempt.
func Test_ConstructionVariance_OverrideStormCoalescesToOneNotePerDispatch(t *testing.T) {
	const storm = deliveryTaskInboxCapacity / 2
	rig := varianceRig(t, intervention.VarianceRetry, 0)
	// One lagging poll on the task under the storm, so it is still in flight with an inbox it
	// reads when the storm lands.
	rig.pipe.laggingTask, rig.pipe.laggingPolls = projectstate.TaskDetailedDesign, 3
	rig.register(rig.env)
	rig.env.RegisterDelayedCallback(func() {
		for range storm {
			rig.env.SignalWorkflow(signalOperatorOverride, operatorOverrideSignal{
				TaskID:   string(projectstate.TaskDetailedDesign),
				Override: ActivityOverride{Kind: OverrideRetry, Notes: "steer"},
			})
		}
	}, 20*time.Second)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	// It COMPLETES. Without the bound this is where MutateConflictExhausted surfaced.
	shapeRequireCompleted(t, rig.env)

	notes := countNotesAtGate(rig.cs, shapeDeploymentID, string(projectstate.TaskDetailedDesign))
	if notes != 1 {
		t.Fatalf("%d operator notes were written for one dispatch's storm of %d overrides, want exactly 1 — "+
			"the rest are too late for the dispatch they were aimed at", notes, storm)
	}
}

// THE COMMAND FALLBACK AGREES WITH THE DATA, for every dispatch task of every lifecycle. The
// generic child passes the lifecycle task's own `command`; the retired flat walk re-derives it
// from the activity's classified pair. Two answers for one question is exactly the drift this
// repo has paid for before, so the equality is pinned rather than assumed — and when Task 13
// deletes the fallback this case is what proves nothing changed.
func Test_DispatchInputs_CommandFallbackAgreesWithTheLifecycleData(t *testing.T) {
	checked := 0
	for _, lc := range methodassets.Lifecycles() {
		typ, variant, ok := lifecyclePairForKey(lc.Type)
		if !ok {
			continue // the three design lifecycles carry no ActivityMethodPhase profile of their own
		}
		for _, task := range lc.Tasks {
			if task.Kind != methodassets.LifecycleTaskDispatch {
				continue
			}
			carried := dispatchInputsFor(pipelineSpec{Phase: task.Phase, Command: task.Command})
			derived := dispatchInputsFor(pipelineSpec{Phase: task.Phase, Type: typ, Variant: variant})
			if carried["command"] != task.Command {
				t.Errorf("%s/%s: the carried command is %q, want the task's own %q", lc.Type, task.ID, carried["command"], task.Command)
			}
			if derived["command"] != carried["command"] {
				t.Errorf("%s/%s: CommandFor answers %q where the lifecycle task says %q — the flat walk and the child would dispatch different commands",
					lc.Type, task.ID, derived["command"], carried["command"])
			}
			checked++
		}
	}
	if checked == 0 {
		t.Fatal("no dispatch task was checked, so this case is vacuous")
	}
}

// lifecyclePairForKey maps a lifecycle TYPE KEY back onto the (ActivityType, TestingVariant)
// pair CommandFor takes, for the eleven BUILD lifecycles. The three design keys are excluded by
// returning false: they are dispatched through the design arm, whose command parity Task 10
// pins separately.
//
// The pairs are enumerated rather than reflected, because LifecycleKeyFor is the production
// statement of the rule and this is its inverse — deriving one from the other would make the
// case agree with itself.
func lifecyclePairForKey(key string) (projectstate.ActivityType, projectstate.TestingVariant, bool) {
	types := []projectstate.ActivityType{
		projectstate.ActivityTypeService, projectstate.ActivityTypeFrontend, projectstate.ActivityTypeTesting,
		projectstate.ActivityTypeDeployment, projectstate.ActivityTypeDocumentation, projectstate.ActivityTypeUIDesign,
		projectstate.ActivityTypeIntegration, projectstate.ActivityTypeRequirements,
		projectstate.ActivityTypeArchitecture, projectstate.ActivityTypeProjectDesign,
	}
	variants := []projectstate.TestingVariant{
		projectstate.TestVariantPlan, projectstate.TestVariantHarness, projectstate.TestVariantPerf,
		projectstate.TestVariantSystemTest, projectstate.TestVariantQAProcess,
	}
	for _, typ := range types {
		for _, variant := range variants {
			if projectstate.LifecycleKeyFor(typ, variant) != key {
				continue
			}
			if isDesignLifecycle(typ) {
				return 0, 0, false
			}
			return typ, variant, true
		}
	}
	return 0, 0, false
}

// THE LAST PHASE'S GATE IS THE WALK'S FINAL TASK, for every lifecycle — which is what makes
// finalizeWalk the "last gate passed" site the plan asks the merge to hang off, without a second
// place that has to agree about when an activity is over (stage 4b1 Task 11).
//
// A platform release that added a task AFTER the final gate — a publish step, a notification —
// would break that identity, and the merge would then run while a task was still to come. It
// fails HERE rather than by merging a branch mid-walk.
func Test_LastPhaseGateIsTheWalksFinalTask(t *testing.T) {
	seen := 0
	for _, lc := range methodassets.Lifecycles() {
		if len(lc.Phases) == 0 || len(lc.Tasks) == 0 {
			t.Fatalf("lifecycle %q carries no phases or no tasks", lc.Type)
		}
		gate := lc.Phases[len(lc.Phases)-1].Gate
		if gate == "" {
			t.Fatalf("lifecycle %q: its last phase names no gate, so the walk has no final gate at all", lc.Type)
		}
		if last := lc.Tasks[len(lc.Tasks)-1].ID; last != gate {
			t.Errorf("lifecycle %q: the last phase's gate is %q but the last declared task is %q — finalizeWalk would run the merge before that task",
				lc.Type, gate, last)
		}
		for _, task := range lc.Tasks {
			if slices.Contains(task.DependsOn, gate) {
				t.Errorf("lifecycle %q: task %q depends on the final gate %q, so the walk continues past it", lc.Type, task.ID, gate)
			}
		}
		seen++
	}
	if seen != 14 {
		t.Fatalf("the pinned lifecycles are %d, not the 14 this case was measured against; re-measure before changing the number", seen)
	}
}

// THE EVIDENCE LADDER's three arms, and its ORDER. A construction attempt's evidence is the
// EPISODE (its output is a commit this store does not hold); a design or compute attempt's is
// the STAGED model; nothing cites nothing, because a ref nobody can follow is worse than an
// absent one.
func Test_AttemptEvidence_PrefersTheEpisodeThenTheStagedModel(t *testing.T) {
	for _, c := range []struct {
		name     string
		produced producedSubject
		wantKind projectstate.EvidenceKind
		wantRef  string
	}{
		{"construction cites its episode", producedSubject{EpisodeID: "ep-1"}, projectstate.EvidenceEpisode, "ep-1"},
		{"a design task cites its staged model", producedSubject{StagedRef: "C-x:missionDraft:Mission@v3"}, projectstate.EvidenceGit, "C-x:missionDraft:Mission@v3"},
		{"the episode outranks a staged ref", producedSubject{EpisodeID: "ep-2", StagedRef: "s"}, projectstate.EvidenceEpisode, "ep-2"},
		{"a judged review cites nothing", producedSubject{}, projectstate.EvidenceNone, ""},
	} {
		kind, ref := attemptEvidence(c.produced)
		if kind != c.wantKind || ref != c.wantRef {
			t.Errorf("%s: got (%v, %q), want (%v, %q)", c.name, kind, ref, c.wantKind, c.wantRef)
		}
	}
}

// A FAILED CRITIQUE JOB HOLDS THE GATE AND NEVER FAILS THE ACTIVITY (Task 10 review, F1).
//
// THE DEFECT IT PREVENTS, and it is unrecoverable rather than merely noisy: a red
// `mission-critique` run failed the child, the pump propagated the error with NO head-state
// record, the row already carried StartedAt so PumpWroteRow answered true, and
// isActivityDispatchable then answered false FOREVER — no gate to answer, no re-open path, and
// nothing in the ledger saying why. The retired rail routed all three critique faults to the
// human gate; only the missing-verdict one survived the first draft of the design arm.
//
// The preset is `vibes`, which is what makes the claim sharp: every OTHER gate in this walk is
// auto-passed by the policy, so a HUMAN deciding this one is the policy being overridden by the
// critic's silence rather than by the absence of a signal.
func Test_DesignWalk_FailedCritiqueJob_HoldsTheGateForAHumanAndFinishes(t *testing.T) {
	rig, pipe := designShapeRig(t, projectstate.ReviewPresetVibes)
	pipe.failCritique["mission"] = true
	rig.register(rig.env)
	rig.env.RegisterDelayedCallback(shapeApprove(rig.env, "missionReview"), 2*time.Minute)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID:  shapeProjectID,
		ActivityID: "requirements",
		Activity:   designActivity("requirements", projectstate.ActivityTypeRequirements),
	})
	// The walk FINISHES. A critique fault that failed the walk would stop here, and the
	// activity would be the unrecoverable row described above.
	shapeRequireCompleted(t, rig.env)

	row := rig.cs.execution("requirements")
	assertHeldForAHuman(t, latestRoundAt(row, "missionReview"), "went red")
	// The three siblings were auto-passed in the SAME walk, so the hold cannot be the preset's
	// doing.
	for _, task := range []string{"glossaryReview", "volatilitiesReview", "coreUseCasesReview"} {
		if r := latestRoundAt(row, task); r.DecidedBy != gateActorSystem {
			t.Errorf("round at %s was decided by %q; under vibes its siblings auto-pass", task, r.DecidedBy)
		}
	}
	// The activity still exits COMPLETED: the gate was answered, so the walk finished its work.
	if !shapeExitedCompleted(rig.cs, "requirements") {
		t.Error("the activity must reach its binary exit once the held gate is answered")
	}
}

// latestRoundAt is the highest-numbered round the ledger holds at a task, or the zero round.
func latestRoundAt(row projectstate.ActivityExecution, taskID string) projectstate.ReviewRound {
	var best projectstate.ReviewRound
	for _, r := range row.Reviews {
		if string(r.TaskID) == taskID && r.Round >= best.Round {
			best = r
		}
	}
	return best
}

// assertHeldForAHuman is the failed critique's whole claim: a HUMAN decided the round, and the
// critic's silence is on the record as an ABSTENTION carrying the venue's diagnostic — not as an
// approve, and not as a rejection nobody cast.
func assertHeldForAHuman(t *testing.T, round projectstate.ReviewRound, diagnostic string) {
	t.Helper()
	if round.RoundID == "" {
		t.Fatal("the mission gate opened no round at all, so nothing held")
	}
	if round.DecidedBy != gateActorOperator {
		t.Errorf("the mission round was decided by %q; a critic that did not answer must hold the gate for a HUMAN whatever the preset says", round.DecidedBy)
	}
	abstained := false
	for _, v := range round.Verdicts {
		if v.Verdict == projectstate.VerdictAbstain && strings.Contains(v.Summary, diagnostic) {
			abstained = true
		}
		if v.Verdict == projectstate.VerdictApprove && v.Actor != gateActorOperator {
			t.Errorf("a critique that never answered was recorded as an APPROVE by %q", v.Actor)
		}
	}
	if !abstained {
		t.Errorf("the critique fault must leave an ABSTAIN carrying the venue's diagnostic (%q); verdicts=%+v",
			diagnostic, round.Verdicts)
	}
}

// A REJECTED CRITIQUE DISPATCH HOLDS THE GATE TOO — the SECOND of the retired rail's three
// critique faults, and the one the first fix round left unpinned (Task 11 review, finding 2):
// reverting only this arm to a returned error left the whole package green, because every other
// case reached the gate through the terminal-failure arm instead.
//
// A refused dispatch is the same unrecoverable shape as a red run: nothing ran, so nothing judged,
// and failing the child strands the activity with a StartedAt row that isActivityDispatchable
// answers false for forever.
func Test_DesignWalk_RejectedCritiqueDispatch_HoldsTheGateForAHumanAndFinishes(t *testing.T) {
	rig, pipe := designShapeRig(t, projectstate.ReviewPresetVibes)
	pipe.rejectCritique["mission"] = true
	rig.register(rig.env)
	rig.env.RegisterDelayedCallback(shapeApprove(rig.env, "missionReview"), 2*time.Minute)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID:  shapeProjectID,
		ActivityID: "requirements",
		Activity:   designActivity("requirements", projectstate.ActivityTypeRequirements),
	})
	shapeRequireCompleted(t, rig.env)

	row := rig.cs.execution("requirements")
	assertHeldForAHuman(t, latestRoundAt(row, "missionReview"), "refused the critique dispatch")
	// The three siblings still auto-passed, so the hold is the refusal's doing and not the preset's.
	for _, task := range []string{"glossaryReview", "volatilitiesReview", "coreUseCasesReview"} {
		if r := latestRoundAt(row, task); r.DecidedBy != gateActorSystem {
			t.Errorf("round at %s was decided by %q; under vibes its siblings auto-pass", task, r.DecidedBy)
		}
	}
	if !shapeExitedCompleted(rig.cs, "requirements") {
		t.Error("the activity must reach its binary exit once the held gate is answered")
	}
}

// THE ACTUAL LOCAL COMBINATION, driven through the WALK (Task 10 review, minor (a)): a project
// whose repo resolves to the deterministic GitLocal ref while the construction PR rail is
// DORMANT. That pair is what a founder boot runs, and it is the whole reason designVenue is the
// child's one new wf.Repo reader — csWorkflows.gitEnabled additionally asks RailEnabled, which
// answers false here, so routing the design dispatch through it would send every local draft to
// the CENTRAL construction repo.
//
// It is asserted at WALK level and not at Manager level because the two are different claims:
// the Manager-level case pins what the resolver answers, this one pins what the DISPATCH does
// with the answer — the GitLocal owner/name decode, the design workflow file, and the activity
// branch the read-back then reads.
func Test_DesignWalk_LocalVenue_DispatchesIntoTheGitLocalRepo(t *testing.T) {
	rig, pipe := designShapeRigOn(t, projectstate.ReviewPresetVibes,
		func(p ProjectID) (sourcecontrol.RepoRef, bool) {
			return sourcecontrol.GitLocalRepoRefForProject(sourcecontrol.ProjectID(p)), true
		})
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID:  shapeProjectID,
		ActivityID: "requirements",
		Activity:   designActivity("requirements", projectstate.ActivityTypeRequirements),
	})
	shapeRequireCompleted(t, rig.env)

	wantOwner, wantName, err := sourcecontrol.RepoRefOwnerRepo(
		sourcecontrol.GitLocalRepoRefForProject(sourcecontrol.ProjectID(shapeProjectID)))
	if err != nil {
		t.Fatalf("the GitLocal ref must decode to an owner/name pair: %v", err)
	}
	designs := 0
	for _, spec := range pipe.submitted {
		if spec.DispatchInputs[dispatchInputCommand] == "" {
			continue // the local merge job, which carries no design command
		}
		designs++
		if spec.TargetRepo.Owner != wantOwner || spec.TargetRepo.Name != wantName {
			t.Errorf("dispatch target = %+v, want the GitLocal pair (%s, %s) — a zero target sends the draft to the CENTRAL construction repo",
				spec.TargetRepo, wantOwner, wantName)
		}
		if spec.WorkflowFile != designWorkflowFileName {
			t.Errorf("dispatch workflow file = %q, want %q", spec.WorkflowFile, designWorkflowFileName)
		}
		if got, want := spec.DispatchInputs[dispatchInputTargetBranch], activityBranchName("requirements"); got != want {
			t.Errorf("target_branch = %q, want %q — the read-back reads this branch", got, want)
		}
	}
	if designs == 0 {
		t.Fatal("no design job was dispatched, so this case is vacuous")
	}
	// The PR rail stayed dormant and the LOCAL MERGE is what lands the branch, which is the other
	// half of the asymmetry: gitOn is true (the status records fire) while gf.enabled is false.
	if n := mergeJobCount(pipe.submitted); n != 1 {
		t.Errorf("the local profile must dispatch exactly one merge job to land activity/requirements; got %d", n)
	}
	// And the four slots still committed, which they cannot be until that merge has landed them
	// on main.
	if len(rig.cs.committedSlots) != 4 {
		t.Errorf("committed %v, want the four Phase-1 kinds this activity produces", rig.cs.committedSlots)
	}
}

// ===========================================================================
// TASK 8 REVIEW CARRIES (stage 4b1 Task 10). Two cases the router's own three cases
// could not state: the RECEIVER's side of the overflow rule, and two human gates
// suspended at once on a fork.
// ===========================================================================

// THE RECEIVER DRAINS PAST THE INBOX'S CAPACITY. deliveryTaskInboxCapacity is 64 and the
// router never blocks, so message 65 and beyond land in ws.pending — and the ONLY thing that
// ever pulls them out is drainPending at the top of the receiver's loop. This sends
// comfortably more than capacity to a live gate and asserts every one was APPLIED.
//
// THE MUTATION IT EXISTS FOR: make drainPending return immediately and this goes RED at
// exactly (capacity) delivered statuses, because the overflow is stranded in a map nobody reads
// until closeInbox logs it as too-late. The complementary case,
// full-inbox-does-not-wedge-the-router, asserts the OTHER arm — a task that retires WITHOUT
// draining — so between them the overflow is pinned from both sides.
//
// IT COUNTS DELIVERIES, NOT LEDGER WRITES (re-pointed, stage 4b1 Task 12). The assertion used
// to read the store double's comment-status call log, which worked only because that double
// logged every call and applied none: the 76 comment ids here name comments no round holds,
// and the real store answers NotFound for each. The double now walks the thread as the store
// does, so the honest observable for "the receiver pulled every message through" is the
// ROUTER's own delivery hook — which is also strictly closer to the claim.
func Test_DeliveryGate_ReceiverDrainsPastTheInboxCapacity(t *testing.T) {
	const statuses = deliveryTaskInboxCapacity + 12
	var ts testsuite.WorkflowTestSuite
	env := ts.NewTestWorkflowEnvironment()
	ps := newFakeProjectStateWithPolicy(projectstate.ReviewPolicy{
		GatedPhasesByType: map[string][]projectstate.ActivityMethodPhase{
			"service": {projectstate.MethodPhaseDetailedDesign},
		},
	})
	rec := newShapeRecorder()
	ps.rec = rec
	pipe := &csFakePipeline{phase: PipelineSucceeded}
	deps := gateDeps(ps)
	deps.Review = review.NewReviewEngine()
	deps.SDPEngines = shapeSDPEngines()
	wf := csNewWorkflows(deps)
	wf.Deliveries = rec
	registerDeliveryActivity(env, wf, ps, pipe)

	// Every status rides in one delayed callback, so all of them are delivered to the router
	// before the gate has read any of them: the inbox takes 64, the rest queue in ws.pending, and
	// the receiver has to pull them through.
	env.RegisterDelayedCallback(func() {
		for i := range statuses {
			env.SignalWorkflow(signalSetCommentStatus, setCommentStatusSignal{
				TaskID:    shapeDesignReviewTask,
				CommentID: "c-" + strconv.Itoa(i),
				Status:    projectstate.ReviewCommentResolved,
			})
		}
	}, 5*time.Second)
	env.RegisterDelayedCallback(shapeApprove(env, shapeDesignReviewTask), 5*time.Minute)
	env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeServiceID, Activity: sampleActivity(),
	})
	shapeRequireCompleted(t, env)

	delivered := 0
	for _, d := range rec.outcome(nil, false).SignalsDelivered {
		if d == shapeDesignReviewTask+":"+routedKindStatus {
			delivered++
		}
	}
	if delivered != statuses {
		t.Fatalf("%d of %d comment-status signals reached the gate's inbox; the %d beyond the inbox's capacity of %d were "+
			"stranded in ws.pending, which means the receiver stopped draining",
			delivered, statuses, statuses-delivered, deliveryTaskInboxCapacity)
	}
}

// TWO HUMAN GATES SUSPENDED AT ONCE ON A FORK, each its OWN round and its OWN judged attempt.
// `service` forks at srsReview into detailedDesign→designReview and stp→stpReview, and a
// policy that gates BOTH phases puts two coroutines at two gates simultaneously — which the
// flat phase walk could not express at all, and which is the state the signal router exists
// for.
//
// THE CLAIM, and it is the one a single-gate case cannot make: deciding ONE leaves the OTHER
// awaiting. The walk must not finish on the first approve, the second gate's round must still
// be pending at that moment, and each round must carry its own id and its own subject.
func Test_DeliveryGate_TwoSimultaneousHumanGatesAreDecidedIndependently(t *testing.T) {
	var ts testsuite.WorkflowTestSuite
	env := ts.NewTestWorkflowEnvironment()
	ps := newFakeProjectStateWithPolicy(projectstate.ReviewPolicy{
		GatedPhasesByType: map[string][]projectstate.ActivityMethodPhase{
			"service": {projectstate.MethodPhaseDetailedDesign, projectstate.MethodPhaseTestPlan},
		},
	})
	rec := newShapeRecorder()
	pipe := &csFakePipeline{phase: PipelineSucceeded}
	deps := gateDeps(ps)
	deps.Review = review.NewReviewEngine()
	deps.SDPEngines = shapeSDPEngines()
	wf := csNewWorkflows(deps)
	wf.Deliveries = rec
	registerDeliveryActivity(env, wf, ps, pipe)

	// BOTH gates are open before either is answered, which is what makes this a fork case and
	// not two sequential gates. Measured at the moment designReview is approved.
	var stpPendingWhenDesignDecided bool
	env.RegisterDelayedCallback(func() {
		stpPendingWhenDesignDecided = roundIsPending(ps, shapeServiceID, shapeSTPTask+"Review")
		shapeApprove(env, shapeDesignReviewTask)()
	}, 2*time.Minute)
	env.RegisterDelayedCallback(shapeApprove(env, shapeSTPTask+"Review"), 4*time.Minute)
	env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeServiceID, Activity: sampleActivity(),
	})
	shapeRequireCompleted(t, env)

	if !stpPendingWhenDesignDecided {
		t.Fatal("stpReview's round was not PENDING when designReview was approved — the two gates were not " +
			"suspended at the same time, so this case is asserting two sequential gates instead of a fork")
	}
	row := ps.execution(shapeServiceID)
	decided := map[string]string{}
	for _, r := range row.Reviews {
		decided[string(r.TaskID)] = string(r.Outcome)
	}
	for _, task := range []string{shapeDesignReviewTask, shapeSTPTask + "Review"} {
		if decided[task] != string(projectstate.RoundPassed) {
			t.Errorf("round at %s is %q, want passed — each gate is answered on its own", task, decided[task])
		}
	}
	// Each round is its OWN id and its own judged attempt: a shared gateLedger would have made
	// one gate decide the other's round (Task 8's R8-7).
	ids := map[string]bool{}
	for _, r := range row.Reviews {
		if ids[r.RoundID] {
			t.Errorf("two rounds share the id %q", r.RoundID)
		}
		ids[r.RoundID] = true
	}
	if len(row.Reviews) < 2 {
		t.Fatalf("want at least the two forked gates' rounds, got %d", len(row.Reviews))
	}
}

// roundIsPending reports whether the named task's latest round is still awaiting a decision.
func roundIsPending(ps *csFakeProjectState, activityID, taskID string) bool {
	row := ps.execution(activityID)
	pending := false
	best := int64(-1)
	for _, r := range row.Reviews {
		if string(r.TaskID) != taskID || r.Round <= best {
			continue
		}
		best, pending = r.Round, r.Outcome == projectstate.RoundPending
	}
	return best >= 0 && pending
}

// ===========================================================================
// STAGE 4b1 TASK 12 — THE FIVE CONSTRUCTION WRITE PATHS (R2/GAP-6)
//
// Stage 4a answered five construction paths with a refusal naming 4b. These are the cases
// that say what each one does now, and they are deliberately split by MECHANISM: the three
// ledger writes are asserted on the ROW (the round ledger is the truth), and the two signals
// are asserted on the routed DELIVERY (a signal that reached nobody looks exactly like a
// verdict the walk declined).
// ===========================================================================

// task12RoundStore is a project holding the ledgerChain plan plus ONE execution row for `A`
// with one round on taskID — its thread as given, its outcome as given — and a passed attempt
// at the task that round judges, so judgedAttemptOfRound has something to cite.
func task12RoundStore(taskID, judged projectstate.MethodTask, outcome projectstate.ReviewRoundOutcome, thread []projectstate.ReviewComment) *csFakeProjectState {
	proj := ledgerChain()
	proj.ActivityExecution = map[string]projectstate.ActivityExecution{
		"A": {
			ActivityID: "A",
			StartedAt:  &testLedgerClock,
			Attempts: []projectstate.TaskAttempt{{
				AttemptID: projectstate.AttemptID("A", judged, 1), Task: judged, Attempt: 1,
				Outcome: projectstate.OutcomePassed,
			}},
			Reviews: []projectstate.ReviewRound{{
				RoundID: projectstate.AttemptID("A", taskID, 1), TaskID: taskID, Reviews: judged,
				Round: 1, Outcome: outcome, SubjectRef: projectstate.SubjectRef{Ref: "sha"},
				Thread: thread,
			}},
		},
	}
	return &csFakeProjectState{project: proj}
}

// task12Comment is one open comment on round 1, as a human reviewer's send-back leaves it.
func task12Comment(id, text string) projectstate.ReviewComment {
	return projectstate.ReviewComment{
		ID: id, Anchor: "$.ops[0]", Text: text, AuthorRole: reviewAuthorRole,
		Round: 1, Status: projectstate.ReviewCommentOpen,
	}
}

// task12Manager is the REAL twelve-op façade over one store and one client, so each case
// drives the op the SPA calls (SubmitReviewDecision / AskQuestions / DispatchActivityTask /
// AcknowledgeStaleBasis) and the rail routing is part of what is under test.
func task12Manager(c client.Client, ps *csFakeProjectState) *deliveryManager {
	full := fakeFullProjectState{ps}
	return newDeliveryManager(
		c, full, &artifactfake.FakeArtifactAccess{}, &fakeIntervention{}, &fakeReview{},
		estimation.NewEstimationEngine(), operationestimation.NewOperationEstimationEngine(),
		billing.NewBillingEngine(), csNewFakePipeline(), &stubRail{}, fakeConstructionTransition{ps}, ps,
		projectstate.NewDesignSessionAccess(full), csFakeActivityExecution{ps}, &recordingSignalBus{},
		&fakeEpisodes{}, 0, "", func(ProjectID) (sourcecontrol.RepoRef, bool) { return sourcecontrol.RepoRef(""), false }, "")
}

// task12NoSession is a client whose session Query answers NotFound for any id — an activity
// with no live execution, which is the state two of the five write paths are FOR.
func task12NoSession() *temporalmocks.Client {
	mc := &temporalmocks.Client{}
	mc.On("QueryWorkflow", mock.Anything, mock.Anything, "", querySessionState).
		Return(nil, serviceerror.NewNotFound("workflow not found for ID: p:activity:A"))
	return mc
}

// task12Round reads the one round back off the row.
func task12Round(t *testing.T, ps *csFakeProjectState) projectstate.ReviewRound {
	t.Helper()
	row := ps.execution("A")
	if len(row.Reviews) == 0 {
		t.Fatal("want the seeded round, got none")
	}
	return row.Reviews[0]
}

// LATEST-ROUND RESOLUTION, and the two things it must not get wrong: two artifact kinds
// sharing ONE gate task resolve to their OWN latest round (Task 3's join key), and a task with
// no round at all is a REFUSAL rather than an empty success.
func Test_LatestRoundFor_KeysOnTheGateAndRefusesWhenThereIsNone(t *testing.T) {
	sys, ops := projectstate.KindSystem, projectstate.KindOperationalConcepts
	row := projectstate.ActivityExecution{ActivityID: "architecture", Reviews: []projectstate.ReviewRound{
		{RoundID: "r1", TaskID: "architectureReview", ArtifactKind: &sys, Round: 1},
		{RoundID: "r2", TaskID: "architectureReview", ArtifactKind: &sys, Round: 2},
		{RoundID: "r3", TaskID: "architectureReview", ArtifactKind: &ops, Round: 1},
		{RoundID: "r4", TaskID: "codeReview", Round: 7},
	}}
	got, err := latestRoundFor(row, "architectureReview", &sys)
	if err != nil || got.RoundID != "r2" {
		t.Fatalf("System's latest round is r2; got %+v (%v)", got, err)
	}
	got, err = latestRoundFor(row, "architectureReview", &ops)
	if err != nil || got.RoundID != "r3" {
		t.Fatalf("operationalConcepts counts its OWN rounds: want r3, got %+v (%v)", got, err)
	}
	got, err = latestRoundFor(row, "codeReview", nil)
	if err != nil || got.RoundID != "r4" {
		t.Fatalf("a construction round keys on the task alone: want r4, got %+v (%v)", got, err)
	}
	if _, err := latestRoundFor(row, "designReview", nil); err == nil ||
		asConstructionError(t, err).Kind != fwmanager.FailedPrecondition {
		t.Fatalf("a task with no round must refuse, not answer an empty round; got %v", err)
	}
	// A KINDED round can never be found by a KINDLESS lookup, which is the whole point of the
	// join key: the design rails' three kinds share `architectureReview`.
	if _, err := latestRoundFor(row, "architectureReview", nil); err == nil {
		t.Fatal("a kindless lookup must not match a kinded round — that is how two kinds' rounds got confused")
	}
}

// WHICH TASK AN OVERRIDE STEERS, off the ledger alone (the override carries none).
func Test_EscalatedTaskOf_IsTheLastTaskWhoseLatestAttemptFailed(t *testing.T) {
	attempt := func(task projectstate.MethodTask, n int, out projectstate.TaskOutcome) projectstate.TaskAttempt {
		return projectstate.TaskAttempt{AttemptID: projectstate.AttemptID("A", task, n), Task: task, Attempt: n, Outcome: out}
	}
	cases := []struct {
		name     string
		attempts []projectstate.TaskAttempt
		want     projectstate.MethodTask
		ok       bool
	}{
		{"nothing dispatched", nil, "", false},
		{"everything passed", []projectstate.TaskAttempt{
			attempt("srs", 1, projectstate.OutcomePassed), attempt("detailedDesign", 1, projectstate.OutcomePassed),
		}, "", false},
		{"the one failed dispatch", []projectstate.TaskAttempt{
			attempt("srs", 1, projectstate.OutcomePassed), attempt("detailedDesign", 1, projectstate.OutcomeFailed),
		}, "detailedDesign", true},
		// A RETRY that passed supersedes its own failure: latestTaskOutcome reads the
		// highest-numbered attempt, so a task that recovered is not the escalated one.
		{"a task that recovered", []projectstate.TaskAttempt{
			attempt("detailedDesign", 1, projectstate.OutcomeFailed), attempt("detailedDesign", 2, projectstate.OutcomePassed),
		}, "", false},
		// A FORK can escalate two branches; the most recent dispatch is what the operator sees.
		{"two failed branches", []projectstate.TaskAttempt{
			attempt("stp", 1, projectstate.OutcomeFailed), attempt("detailedDesign", 1, projectstate.OutcomeFailed),
		}, "detailedDesign", true},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got, ok := escalatedTaskOf(projectstate.ActivityExecution{Attempts: c.attempts})
			if ok != c.ok || got != c.want {
				t.Fatalf("got (%q,%v), want (%q,%v)", got, ok, c.want, c.ok)
			}
		})
	}
}

// RESOLVE THEN REOPEN ROUND-TRIPS THROUGH THE LEDGER — the first of the five, and the first
// production caller of activityExecutionAccess.setReviewCommentStatus.
//
// It goes through deliveryManager.SubmitReviewDecision, which refused this with a
// ContractMisuse naming 4b, and the assertions are on the ROW: the status, the reopened bit,
// and that the round's own outcome was not touched (a comment's fate is not the round's).
func Test_ConstructionComments_ResolveThenReopenRoundTripsThroughTheLedger(t *testing.T) {
	ps := task12RoundStore("designReview", "detailedDesign", projectstate.RoundPending,
		[]projectstate.ReviewComment{task12Comment("r1c1", "name the failure")})
	// A SECOND, LATER ROUND on the same gate, deliberately: the comment being resolved lives on
	// round 1 while round 2 is the gate's latest, which is the ordinary shape at a redraft's gate
	// (a reviewer resolves what they filed last time). Resolving through latestRoundFor would
	// land the transition on round 2 and the store would answer NotFound for a comment that
	// plainly exists — so the COMMENT decides its round.
	func() {
		ps.mu.Lock()
		defer ps.mu.Unlock()
		row := ps.project.ActivityExecution["A"]
		row.Reviews = append(row.Reviews, projectstate.ReviewRound{
			RoundID: projectstate.AttemptID("A", "designReview", 2), TaskID: "designReview",
			Reviews: "detailedDesign", Round: 2, Outcome: projectstate.RoundPending,
			SubjectRef: projectstate.SubjectRef{Ref: "sha2"},
		})
		ps.project.ActivityExecution["A"] = row
	}()
	m := task12Manager(&fakeTemporalClient{session: awaitingAt("designReview")}, ps)
	resolve := ReviewDecisionInput{Decision: ReviewSetCommentStatus,
		CommentID: ptrTo("r1c1"), CommentStatus: ptrTo(projectstate.ReviewCommentResolved)}
	if err := m.SubmitReviewDecision(testCtx(), "p", "A", "designReview", resolve, nil); err != nil {
		t.Fatalf("a construction resolve must land: %v", err)
	}
	if got := task12Round(t, ps).Thread[0]; got.Status != projectstate.ReviewCommentResolved || got.Reopened {
		t.Fatalf("after the resolve: %+v, want resolved and not reopened", got)
	}
	reopen := ReviewDecisionInput{Decision: ReviewSetCommentStatus,
		CommentID: ptrTo("r1c1"), CommentStatus: ptrTo(projectstate.ReviewCommentOpen)}
	if err := m.SubmitReviewDecision(testCtx(), "p", "A", "designReview", reopen, nil); err != nil {
		t.Fatalf("a construction reopen must land: %v", err)
	}
	got := task12Round(t, ps)
	if got.Thread[0].Status != projectstate.ReviewCommentOpen || !got.Thread[0].Reopened {
		t.Fatalf("after the reopen: %+v, want open with the reopened bit set", got.Thread[0])
	}
	if got.Outcome != projectstate.RoundPending {
		t.Fatalf("a comment's status must not decide its round; outcome = %q", got.Outcome)
	}
	// AN UNKNOWN COMMENT IS NotFound, not a silent success: the round is resolved from the
	// COMMENT, so a comment nothing holds names no round.
	stray := ReviewDecisionInput{Decision: ReviewSetCommentStatus,
		CommentID: ptrTo("r9c9"), CommentStatus: ptrTo(projectstate.ReviewCommentResolved)}
	err := m.SubmitReviewDecision(testCtx(), "p", "A", "designReview", stray, nil)
	if e := asConstructionError(t, err); e.Kind != fwmanager.NotFound || !strings.Contains(e.Detail, "r9c9") {
		t.Fatalf("want NotFound naming the comment, got %s %q", e.Kind, e.Detail)
	}
	// AND THE EMPTINESS GUARD: `required` is presence-only, so "" arrives as a sent value.
	blank := ReviewDecisionInput{Decision: ReviewSetCommentStatus, CommentID: ptrTo(""), CommentStatus: ptrTo("resolved")}
	if e := asConstructionError(t, m.SubmitReviewDecision(testCtx(), "p", "A", "designReview", blank, nil)); e.Kind != fwmanager.ContractMisuse {
		t.Fatalf("want ContractMisuse for an empty commentId, got %s %q", e.Kind, e.Detail)
	}
}

// A WITHDRAW STAMPS RoundWithdrawn — Task 4's wire member earning its keep — and it is refused
// at a LIVE GATE, which is the design and not an omission: a round pulled out from under a
// child that is awaiting it strands the walk.
func Test_ConstructionWithdraw_StampsRoundWithdrawnAndRefusesAtALiveGate(t *testing.T) {
	withdraw := ReviewDecisionInput{Decision: ReviewWithdraw}
	// (a) A LIVE GATE at this very task: refused, and nothing is written.
	live := task12RoundStore("designReview", "detailedDesign", projectstate.RoundPending, nil)
	err := task12Manager(&fakeTemporalClient{session: awaitingAt("designReview")}, live).
		SubmitReviewDecision(testCtx(), "p", "A", "designReview", withdraw, nil)
	if e := asConstructionError(t, err); e.Kind != fwmanager.FailedPrecondition || !strings.Contains(e.Detail, "awaiting your decision") {
		t.Fatalf("want FailedPrecondition naming the live gate, got %s %q", e.Kind, e.Detail)
	}
	if got := task12Round(t, live); got.Outcome != projectstate.RoundPending {
		t.Fatalf("a refused withdraw must write nothing; outcome = %q", got.Outcome)
	}
	// (b) NO LIVE EXECUTION — the case the verb is for: the round is closed withdrawn, by the
	// operator rather than by the sweep.
	dead := task12RoundStore("designReview", "detailedDesign", projectstate.RoundPending, nil)
	mc := task12NoSession()
	if err := task12Manager(mc, dead).SubmitReviewDecision(testCtx(), "p", "A", "designReview", withdraw, nil); err != nil {
		t.Fatalf("a withdraw with no live judge must land: %v", err)
	}
	got := task12Round(t, dead)
	if got.Outcome != projectstate.RoundWithdrawn || got.DecidedBy != decidedByOperator {
		t.Fatalf("round = %q by %q, want withdrawn by the operator", got.Outcome, got.DecidedBy)
	}
	// (c) A DECIDED ROUND is refused: a withdraw pulls back a round nobody judged.
	if err := task12Manager(mc, dead).SubmitReviewDecision(testCtx(), "p", "A", "designReview", withdraw, nil); err == nil ||
		asConstructionError(t, err).Kind != fwmanager.FailedPrecondition {
		t.Fatalf("a second withdraw must refuse, got %v", err)
	}
	// (d) A TASK WITH NO ROUND refuses through the shared resolver rather than guessing.
	if err := task12Manager(mc, dead).SubmitReviewDecision(testCtx(), "p", "A", "codeReview", withdraw, nil); err == nil ||
		!strings.Contains(asConstructionError(t, err).Detail, "no review round") {
		t.Fatalf("want the resolver's refusal naming the missing round, got %v", err)
	}
}

// A QUESTION LANDS ON THE ROUND'S THREAD as ReviewComment.type = question (spec §5.3: an Ask
// is a comment, not a third mechanism), carried by an ABSTENTION — because asking is not
// judging — and a follow-up reaches the thread it names.
func Test_ConstructionAsk_LandsQuestionsOnTheRoundsThread(t *testing.T) {
	ps := task12RoundStore("designReview", "detailedDesign", projectstate.RoundPending, nil)
	m := task12Manager(&fakeTemporalClient{session: awaitingAt("designReview")}, ps)
	if err := m.AskQuestions(testCtx(), "p", "A", "designReview", projectstate.ReviewAddresseeArchitect,
		[]AnchoredComment{{JSONPath: "$.ops[0]", Text: "which failure mode does this cover?"}}); err != nil {
		t.Fatalf("a construction ask must land: %v", err)
	}
	got := task12Round(t, ps)
	if len(got.Thread) != 1 {
		t.Fatalf("want the one question on the round's thread, got %+v", got.Thread)
	}
	q := got.Thread[0]
	if q.Type != projectstate.ReviewCommentTypeQuestion || q.Addressee != projectstate.ReviewAddresseeArchitect ||
		q.Status != projectstate.ReviewCommentOpen {
		t.Fatalf("question = %+v, want an OPEN question addressed to the architect", q)
	}
	if len(got.Verdicts) != 1 || got.Verdicts[0].Verdict != projectstate.VerdictAbstain ||
		got.Verdicts[0].AttemptID != projectstate.AttemptID("A", "detailedDesign", 1) {
		t.Fatalf("verdicts = %+v, want ONE abstention citing the judged attempt", got.Verdicts)
	}
	if !strings.Contains(got.Verdicts[0].Summary, "1 question") {
		t.Fatalf("the verdict must say what was asked, got %q", got.Verdicts[0].Summary)
	}
	// A FOLLOW-UP on that thread is a reply, not a second question.
	if err := m.AskQuestions(testCtx(), "p", "A", "designReview", projectstate.ReviewAddresseeArchitect,
		[]AnchoredComment{{ReplyTo: q.ID, Text: "still unclear"}}); err != nil {
		t.Fatalf("a follow-up must land on the thread it names: %v", err)
	}
	after := task12Round(t, ps)
	if len(after.Thread) != 1 || len(after.Thread[0].Replies) != 1 {
		t.Fatalf("want one thread carrying one reply, got %+v", after.Thread)
	}
}

// THE THREE REFUSALS AN ASK OWES, each naming the datum it is missing.
func Test_ConstructionAsk_Refusals(t *testing.T) {
	// A replyTo naming nothing on this round is a hard refusal, never a fresh comment.
	open := task12RoundStore("designReview", "detailedDesign", projectstate.RoundPending, nil)
	if err := task12Manager(&fakeTemporalClient{}, open).AskQuestions(testCtx(), "p", "A", "designReview",
		projectstate.ReviewAddresseeArchitect, []AnchoredComment{{ReplyTo: "r9c9", Text: "hello?"}}); err == nil {
		t.Fatal("a replyTo naming no comment on the round must be refused")
	}
	// A DECIDED ROUND takes no questions: the store refuses a verdict on one, and the refusal is
	// stated at the façade with the sentence a reviewer can act on.
	decided := task12RoundStore("designReview", "detailedDesign", projectstate.RoundPassed, nil)
	err := task12Manager(&fakeTemporalClient{}, decided).AskQuestions(testCtx(), "p", "A", "designReview",
		projectstate.ReviewAddresseeArchitect, []AnchoredComment{{Text: "too late?"}})
	if e := asConstructionError(t, err); e.Kind != fwmanager.FailedPrecondition || !strings.Contains(e.Detail, "already decided") {
		t.Fatalf("want FailedPrecondition naming the decided round, got %s %q", e.Kind, e.Detail)
	}
	// A TASK WITH NO ROUND refuses through the shared resolver: a question against a task that
	// has never been reviewed is a caller error, not an empty success.
	err = task12Manager(&fakeTemporalClient{}, open).AskQuestions(testCtx(), "p", "A", "codeReview",
		projectstate.ReviewAddresseeArchitect, []AnchoredComment{{Text: "where?"}})
	if e := asConstructionError(t, err); e.Kind != fwmanager.FailedPrecondition || !strings.Contains(e.Detail, "no review round") {
		t.Fatalf("want the resolver's refusal, got %s %q", e.Kind, e.Detail)
	}
}

// A CONSTRUCTION ACTIVITY HAS NO STALE BASIS, and the refusal says so semantically instead of
// naming a stage that has arrived. Measured: no construction task in any of the fourteen
// lifecycles names an artifact kind, and StaleBasis is a field on a SLOT.
func Test_ConstructionAcknowledgeStaleBasis_RefusesForTheReasonAndNotForAStage(t *testing.T) {
	ps := task12RoundStore("designReview", "detailedDesign", projectstate.RoundPending, nil)
	err := task12Manager(&fakeTemporalClient{}, ps).
		AcknowledgeStaleBasis(testCtx(), "p", "A", "designReview", "reviewed — unaffected")
	e := asConstructionError(t, err)
	if e.Kind != fwmanager.FailedPrecondition || !strings.Contains(e.Detail, "no committed artifact slot") {
		t.Fatalf("want FailedPrecondition naming the missing datum, got %s %q", e.Kind, e.Detail)
	}
	if strings.Contains(e.Detail, "stage 4b") {
		t.Fatalf("the refusal must not name a stage that has arrived: %q", e.Detail)
	}
}

// THE TWO SIGNALS ADDRESS THE GENERIC CHILD, BY TASK. Both ops used to be unreachable: the
// decision named the retired child's id AND a phase vocabulary that rejects a task id, and the
// re-dispatch was a FailedPrecondition naming 4b.
func Test_Facade_ConstructionSignalsNameTheGenericChildAndItsTask(t *testing.T) {
	cases := []struct {
		name   string
		drive  func(m *deliveryManager) error
		signal string
		task   func(arg any) string
	}{
		{"approve", func(m *deliveryManager) error {
			return m.SubmitReviewDecision(testCtx(), "p", "A", "designReview", ReviewDecisionInput{Decision: ReviewApprove}, nil)
		}, signalTaskDecision, func(arg any) string { return arg.(taskDecisionSignal).TaskID }},
		{"send back", func(m *deliveryManager) error {
			return m.SubmitReviewDecision(testCtx(), "p", "A", "designReview", ReviewDecisionInput{Decision: ReviewReject},
				&ReviewFeedback{Notes: "tighten the error model"})
		}, signalTaskDecision, func(arg any) string { return arg.(taskDecisionSignal).TaskID }},
		{"re-dispatch", func(m *deliveryManager) error {
			_, err := m.DispatchActivityTask(testCtx(), "p", "A", "designReview", nil)
			return err
		}, lSignalRedraft, func(arg any) string { return arg.(redraftSignal).TaskID }},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			fc := &fakeTemporalClient{session: awaitingAt("designReview")}
			ps := task12RoundStore("designReview", "detailedDesign", projectstate.RoundPending, nil)
			if err := c.drive(task12Manager(fc, ps)); err != nil {
				t.Fatalf("%s: %v", c.name, err)
			}
			if want := deliveryActivityWorkflowID("p", "A"); fc.lastWorkflowID != want || fc.lastSignalName != c.signal {
				t.Fatalf("%s signalled %q/%q, want %q/%q", c.name, fc.lastWorkflowID, fc.lastSignalName, want, c.signal)
			}
			if got := c.task(fc.lastSignalArg); got != "designReview" {
				t.Fatalf("%s carried taskId %q — the router DROPS a signal that names no task", c.name, got)
			}
		})
	}
}

// AWAY FROM A GATE, BOTH SIGNALS REFUSE rather than presenting as success: a redraft delivered
// to a task that is mid-dispatch is re-offered when it retires (i.e. does nothing), and a task
// whose activity has exited has no inbox at all.
func Test_Facade_ConstructionSignalsRefuseAwayFromTheirGate(t *testing.T) {
	for name, view := range map[string]ConstructionSessionView{
		"a running pipeline":  {Stage: StagePipelineRunning},
		"another task's gate": awaitingAt("codeReview"),
		"an exited activity":  {Stage: StageExited},
	} {
		fc := &fakeTemporalClient{session: view}
		ps := task12RoundStore("designReview", "detailedDesign", projectstate.RoundPending, nil)
		m := task12Manager(fc, ps)
		if _, err := m.DispatchActivityTask(testCtx(), "p", "A", "designReview", nil); err == nil ||
			asConstructionError(t, err).Kind != fwmanager.FailedPrecondition {
			t.Errorf("%s: a re-dispatch must refuse, got %v", name, err)
		}
		if err := m.SubmitReviewDecision(testCtx(), "p", "A", "designReview",
			ReviewDecisionInput{Decision: ReviewApprove}, nil); err == nil ||
			asConstructionError(t, err).Kind != fwmanager.FailedPrecondition {
			t.Errorf("%s: a decision must refuse, got %v", name, err)
		}
		if fc.lastSignalName != "" {
			t.Errorf("%s: a refused op must not signal, got %q", name, fc.lastSignalName)
		}
	}
	// A DORMANT ACTIVITY (no live execution at all) is named as such, not as a transport fault.
	mc := task12NoSession()
	_, err := task12Manager(mc, task12RoundStore("designReview", "detailedDesign", projectstate.RoundPending, nil)).
		DispatchActivityTask(testCtx(), "p", "A", "designReview", nil)
	if e := asConstructionError(t, err); e.Kind != fwmanager.NotFound {
		t.Fatalf("want the session read's NotFound for a dormant activity, got %s %q", e.Kind, e.Detail)
	}
}

// THE RE-DISPATCH REACHES THE NAMED TASK'S INBOX, end to end from the façade through the
// router into the gate — asserted on the DELIVERY and not on the walk's terminal, because a
// redraft that reached nobody looks identical to one the operator never sent: the gate simply
// keeps awaiting its decision either way (controller ruling 6).
//
// WHAT THE CHILD THEN DOES, stated because the brief's phrasing is ambiguous: the redraft arm
// WITHDRAWS the round (nobody judged it) and re-opens the judged pair at revision n+1, which is
// the send-back's own mechanism asked for directly. It is NOT "a new attempt at the same
// revision" — that shape belongs to the variance retry (Task 11), and re-using the revision
// here would re-open a round id the ledger already holds as pending.
func Test_Facade_RedraftReachesTheNamedTasksInboxAndReopensThePair(t *testing.T) {
	var ts testsuite.WorkflowTestSuite
	env := ts.NewTestWorkflowEnvironment()
	ps := newFakeProjectStateWithPolicy(projectstate.ReviewPolicy{
		GatedPhasesByType: map[string][]projectstate.ActivityMethodPhase{
			"service": {projectstate.MethodPhaseDetailedDesign},
		},
	})
	// The façade reads the COMMITTED PLAN to resolve the activity's rail, so the store carries
	// the activity the child is running. Everything else about this store is the gate rig's.
	plan := projWithActivities(
		[]projectstate.ActivityItem{{Name: shapeServiceID, Title: shapeServiceID, WorkerClass: "junior-developer", Coding: true, ComponentID: "todo-list-manager"}},
		[]projectstate.NetworkDependency{{Activity: shapeServiceID, DependsOn: []string{}}})
	ps.project.Network, ps.project.ActivityList, ps.project.SystemDesign = plan.Network, plan.ActivityList, plan.SystemDesign
	rec := newShapeRecorder()
	ps.rec = rec
	pipe := &csFakePipeline{phase: PipelineSucceeded, rec: rec}
	deps := gateDeps(ps)
	deps.Review = review.NewReviewEngine()
	deps.SDPEngines = shapeSDPEngines()
	wf := csNewWorkflows(deps)
	wf.Deliveries = rec
	registerDeliveryActivity(env, wf, ps, pipe)
	env.SetStartWorkflowOptions(client.StartWorkflowOptions{ID: deliveryActivityWorkflowID("p", shapeServiceID)})
	m := task12Manager(&envSignalClient{env: env}, ps)

	env.RegisterDelayedCallback(func() {
		if _, err := m.DispatchActivityTask(testCtx(), "p", ActivityID(shapeServiceID), shapeDesignReviewTask,
			&ReviewFeedback{Notes: "run it again against the amended contract"}); err != nil {
			t.Errorf("the re-dispatch must be accepted at its own gate: %v", err)
		}
	}, time.Minute)
	env.RegisterDelayedCallback(shapeApprove(env, shapeDesignReviewTask), 5*time.Minute)
	env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: "p", ActivityID: ActivityID(shapeServiceID), Activity: sampleActivity(),
	})
	shapeRequireCompleted(t, env)

	want := shapeDesignReviewTask + ":" + routedKindRedraft
	if got := rec.outcome(nil, false); !slices.Contains(got.SignalsDelivered, want) {
		t.Fatalf("the façade's redraft must reach the NAMED task's inbox (%s); SignalsDelivered=%v", want, got.SignalsDelivered)
	}
	row := ps.execution(shapeServiceID)
	rounds := map[int64]projectstate.ReviewRoundOutcome{}
	for _, r := range row.Reviews {
		if string(r.TaskID) == shapeDesignReviewTask {
			rounds[r.Round] = r.Outcome
		}
	}
	if rounds[1] != projectstate.RoundWithdrawn {
		t.Errorf("round 1 must be WITHDRAWN — nobody judged it, the operator asked for another draft; got %q", rounds[1])
	}
	if rounds[2] != projectstate.RoundPassed {
		t.Errorf("the redraft's own round 2 must carry the approve that followed; got %q", rounds[2])
	}
	dispatches := 0
	for _, a := range row.Attempts {
		if a.Task == projectstate.TaskDetailedDesign {
			dispatches++
		}
	}
	if dispatches != 2 {
		t.Errorf("the judged task must be re-dispatched exactly once more; got %d attempts", dispatches)
	}
}

// A REFUSED SUBMIT RESOLVES ITS ATTEMPT (Task-11 round-2 defect D1). The attempt is opened
// PENDING before the job it describes, so a dispatch that cannot be submitted must resolve it
// FAILED: the pair's own rule is that an attempt left pending is indistinguishable from a run
// that died, and the caller reports AttemptRecorded, so nothing downstream would have resolved
// it either.
func Test_ConstructionDispatch_ARefusedSubmitResolvesItsAttemptFailed(t *testing.T) {
	rig := varianceRig(t, intervention.VarianceRetry, 0)
	rig.pipe.refuseSubmitInPhase = map[string]bool{string(projectstate.MethodPhaseDetailedDesign): true}
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	// A rejected dispatch is a WIRING fault, not a variance in the work: it fails the walk,
	// which is the retired rail's behaviour too.
	if err := rig.env.GetWorkflowError(); err == nil {
		t.Fatal("a refused submit must fail the walk — a dispatch that cannot be submitted is a wiring fault")
	}
	row := rig.cs.execution(shapeDeploymentID)
	attempts := 0
	for _, a := range row.Attempts {
		if a.Task != projectstate.TaskDetailedDesign {
			continue
		}
		attempts++
		if a.Outcome != projectstate.OutcomeFailed {
			t.Errorf("attempt %d is %q; a refused submit leaves NO pending attempt behind", a.Attempt, a.Outcome)
		}
	}
	if attempts != 1 {
		t.Fatalf("want the one opened attempt on the ledger, got %d", attempts)
	}
}

// ===========================================================================
// STAGE 4b1 TASK 12, FIX ROUND 1 — A TERMINAL ACTIVITY CAN BE RE-OPENED
//
// Terminal was terminal and nothing could undo it, so a failed walk, a spent variance budget
// and an operator's own Skip each left an activity NOTHING could re-run. A REQUEUE note now
// re-arms the row (reopenTerminalRow), and these cases pin the three things that has to mean:
// the pump selects the activity again, the walk re-dispatches ONLY what did not pass, and a
// row that has not exited is refused.
// ===========================================================================

// reopenOverride is what the operator sends. Every override KIND reaches the re-open arm — an
// operator looking at a finished activity is asking for it to run again whatever word the SPA
// put on the button — so the case uses the one that says it most plainly.
func reopenOverride(notes string) ActivityOverride {
	return ActivityOverride{Kind: OverrideRetry, Notes: notes}
}

// designPlanStore merges the derived plan's fixed design prefix into a store the design rig
// built, so the PUMP's own predicates can be asked about the activity the child just ran.
func designPlanStore(ps *csFakeProjectState) {
	plan := planWithDesignPrefix()
	ps.mu.Lock()
	defer ps.mu.Unlock()
	ps.project.Network, ps.project.ActivityList, ps.project.SystemDesign = plan.Network, plan.ActivityList, plan.SystemDesign
}

// dispatchableNow asks the PUMP's own eligibility about one activity, off the store's row map.
func dispatchableNow(t *testing.T, ps *csFakeProjectState, activityID string) bool {
	t.Helper()
	ps.mu.Lock()
	proj := ps.project
	ps.mu.Unlock()
	item, ok := committedActivityItem(proj, activityID)
	if !ok {
		t.Fatalf("the committed plan must hold %s for the pump to reason about it", activityID)
	}
	return isActivityDispatchable(activityID, item, proj.ActivityExecution)
}

// A FAILED DESIGN WALK IS RE-ARMED AND RE-DISPATCHES ONLY WHAT DID NOT PASS — the whole point of
// re-arming a row rather than re-planning the activity. `mission` passed and is NOT drafted
// again; `glossary`, whose draft job died, is.
func Test_Reopen_AFailedDesignWalkReDispatchesOnlyWhatDidNotPass(t *testing.T) {
	rig, _ := designShapeRig(t, projectstate.ReviewPresetVibes)
	designPlanStore(rig.cs)
	pipe := newDesignJobPipeline(rig.cs, rig.rec)
	pipe.failDraft["glossary"] = true
	rig.pipe = nil
	rig.register = func(env *testsuite.TestWorkflowEnvironment) { registerDeliveryActivity(env, rig.cswf, rig.cs, pipe) }
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: "requirements",
		Activity: designActivity("requirements", projectstate.ActivityTypeRequirements),
	})
	if rig.env.GetWorkflowError() == nil {
		t.Fatal("a terminal draft failure must fail the walk — this case needs the failure it re-opens")
	}
	if row := rig.cs.execution("requirements"); row.FailureReason == projectstate.FailureReasonUnknown {
		t.Fatalf("the failed walk must leave a terminal on the row, got %+v", row)
	}
	// THE STATE THE OPERATOR IS LOOKING AT: a failed activity the pump will never select again.
	if dispatchableNow(t, rig.cs, "requirements") {
		t.Fatal("a terminal row must NOT be dispatchable — the case's premise is that nothing re-runs it")
	}

	m := newFacadeConstructionManager(task12NoSession(), rig.cs)
	if err := m.OverrideActivity(testCtx(), shapeProjectID, "requirements",
		reopenOverride("the glossary venue is back; run it again")); err != nil {
		t.Fatalf("re-opening a terminal activity with no live child must be accepted: %v", err)
	}
	assertReArmed(t, rig.cs, "requirements")

	// THE RE-RUN, on a second environment over the SAME ledger.
	pipe.failDraft["glossary"] = false
	before := pipe.drafts["mission"]
	next := rig.reenter(t)
	next.register = func(env *testsuite.TestWorkflowEnvironment) { registerDeliveryActivity(env, next.cswf, next.cs, pipe) }
	next.register(next.env)
	next.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: "requirements",
		Activity: designActivity("requirements", projectstate.ActivityTypeRequirements),
	})
	shapeRequireCompleted(t, next.env)
	if pipe.drafts["mission"] != before {
		t.Errorf("mission passed before the failure and must NOT be drafted again; drafts %d → %d", before, pipe.drafts["mission"])
	}
	if pipe.drafts["glossary"] < 2 {
		t.Errorf("glossary is what did not pass and must be re-dispatched; drafts = %d", pipe.drafts["glossary"])
	}
}

// A CONSTRUCTION GIVE-UP IS RE-ARMED TOO. The operator's own Skip is the terminal here — the
// hardest case, because nothing failed: they decided to stop, and then changed their mind.
func Test_Reopen_AConstructionGiveUpIsReArmed(t *testing.T) {
	rig := varianceRig(t, intervention.VarianceEscalate, 0)
	rig.pipe.failTask[projectstate.TaskDetailedDesign] = true
	rig.register(rig.env)
	rig.env.RegisterDelayedCallback(func() {
		rig.env.SignalWorkflow(signalOperatorOverride, operatorOverrideSignal{
			TaskID:   string(projectstate.TaskDetailedDesign),
			Override: ActivityOverride{Kind: OverrideSkip, Notes: "blocked on the vendor"},
		})
	}, time.Minute)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: shapeDeploymentID, Activity: shapeDeploymentActivity(),
	})
	shapeRequireCompleted(t, rig.env)
	item := projectstate.ActivityItem{Name: shapeDeploymentID, WorkerClass: "junior-developer", Coding: true}
	rows := map[string]projectstate.ActivityExecution{shapeDeploymentID: rig.cs.execution(shapeDeploymentID)}
	if isActivityDispatchable(shapeDeploymentID, item, rows) {
		t.Fatal("a skipped activity is an EXIT — the pump must not select it until it is re-opened")
	}
	if err := newFacadeConstructionManager(task12NoSession(), rig.cs).
		OverrideActivity(testCtx(), shapeProjectID, ActivityID(shapeDeploymentID),
			reopenOverride("the vendor unblocked us")); err != nil {
		t.Fatalf("re-opening a skipped activity must be accepted: %v", err)
	}
	rows[shapeDeploymentID] = rig.cs.execution(shapeDeploymentID)
	if !isActivityDispatchable(shapeDeploymentID, item, rows) {
		t.Fatal("after the re-open the pump must select it again")
	}
}

// A ROW THAT HAS NOT EXITED IS REFUSED, and the refusal comes from the STORE's rule rather than
// from a façade guess: re-arming a live row would hand a second child the row this one is writing.
func Test_Reopen_RefusesAnActivityThatHasNotExited(t *testing.T) {
	running := &csFakeProjectState{project: projectstate.Project{
		Phase: projectstate.PhaseConstruction,
		ActivityExecution: map[string]projectstate.ActivityExecution{
			"A": {ActivityID: "A", StartedAt: &testLedgerClock},
		},
	}}
	err := newFacadeConstructionManager(task12NoSession(), running).
		OverrideActivity(testCtx(), "p", "A", reopenOverride("run it again"))
	// FAILED PRECONDITION, because the store answers Conflict (Task 12 round 3, minor (e)): the
	// refusal is state-dependent — the same requeue is legal the moment the activity exits — and
	// the façade maps a store Conflict to the operator's FailedPrecondition exactly as it does for
	// this facet's other two terminality refusals.
	if e := asConstructionError(t, err); e.Kind != fwmanager.FailedPrecondition || !strings.Contains(e.Detail, "not finished") {
		t.Fatalf("want FailedPrecondition naming the live row, got %s %q", e.Kind, e.Detail)
	}
	if row := running.execution("A"); row.StartedAt == nil {
		t.Fatal("a refused re-open must move NOTHING — the row was re-armed anyway")
	}
	// AND AN ACTIVITY WITH NO ROW AT ALL is NotFound, not a silent success.
	empty := &csFakeProjectState{project: projectstate.Project{Phase: projectstate.PhaseConstruction}}
	if e := asConstructionError(t, newFacadeConstructionManager(task12NoSession(), empty).
		OverrideActivity(testCtx(), "p", "A", reopenOverride("run it again"))); e.Kind != fwmanager.NotFound {
		t.Fatalf("want NotFound for an activity with no execution row, got %s %q", e.Kind, e.Detail)
	}
}

// THE POST-EXIT COMMIT WINDOW SELF-HEALS THROUGH A RE-OPEN (controller carry 4). The walk
// records the activity's binary exit and THEN commits its slots, so a failed commit leaves a
// Completed activity with an AwaitingReview slot. A re-open plus a re-run repairs it — and it
// only does so because commitDesignArtifacts' no-work arm now asks which slots are still
// uncommitted instead of skipping (the arm that made this state permanent).
func Test_Reopen_HealsTheDesignSlotCommitWindow(t *testing.T) {
	rig, _ := designShapeRig(t, projectstate.ReviewPresetVibes)
	designPlanStore(rig.cs)
	rig.cs.mu.Lock()
	rig.cs.commitFailKinds = map[projectstate.ArtifactKind]bool{projectstate.KindCoreUseCases: true}
	rig.cs.mu.Unlock()
	pipe := newDesignJobPipeline(rig.cs, rig.rec)
	rig.pipe = nil
	rig.register = func(env *testsuite.TestWorkflowEnvironment) { registerDeliveryActivity(env, rig.cswf, rig.cs, pipe) }
	rig.register(rig.env)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: "requirements",
		Activity: designActivity("requirements", projectstate.ActivityTypeRequirements),
	})
	if rig.env.GetWorkflowError() == nil {
		t.Fatal("a failed slot commit must surface as the walk's error; this case needs the window it repairs")
	}
	// THE WINDOW ITSELF: the activity EXITED (the binary exit is recorded before the commits)
	// while one slot it produced is still not committed.
	row := rig.cs.execution("requirements")
	if row.CompletedAt == nil {
		t.Fatalf("the window's premise is a recorded exit, got %+v", row)
	}
	if slotStatusOf(rig.cs, projectstate.KindCoreUseCases) == projectstate.ReviewCommitted {
		t.Fatal("the case needs coreUseCases UNCOMMITTED — the commit double did not refuse")
	}

	if err := newFacadeConstructionManager(task12NoSession(), rig.cs).
		OverrideActivity(testCtx(), shapeProjectID, "requirements", reopenOverride("the commit faulted; land the slots")); err != nil {
		t.Fatalf("re-opening the activity must be accepted: %v", err)
	}
	rig.cs.mu.Lock()
	rig.cs.commitFailKinds = nil
	advancedBefore := rig.cs.advanced
	rig.cs.mu.Unlock()

	// THE PUMP MUST NOW SELECT IT, and this assertion is the one the window needed: the
	// re-open clears the head facts and KEEPS the ledger, so isActivityDispatchable's ledger
	// derivation resolves Done for a walk whose every gate passed. Before Task 12 round 3 this
	// test passed only because it calls ExecuteWorkflow directly — in production the pump
	// refused the row and the repair never ran, however many times the operator pressed the
	// button. Asserted through the real predicate, over the real row.
	if !dispatchableNow(t, rig.cs, "requirements") {
		t.Fatal("a re-opened activity must be dispatchable; the repair below only runs because the PUMP selects it")
	}

	next := rig.reenter(t)
	next.register = func(env *testsuite.TestWorkflowEnvironment) { registerDeliveryActivity(env, next.cswf, next.cs, pipe) }
	next.register(next.env)
	next.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: shapeProjectID, ActivityID: "requirements",
		Activity: designActivity("requirements", projectstate.ActivityTypeRequirements),
	})
	shapeRequireCompleted(t, next.env)
	if got := slotStatusOf(rig.cs, projectstate.KindCoreUseCases); got != projectstate.ReviewCommitted {
		t.Fatalf("the re-run must land the slot the failed commit left behind; status = %v", got)
	}
	// AND IT RE-DRAFTED NOTHING: every task seeded passed off the ledger, so the repair is a
	// commit pass and not four fresh design jobs.
	for _, kind := range []string{"mission", "glossary", "volatilities", "coreUseCases"} {
		if pipe.drafts[kind] != 1 {
			t.Errorf("%s drafted %d times across both runs, want 1 — the repair must not re-draft", kind, pipe.drafts[kind])
		}
	}
	rig.cs.mu.Lock()
	advancedAfter := rig.cs.advanced
	rig.cs.mu.Unlock()
	if advancedAfter > advancedBefore+1 {
		t.Errorf("the phase advanced %d times across the repair, want at most one more", advancedAfter-advancedBefore)
	}
}

// slotStatusOf reads one slot's review status off the store.
func slotStatusOf(ps *csFakeProjectState, kind projectstate.ArtifactKind) projectstate.ArtifactReviewStatus {
	ps.mu.Lock()
	defer ps.mu.Unlock()
	if slot := designSlotPtr(&ps.project, kind); slot != nil {
		return slot.Status
	}
	return projectstate.ArtifactReviewStatus(0)
}

// assertReArmed is the re-opened row's whole shape, Manager-side: the head facts cleared, the
// ledger kept, the pump selecting it again, and exactly ONE requeue note carrying the reason.
func assertReArmed(t *testing.T, ps *csFakeProjectState, activityID string) {
	t.Helper()
	row := ps.execution(activityID)
	if row.StartedAt != nil || row.CompletedAt != nil || row.FailureReason != projectstate.FailureReasonUnknown {
		t.Fatalf("the re-open must clear exactly the four head facts, got %+v", row)
	}
	if len(row.Attempts) == 0 {
		t.Fatal("the re-open must PRESERVE the attempt ledger — it is what the re-run seeds from")
	}
	if !dispatchableNow(t, ps, activityID) {
		t.Fatal("after the re-open the pump must select the activity again (its ledger-partial arm)")
	}
	notes := 0
	for _, n := range row.OperatorNotes {
		if n.Kind == projectstate.NoteRequeue && n.Gate == reopenGateKey {
			notes++
		}
	}
	if notes != 1 {
		t.Fatalf("the re-open must leave exactly ONE requeue note — the operator's own reason; got %d", notes)
	}
}

// ===========================================================================
// STAGE 4b1 TASK 12, FIX ROUND 2 — AN OPEN REVIEW COMMENT GATES THE GENERIC CHILD
//
// The retired rail guarded twice: the vibes autogate made "no open comments" a precondition of
// the synthesized approve, and a human approve was refused Manager-side over open threads and
// re-checked in the child. The generic child guarded NOWHERE — OpenReviewCommentIDs had zero
// callers in deliveryactivity.go — so a comment filed on a round while its critic was still
// running was buried by the pass that followed.
// ===========================================================================

// openCommentRig is a vibes-gated service walk whose `designReview` round gets a comment filed on
// it while the gate is being decided. `vibes` means the engine asks for NO human, so every case
// here is about what the AUTOGATE does with a comment it did not expect.
func openCommentRig(t *testing.T) (*shapeRig, *deliveryManager) {
	t.Helper()
	var ts testsuite.WorkflowTestSuite
	rig := &shapeRig{env: ts.NewTestWorkflowEnvironment(), rec: newShapeRecorder()}
	preset := projectstate.ReviewPresetVibes
	ps := newFakeProjectStateWithPolicy(projectstate.ReviewPolicy{Preset: &preset})
	ps.rec = rig.rec
	plan := projWithActivities(
		[]projectstate.ActivityItem{{Name: shapeServiceID, Title: shapeServiceID, WorkerClass: "junior-developer", Coding: true, ComponentID: "todo-list-manager"}},
		[]projectstate.NetworkDependency{{Activity: shapeServiceID, DependsOn: []string{}}})
	ps.project.Network, ps.project.ActivityList, ps.project.SystemDesign = plan.Network, plan.ActivityList, plan.SystemDesign
	pipe := &csFakePipeline{phase: PipelineSucceeded, rec: rig.rec, failTask: map[projectstate.MethodTask]bool{}, failTaskFirst: map[projectstate.MethodTask]int{}}
	deps := gateDeps(ps)
	deps.Review = review.NewReviewEngine()
	deps.SDPEngines = shapeSDPEngines()
	wf := csNewWorkflows(deps)
	wf.Deliveries = rig.rec
	rig.cs, rig.cswf, rig.pipe = ps, wf, pipe
	rig.register = func(env *testsuite.TestWorkflowEnvironment) { registerDeliveryActivity(env, wf, ps, pipe) }
	rig.register(rig.env)
	rig.env.SetStartWorkflowOptions(client.StartWorkflowOptions{ID: deliveryActivityWorkflowID("p", shapeServiceID)})
	return rig, task12Manager(&envSignalClient{env: rig.env}, ps)
}

// UNDER VIBES, AN OPEN COMMENT HOLDS THE GATE FOR A HUMAN — and resolving it releases the gate
// WITHOUT one, because the policy never wanted a human in the first place. That second half is
// what makes the Manager's comment-status MIRROR signal load-bearing: the write is the Manager's,
// and only the child can re-evaluate the hold.
func Test_AutoGate_AnOpenCommentHoldsTheGateAndAResolveReleasesIt(t *testing.T) {
	rig, m := openCommentRig(t)
	// A QUESTION lands on srsReview's round in the window the critic occupies in production — the
	// double puts it there (seedCommentOnRound), because a test environment has no such window.
	// A question is the strictest case on purpose: it does NOT block a human approve
	// (ReviewCommentBlocksApprove), and it MUST still hold an autogate, because an autogate has no
	// human to surface it to.
	question := task12Comment("r1c1", "which failure mode does this cover?")
	question.Type = projectstate.ReviewCommentTypeQuestion
	question.Addressee = projectstate.ReviewAddresseeArchitect
	rig.cs.mu.Lock()
	rig.cs.seedCommentOnRound = map[string]projectstate.ReviewComment{"srsReview": question}
	rig.cs.mu.Unlock()
	rig.env.RegisterDelayedCallback(func() {
		// The gate is HELD: under vibes it would otherwise have passed itself already.
		if !roundIsPending(rig.cs, shapeServiceID, "srsReview") {
			t.Error("an open comment must HOLD the autogate — the round was decided with it open")
		}
		if err := m.SubmitReviewDecision(testCtx(), "p", ActivityID(shapeServiceID), "srsReview",
			ReviewDecisionInput{Decision: ReviewSetCommentStatus, CommentID: ptrTo("r1c1"),
				CommentStatus: ptrTo(projectstate.ReviewCommentResolved)}, nil); err != nil {
			t.Errorf("the resolve must land: %v", err)
		}
	}, 30*time.Second)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: "p", ActivityID: ActivityID(shapeServiceID), Activity: sampleActivity(),
	})
	shapeRequireCompleted(t, rig.env)
	if err := rig.env.GetWorkflowError(); err != nil {
		t.Fatalf("the walk must finish once the comment is resolved: %v", err)
	}
	// THE MIRROR REACHED THE ROUND'S OWN TASK — not the task the caller happened to name.
	want := "srsReview:" + routedKindStatus
	if got := rig.rec.outcome(nil, false); !slices.Contains(got.SignalsDelivered, want) {
		t.Fatalf("the comment-status mirror must reach the round's task (%s); SignalsDelivered=%v", want, got.SignalsDelivered)
	}
	// And the released gate is the AUTOGATE's own pass: decided by the system, not by an operator.
	row := rig.cs.execution(shapeServiceID)
	for _, r := range row.Reviews {
		if string(r.TaskID) != "srsReview" {
			continue
		}
		if r.Outcome != projectstate.RoundPassed || r.DecidedBy != gateActorSystem {
			t.Fatalf("the released autogate must pass as the SYSTEM (the policy asked for no human); round = %+v", r)
		}
	}
}

// A HUMAN APPROVE IS REFUSED OVER AN OPEN CHANGE REQUEST, in the design rail's own words — and
// the child re-checks, because the decision reaches it as a fire-and-forget signal.
func Test_Approve_IsRefusedWhileAChangeRequestIsOpen(t *testing.T) {
	ps := task12RoundStore("designReview", "detailedDesign", projectstate.RoundPending,
		[]projectstate.ReviewComment{task12Comment("r1c1", "name the failure")})
	fc := &fakeTemporalClient{session: awaitingAt("designReview")}
	m := task12Manager(fc, ps)
	err := m.SubmitReviewDecision(testCtx(), "p", "A", "designReview", ReviewDecisionInput{Decision: ReviewApprove}, nil)
	if e := asConstructionError(t, err); e.Kind != fwmanager.FailedPrecondition ||
		!strings.Contains(e.Detail, "cannot approve: 1 review thread(s) still open") {
		t.Fatalf("want the design rail's own refusal, got %s %q", e.Kind, e.Detail)
	}
	if fc.lastSignalName != "" {
		t.Fatalf("a refused approve must not signal, got %q", fc.lastSignalName)
	}
	// RESOLVED, and the approve goes through.
	if err := m.SubmitReviewDecision(testCtx(), "p", "A", "designReview",
		ReviewDecisionInput{Decision: ReviewSetCommentStatus, CommentID: ptrTo("r1c1"),
			CommentStatus: ptrTo(projectstate.ReviewCommentResolved)}, nil); err != nil {
		t.Fatalf("the resolve must land: %v", err)
	}
	if err := m.SubmitReviewDecision(testCtx(), "p", "A", "designReview", ReviewDecisionInput{Decision: ReviewApprove}, nil); err != nil {
		t.Fatalf("an approve over a resolved thread must be accepted: %v", err)
	}
	if fc.lastSignalName != signalTaskDecision {
		t.Fatalf("the accepted approve must signal the gate, got %q", fc.lastSignalName)
	}
	// AN OPEN QUESTION DOES NOT BLOCK a human: doctrine makes it a soft warning, and the human is
	// the one being warned (ReviewCommentBlocksApprove). The AUTOGATE is stricter — see the case
	// above — because there is nobody there to warn.
	q := task12Comment("r1c2", "why this order?")
	q.Type = projectstate.ReviewCommentTypeQuestion
	withQuestion := task12RoundStore("designReview", "detailedDesign", projectstate.RoundPending,
		[]projectstate.ReviewComment{q})
	if err := task12Manager(&fakeTemporalClient{session: awaitingAt("designReview")}, withQuestion).
		SubmitReviewDecision(testCtx(), "p", "A", "designReview", ReviewDecisionInput{Decision: ReviewApprove}, nil); err != nil {
		t.Fatalf("an open QUESTION must not block a human approve: %v", err)
	}
}

// THE CHILD'S OWN RE-CHECK, DRIVEN AT A LIVE GATE (Task 12 round 3, F2). A decision signal that
// arrives past the façade's guard — the TOCTOU window, or any sender that is not the façade —
// must not decide a round with an open CHANGE REQUEST either.
//
// THE PREVIOUS SHAPE OF THIS CASE WAS VACUOUS and is worth saying so: it registered its
// callbacks at t=3s and t=90s on a walk that completed at workflow time ZERO, so neither ever
// fired, every round's thread was empty, and the assertion ("no passed round holds a blocking
// comment") was true of a walk in which nothing had been asked. Mutating the child's re-check to
// `len(open) > 99` left it green.
//
// What makes it real: the gate is genuinely LIVE when the approve arrives, because a change
// request is seeded on the round the instant it opens (seedCommentOnRound, the stand-in for the
// window a critic occupies for minutes in production) and an open comment HOLDS the autogate. The
// raw approve then arrives at a suspended gate, and the round must still be pending afterwards.
func Test_Approve_TheChildRefusesAnApproveOverAnOpenChangeRequest(t *testing.T) {
	rig, m := openCommentRig(t)
	// A CHANGE REQUEST — the kind that blocks an approve, human or not.
	rig.cs.mu.Lock()
	rig.cs.seedCommentOnRound = map[string]projectstate.ReviewComment{
		"srsReview": task12Comment("r1c1", "name the failure mode this covers"),
	}
	rig.cs.mu.Unlock()
	// STRAIGHT PAST THE FAÇADE, as a stale or hand-crafted signal arrives. The façade would
	// refuse this itself (Test_Approve_IsRefusedWhileAChangeRequestIsOpen); this is the child's
	// own re-check, which is what closes the window between the façade's read and its write.
	rig.env.RegisterDelayedCallback(func() {
		if !roundIsPending(rig.cs, shapeServiceID, "srsReview") {
			t.Error("the open change request must HOLD the gate; there is no live gate for the approve to be refused at")
		}
		rig.env.SignalWorkflow(signalTaskDecision, taskDecisionSignal{
			TaskID: "srsReview", Decision: ReviewApprove, DecidedBy: gateActorOperator,
		})
	}, 30*time.Second)
	// The approve was refused, so the gate is STILL held — and resolving the comment is what
	// releases it. Both halves in one walk, because "refused" and "wedged" look identical from
	// a round that never passes.
	rig.env.RegisterDelayedCallback(func() {
		if !roundIsPending(rig.cs, shapeServiceID, "srsReview") {
			t.Error("the child applied an approve over an open CHANGE REQUEST; its re-check did not fire")
		}
		if err := m.SubmitReviewDecision(testCtx(), "p", ActivityID(shapeServiceID), "srsReview",
			ReviewDecisionInput{Decision: ReviewSetCommentStatus, CommentID: ptrTo("r1c1"),
				CommentStatus: ptrTo(projectstate.ReviewCommentResolved)}, nil); err != nil {
			t.Errorf("the resolve must land: %v", err)
		}
	}, 90*time.Second)
	rig.env.ExecuteWorkflow(executionKindDeliveryActivity, deliveryActivityInput{
		ProjectID: "p", ActivityID: ActivityID(shapeServiceID), Activity: sampleActivity(),
	})
	shapeRequireCompleted(t, rig.env)
	if err := rig.env.GetWorkflowError(); err != nil {
		t.Fatalf("the walk must finish once the change request is resolved: %v", err)
	}
	// AND NO PASSED ROUND CARRIES A BLOCKING COMMENT — the original claim, now made about a walk
	// in which one was genuinely open at a live gate.
	row := rig.cs.execution(shapeServiceID)
	for _, r := range row.Reviews {
		if r.Outcome != projectstate.RoundPassed {
			continue
		}
		for _, c := range r.Thread {
			if projectstate.ReviewCommentBlocksApprove(c) {
				t.Fatalf("round %d at %s passed with comment %s still open", r.Round, r.TaskID, c.ID)
			}
		}
	}
}

// M1's GUARD: the kind a Manager write resolves a round by is the SAME one the child stamps on it.
// A construction task is kindless (its artifactKind names its work product, not a design slot);
// a design task's is its slot, and passing nil for one of the three kinds that SHARE
// `architectureReview` would resolve to whichever was written last.
func Test_RoundKindOfTask_AgreesWithWhatTheChildStamps(t *testing.T) {
	// THE COUNT IS PINNED, because "all fourteen lifecycles" is the claim and a loop over a
	// shorter list would make it vacuously true: a method-assets release that DROPPED a lifecycle
	// would leave this green while an entire activity type's rounds went unchecked.
	if got := len(methodassets.Lifecycles()); got != 14 {
		t.Fatalf("method-assets carries %d lifecycles, want 14 — this case's claim is about all of them", got)
	}
	for _, lc := range methodassets.Lifecycles() {
		for _, task := range lc.Tasks {
			if task.Kind != methodassets.LifecycleTaskReview {
				continue
			}
			want := roundArtifactKind(lc, task)
			got := roundKindOfTask(lc, task.ID)
			switch {
			case want == nil && got != nil:
				t.Errorf("%s/%s: the Manager resolved kind %v where the child stamps none", lc.Type, task.ID, *got)
			case want != nil && (got == nil || *got != *want):
				t.Errorf("%s/%s: the Manager resolved %v where the child stamps %v", lc.Type, task.ID, got, *want)
			}
		}
	}
	// And the one that matters: `architectureReview` is kinded, `codeReview` is not.
	arch, ok := methodassets.LifecycleFor("architecture")
	if !ok {
		t.Fatal("method-assets must carry the architecture lifecycle")
	}
	if got := roundKindOfTask(arch, "architectureReview"); got == nil {
		t.Error("a DESIGN review task's round is kinded — resolving it kindless would cross three kinds' rounds")
	}
	svc, ok := methodassets.LifecycleFor("service")
	if !ok {
		t.Fatal("method-assets must carry the service lifecycle")
	}
	if got := roundKindOfTask(svc, "codeReview"); got != nil {
		t.Errorf("a construction review task's round is KINDLESS; got %v", *got)
	}
}

