// F55 (Phase-2 twin): acknowledgeStale bypasses the stale gate — the seal proceeds to the
// Temporal start (mock errors → Infrastructure, not FailedPrecondition).
// THE PHASE-2 SEAL IS SYNCHRONOUS since stage 4b1 Task 13 (it started and immediately awaited
// Phase2AdvanceWorkflow before, which is a workflow whose whole life was this request), so both
// of these now assert the real answer rather than a mocked workflow start.
func Test_AdvanceToConstruction_StaleSlot_RefusedUnlessAcknowledged(t *testing.T) {
	pid := ProjectID(uuid.NewString())
	proj := committedPhase2Project(pid, KindPlanningAssumptions, KindNetwork)
	proj.PlanningAssumptions.StaleBasis = true
	m := &deliveryManager{projectState: &pdFakeProjectState{project: proj}}

	_, err := m.AdvanceToConstruction(fwmanager.Context{Context: context.Background()}, pid, false)
	if err == nil {
		t.Fatal("a stale committed slot must refuse the seal")
	}
	if got := asProjectDesignError(t, err).Kind; got != fwmanager.FailedPrecondition {
		t.Fatalf("stale-slot refusal kind = %v, want FailedPrecondition", got)
	}
	// ACKNOWLEDGED, the gate is bypassed and the seal runs — it then answers with the slots that
	// are still missing rather than an error, which is what the SPA renders.
	res, err := m.AdvanceToConstruction(fwmanager.Context{Context: context.Background()}, pid, true)
	if err != nil {
		t.Fatalf("acknowledging the staleness must bypass the gate: %v", err)
	}
	if res.Advanced {
		t.Error("this project has not committed every Phase-2 kind, so it must not advance")
	}
	if len(res.MissingArtifacts) == 0 {
		t.Error("an unsealed phase must NAME what is missing; an empty list is indistinguishable from a seal")
	}
}

func Test_AdvanceToConstruction_NoStaleSlot_ReachesTheSealGate(t *testing.T) {
	pid := ProjectID(uuid.NewString())
	proj := committedPhase2Project(pid, KindPlanningAssumptions, KindNetwork)
	m := &deliveryManager{projectState: &pdFakeProjectState{project: proj}}

	res, err := m.AdvanceToConstruction(fwmanager.Context{Context: context.Background()}, pid, false)
	if err != nil {
		t.Fatalf("with no stale slot the gate must pass through to the seal: %v", err)
	}
	if res.Advanced {
		t.Error("two committed kinds are not the whole Phase-2 list")
	}
	if len(res.MissingArtifacts) == 0 {
		t.Error("the seal must name the uncommitted kinds")
	}
}

